/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20181210-6","meetingId":"h30-cm12","date":"2018年12月10日","dateIso":"2018-12-10","committee":"区民委員会","time":"午前１０時００分～午前１１時４５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第９１号議案 臨海部広域斎場組合規約の変更","agenda":"第９１号議案 臨海部広域斎場組合規約の変更","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"確認なのですけれども、別表の建設経費で火葬場整備事業に係る用地取得費及び整備費の負担割合等の項目が定められていると思うのですけれども、今回、用地取得というのは発生するのか、私の認識では、北側駐車場に増設するということで用地取得はないと思っているのですけれども、別表に記載されている理由を伺います。今回の規約の変更で、利用者の利用料は上がるのかということを伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"利用料につきましては、今回この規約の変更に基づいて反映されるというものではございませんで、本年４月１日に使用料を改定させていただきましたけれども、そちらについては３年ごとにその時の状況を踏まえて利用料について検討するですので、今回は直接反映はいたしません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"用地取得費のところが将来的に必要かもしれないということでしたけれども、そうすると、またこの後も増築する可能性があるということなのか、見通しというのでしょうか、そこを伺いたいと思います。この間の利用実績で、１日の限度が２５件の受け入れだと思うのですけれども、この間、その日数の推移がどうなっているかというのがおわかりになればお答えいただければと思います。","respondent":"提坂戸籍住民課長","answer":"火葬炉増築に伴いまして増築の工事を行うわけですけれども、火葬炉は現行１０基ですけれども、２０６０年度までは、６基増築することによって対応できるということなので、当面は用地取得をする必要はないだろうという見込みですが。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"私が聞きたかったのは、１日の限度の受け入れ件数というのは２５件だと思うのですけれども、その２５件いっぱいだった日数が何日だったかというのをお聞きしたかったのですが、今わかりますか。","respondent":"提坂戸籍住民課長","answer":"何日かという形ではお答えできないのですけれども、稼働率としては、９０％程度はいっていると思います。","voiceIndex":13,"id":"exchange-003"},{"speaker":"のだて委員","kind":"意見","question":"私も増設に向けての報告書を見させていただいて、限度いっぱいの日数が増えてきているということでしたので、やはりこの増設というのは、今９０％というお話もありましたので、必要なことだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"素朴な質問で申しわけないような気もするのですが、利用実績割の定め方ですけれども、管理運営経費のところでは「当該会計年度」になっていて、建設経費のところになると「前３会計年度」となっているのですけれども、これは定め方にどうしてこういう違いが出てくるのかお教え願えればと思います。","respondent":"提坂戸籍住民課長","answer":"管理運営経費以外につきましては、負担割合が「前３会計年度」となっているということで、単年度の利用実績割合ということではなくて、一定の期間の利用実績を用いることで単年度の振れ幅を平準化した割合を用いしています。","voiceIndex":16,"id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"言ってみれば、建設経費みたいな固定的なものは毎年毎年出す必要もないだろうという感じですか。毎年毎年変動させていく必要はないというか。管理運営経費だと当該会計年度の利用実績ということになるから、言ってみれば毎年変動するわけですよね。ところが、建設経費は前３会計年度ということは、でも前３会計年度でも毎年変動するわけですか。","respondent":"提坂戸籍住民課長","answer":"管理運営経費というのは、毎年いろいろな修繕がありますので、年度によっては出っこみ引っ込みがありますので、それに基づいて、該当年度の利用実績割合をあん分するです。","voiceIndex":18,"id":"exchange-006"},{"speaker":"おくの委員","kind":"質問","question":"そのほうが３会計年度を平均した、でも３会計年度の平均というか、やはり毎年変わっていくのは変わっていくのですよね。微妙かもしれませんけれども。でも、平準化したほうが単年度でやるよりはいいというか適切だという判断があるのだろうと思うのですけれども、それはどういったことでしょうか。","respondent":"提坂戸籍住民課長","answer":"基本的には、毎年、各区の実績割合はそれほど大きな変動はございませんけれども、仮に突発的な事情によって、単年度だとほかの区が出っこみがあるとか、ほかの区が少なかったとか、そういうこともあり得ないとは言い切れませんので。","voiceIndex":22,"id":"exchange-007"},{"speaker":"おくの委員","kind":"質問","question":"そのほうが公正になるだろうということでしょうか。","respondent":"提坂戸籍住民課長","answer":"管理運営経費については、もう一回ご説明しますけれども、業務委託費とか人件費、その辺が毎年かかるのですが、それを該当年度ごとに支出した費用ということで、該当年度の利用実績割合をあん分に用いることといたしております。","voiceIndex":24,"id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"今日の規約の一部変更はよくわかったのですけれども、今どういう考えかというのが出ているならば教えていただきたいのですけれども、今は日本で年間大体１３０万人ぐらい亡くなっているわけですけれども、いわゆる団塊の世代が亡くなる年代に入ってくると、今日は臨海斎場のことですけれども、日本では年間大体１７０万人ぐらい亡くなる方が出てくることになるというか。","respondent":"提坂戸籍住民課長","answer":"亡くなる方についても、２０２９年度の段階で、今の火葬炉１０基では限界だという推測が出ておりまして、細かい数字は今手元にないのですが、それで来年度から着実に基金を積み立てていってそれに対応していこうということでございまして、６基増設することによって。","voiceIndex":26,"id":"exchange-009"},{"speaker":"大倉委員","kind":"質問・要望","question":"今のお話でいうと、１０基での対応が限界というところでいうと、限界の考え方を教えていただきたいのです。","respondent":"提坂戸籍住民課長","answer":"施設整備基本方針によりますと、２０２９年度までは、ぎりぎりのところで火葬炉１０基ということで対応は可能なのですけれども、それ以降になるともう厳しいだろうと。","voiceIndex":28,"id":"exchange-010"},{"speaker":"大倉委員","kind":"質問・要望","question":"ただ、９０％の稼働率というところでいうと、早めの対応というのが必要なのかなと思うのですが、その点についてもう一回改めて教えていただきたいのと、限界というところの考え方については、１００％超えて限界とか、難しいと思うのですが、１０年というところが何か、その２０２９年の限界というところとの関係が、そこで合っているというところなのですけれども。","respondent":"提坂戸籍住民課長","answer":"これが、これから１２年、１３年の計画で積み立てていくとなると、かなり厳しい部分がございまして、とにかく２０３０年度には少なくとも火葬炉を何基か増設する必要があるということで、１０年間の積み立てということで、計画を立てさせていただいたところです。","voiceIndex":32,"id":"exchange-011"},{"speaker":"大倉委員","kind":"質問","question":"例えば、ほかにも民間の火葬場とかがありますよね。その辺との関係とか、そこもかなりピークに来ているのか、そこが需要としてはまだ空きがあるのか、その総合的な判断というところが、今の話だと、なかなか出てこないというところでいうと。というところが、もう少しお話しいただけると分かりやすいかなと思っているのですが、いかがでしょうか。","respondent":"提坂戸籍住民課長","answer":"周辺の斎場というと、一番近いところでいうと桐ヶ谷斎場、ほかに渋谷区の代々幡斎場、あと新宿区の落合斎場とか、その辺が同じ運営会社によって経営されてありますけれども、その辺の細かい今後の推計は区のほうではつかめてないので。","voiceIndex":34,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問・要望","question":"今、大倉委員とのやりとりを伺っていてそうかと思ったのですけれども、稼働率はどういうふうに考えるかですよね。つまり何が言いたいかというと、品川区の方は臨海斎場を使うことが多いわけですよね。今、渋谷の話が出ていたけど、私たちが利用するのは大体、臨海斎場か桐ヶ谷斎場ではないですか。亡くなりました。と私は思っているのですけれども、そうでないなら教えていただきたいのですけれども。","respondent":"提坂戸籍住民課長","answer":"それで、なるべくお昼の時間に火葬をご希望される方が多いというのは事実として認識しておりますけれども、そこで空きがなければ何とかご理解をいただいて午前中とか午後に時間をずらしていただくとか、そういう形でやりくりをさせていただいているというのが実情です。","voiceIndex":36,"id":"exchange-013"},{"speaker":"藤原委員","kind":"質問・要望","question":"将来的に、２０６０年まで出ていますが、２０６０年ごろというか、先ほどもお話ししましたけれども、日本全体で１７０万人ぐらい亡くなるときに、日本全体で考えれば品川区も増えるわけではないですか。ただ、今の時代は直葬がだんだん増えてきたから、その時間帯でも、ご理解というか、臨海斎場のほうから９時に入れてください、９時半に入れてくださいと葬儀業者のほうに言うパターンが多いではないですか。","respondent":"提坂戸籍住民課長","answer":"正確な数字は把握してございませんけれども、斎場組合の職員と話をする中で出てくるのは、最高で１週間、平均すると２日から４日程度というような話は聞いておりますけれども、それをなるべく延ばさないように工夫してやってまいりたいと考えています。","voiceIndex":38,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問・要望","question":"最高で１週間と臨海斎場の方が言っているという感覚でいることは、やはり少し違うと思うので、だからそれを改善していってもらいたい、将来どうなるかというのを通じて出てくるわけですから、それに向かってやっていただきたいという希望があるだけなので、正確な情報をきちんととって、では将来どうしていこう、ああしていこうということを考えていくのが知恵ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-015"},{"speaker":"大倉委員","kind":"質問","question":"施設についてなのですが、今お話の中で火葬炉がメインなのかなというところで伺っていたのですが、ほかにも式場とか会葬者控室とか各３室ということで、何で３室なのかという考え方について教えてください。","respondent":"提坂戸籍住民課長","answer":"臨海斎場の控室については、組織区５区のそれぞれの事情とかもありますので、断言して申し上げることはできませんけれども、品川区の場合は、今ご指摘のとおり、車で１０分かからないところになぎさ会館がございまして、そちらのほうは利用率については余裕がありますので。","voiceIndex":41,"id":"exchange-016"},{"speaker":"大倉委員","kind":"質問","question":"これから需要が増えていく中でそういった控室も増やしていく、なぎさ会館に余裕があるからお互いうまく利用し合いながら進めていくというところで、一部事務組合なので品川区だけの問題で増やすとかというのはなかなか難しいのかもしれないのですが、近くにそういう式場があるところでいうと、何か品川区としても、そのなぎさ会館がだめとか言うのではなくて、効率的に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-017"},{"speaker":"渡辺委員","kind":"質問","question":"先ほど来、民間事業者のところ、桐ヶ谷をはじめ代々幡を含めて、その辺の動向よりも、これまでの臨海斎場の推移や経緯でいろいろ判断されているような趣旨のご答弁がありましたが、本当にそうですかという意味で。そういう意味で、整理をすると、どうやって現状の課題を発信していくか、その辺のタイミングのところ、それとその根拠のところで民間の動向の捉え方、その辺を教えてください。","respondent":"提坂戸籍住民課長","answer":"「他斎場の動向や事業環境の変化等を注視しつつ、必要に応じて２０２４年度～‘２５年度に精査・見直しを検討することとする」と確かに記載していますので、他斎場の動向についても。","voiceIndex":44,"id":"exchange-018"},{"speaker":"渡辺委員","kind":"質問","question":"それが１つ。それと、アクセスも含めたときに、では料金のところでどうやって配慮がされていくか、この辺のところは民間の動向もしっかり把握しないと何とも言えないと思うのです。今問題ないですが、将来的に進めていけばいいだけの話ではないような気がしているので、現在もその辺、十分把握されているのかどうかだけ教えてください。","respondent":"提坂戸籍住民課長","answer":"施設利用料につきましては、先ほどもご説明申し上げたのですが、３年ごとに見直しを図るということで、その中で民間斎場との兼ね合いというか比較もありますけれども、仮に改定して値上げとなった場合でも民間斎場よりは低廉な料金で利用できるということを前提に。","voiceIndex":46,"id":"exchange-019"}]},{"id":"topic-02","title":"目黒川みんなのイルミネーション２０１８ 冬の桜R)ウインターコンサートの開催","agenda":"目黒川みんなのイルミネーション２０１８ 冬の桜R)ウインターコンサートの開催","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"あわせて実施主体のところで、今回は品川区と目黒川みんなのイルミネーション実行委員会との共催ということですけれども、この間もいろいろイベントの報告等ありましたけれども、どういった場合に区の主催でやるのか、どういった場合に実行委員会形式でやるのか、基準というのでしょうか、条件というのでしょうか、そういったものがあったら教えていただければと思います。","respondent":"立川文化観光課長","answer":"経緯ですが、目黒川みんなのイルミネーションについては９年前から実施しています。３年前より品川区も参加いたしまして、全体で２.２キロにわたって目黒川のイルミネーションを実施しています。","voiceIndex":60,"id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"少し確認をさせていただきたいのですけれども、目黒川みんなのイルミネーションは、冬の桜ということで廃油を利用したイルミネーションだったと思うのですけれども、今回もそうなのかということをまずお聞かせください。","respondent":"立川文化観光課長","answer":"今回もイルミネーションの発電につきましては、周辺地域から廃油を回収いたしまして、それをもとに発電しているものです。","voiceIndex":64,"id":"exchange-021"},{"speaker":"田中委員","kind":"意見","question":"９年前からと先ほどお話がありました。チラシにそのことが一言も書かれてないのです。これは廃油で行っているイルミネーション、地域が育ててきたものという観点からも、ここはとても重要なのではないかと思って、品川区としても、廃油を使ったリサイクルというか、そういう面をもっとアピールすべきだったのではないのかと思うのですけれども、そこのところをお聞かせください。","respondent":"立川文化観光課長","answer":"ただ、イルミネーション自体のイベントにおいては、廃油についてアピールさせていただいていますけれども、今回はイルミネーションの中でコンサートをやるということなので、特に記載していないということですので。","voiceIndex":66,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ、チラシのほうにも、小さくてもいいので、地域の方たちが育ててきたイルミネーションなので、ぜひ記載をしていただきたいなと思うのと、あと、すみません、少しお話が変わって予算額なのですけれども、予算額の内訳を教えてほしいです。","respondent":"立川文化観光課長","answer":"出演料につきましては大体８０万円ぐらい、ステージの設営および音響関連につきましては１３４万円、照明および進行関連につきましては大体６０万円、会場関連につきましては３０万円、その他告知関連につきまして２７万円プラス消費税です。","voiceIndex":69,"id":"exchange-023"},{"speaker":"大倉委員","kind":"質問・要望","question":"改めて目的を教えてください。この日程についても、なぜこの日になったのか教えていただきたいと思います。","respondent":"立川文化観光課長","answer":"日時につきましては、イルミネーションの開催期間ということで１２月１５日を選定したものです。","voiceIndex":71,"id":"exchange-024"},{"speaker":"大倉委員","kind":"質問","question":"目的はコンサートを開催することになるのですか。そのコンサートを開催して、その後どういったものにつなげるとかというところが目的なのかなと思うので、改めて教えてください。","respondent":"立川文化観光課長","answer":"狙いといいますか、そういった観点からお話ししますと、まず五反田の水辺地域について区内外にアピールしていきたいということが第一点です。それから、文化と観光を連携してやはり区内外にアピールしていくです。","voiceIndex":73,"id":"exchange-025"},{"speaker":"大倉委員","kind":"質問","question":"なのに、この時間帯が早いのではないかと思うわけです。イルミネーションとこのコンサートというところでは、もう少し時間が遅いほうがよりきれいなのかなと思うのですが、その辺の考え方。宣伝費なのですが、先ほど２７万円というところで、お金のかけ方については、どこまで宣伝をしっかりしていくかというのも大事なのかなというところでは、何かその広報について工夫があれば教えてください。","respondent":"立川文化観光課長","answer":"１２月１５日になった理由も、そういった開催に関係する実行委員会の方々のご意見をまとめたところ、この日がいいだろうということになりましたので、実施時期については、１２月は寒いというところがありますので。","voiceIndex":75,"id":"exchange-026"},{"speaker":"渡辺委員","kind":"質問","question":"今のに続いてというニュアンスで聞かせていただこうと思います。来場者を何人で成功と見るのか。となると、この場所もそうなのですが、では椅子をどのぐらい用意するのですかというのもあわせて教えてください。ただ、広告宣伝費について、ポスターなのかチラシなのか駅張りなのかも含めて教えてほしいのと、規模ですね、どのくらい告知、チラシであれば幾らなのか。その辺を参考までに教えてください。","respondent":"立川文化観光課長","answer":"集客につきましては、場所も限られているところですので、以前、「目黒川夜市」といって、これは８月のイベントですけれども、ミュージックライブステージというのを同時に開催したというものでございまして、そういったコンサートの開催実績とかもありますので、今回。","voiceIndex":77,"id":"exchange-027"},{"speaker":"渡辺委員","kind":"質問","question":"だから、そういう意味で、今ある程度の人数とかお聞きしましたが、私はあまり高く設定しなくてもいいと思うのです。こういった地域と行政が一体となった行事が２０２０年に向けて、あるいは、その後も、大なり小なり各地域で芽が出て展開されることが理想だと思っています。では今後、区全体で、翌年さらにその先、明確なものではなくても、理想を含めておありだったら教えてください。","respondent":"立川文化観光課長","answer":"２０２０年というのを１つの目標に実施していますけれども、観光であるとか文化芸術というのは、その後も区民の方、または区外からいらっしゃる方に対して、品川区として積極的に取り組むことによって皆さんに満足していただきたいという思いがありますので、今やっていること。","voiceIndex":79,"id":"exchange-028"}]},{"id":"topic-03","title":"品川区施設予約システムのリニューアル","agenda":"品川区施設予約システムのリニューアル","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"確認なのですけれども、先ほど少しご説明があったかもしれないのですが、区のホームページとか予約システムを見ると、１月４日から新システムになるというふうにお知らせされているのですけれども、今回は３月中旬ということで、３月中旬からが正しいということでいいのかということを確認させていただきたいと思います。","respondent":"池田スポーツ推進課長","answer":"システムのリニューアルですけれども、３月中旬ということで、本日の委員会のご報告終了後に訂正できるものについては全て訂正する予定になっているところです。","voiceIndex":85,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"新システムを委託する事業者はどこなのかということもお伺いしたので、お願いします。","respondent":"池田スポーツ推進課長","answer":"新システムについて契約している事業者につきましては、ＮＥＣソリューションイノベータという会社です。","voiceIndex":87,"id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"ここもシステム開発の同系統の会社だということですよね。わかりました。これは要望なのですけれども、現在のシステムですと、貸室を借りようとするときに、きゅりあんとスクエア荏原が別に出てくると思うのですけれども、リニューアルする際に、貸室としても同じものなので一緒に見られるようにしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"こういったことも、今度は私どもの施設のほうに入ってまいりますので、そういったものをあわせて目的ごとに部屋の空き状況が確認できるようにということで今検討しています。支払い状況につきましても、口座引き落としということもいろいろな面で検討しています。","voiceIndex":89,"id":"exchange-031"},{"speaker":"のだて委員","kind":"質問","question":"今ご説明があった検索の仕方のところは、この変更点に書いてある施設検索機能の拡大のところのご説明だったということでよろしいですか。新システムになって目的別でできるようにということは、改めてになりますけれども、きゅりあんとスクエア荏原も一緒に見ることができるようになるということでよろしいのか伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"施設検索機能の拡大ということで、先ほどの目的別、日にち別ということが加わる、新しいものが加わってくるという説明をさせていただきました。","voiceIndex":91,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"一番最初の説明のときに、今のシステムだと不具合があるというご説明があったと思うのですけれども、そこのところをもう一回、不具合の内容を教えていただきたいのと、１月４日からの予約システムからはその不具合はなくなって、さらに３月の中旬からはリニューアルがされるというということなのか、今の不具合の部分は１月４日から３月中旬までは継続されるのかというところをお知らせください。","respondent":"池田スポーツ推進課長","answer":"今あるシステムにつきましては、３月のリニューアルをするまではそのまま継続してご利用していただくことになります。","voiceIndex":93,"id":"exchange-033"},{"speaker":"田中委員","kind":"確認","question":"利用者の方にとっての不具合が発生しているということですか、それとも、事業者間での不具合が発生しているのかということを確認したいのですけれども、お願いします。","respondent":"池田スポーツ推進課長","answer":"新しいシステムについて、１月４日にもしそのままリニューアルした場合には、不具合が生じるということが判明しましたので、そこについての復旧をするのに２カ月延期をするということでございまして、現在のシステムというのはそのまま３月まではご利用していただけるですので。","voiceIndex":97,"id":"exchange-034"},{"speaker":"田中委員","kind":"確認","question":"確認なのですけれども、利用者にとっての不具合が発生してしまうので、３月から新しくリニューアルされるというのはわかりました。その１月から３月にかけて利用者の方にとっての不具合が発生してしまう可能性があるのかないのかを確認したいのですけれども。","respondent":"池田スポーツ推進課長、安藤文化スポーツ振興部長","answer":"１月から３月までは、現在のシステムをそのまま使いますので、利用者にとって不具合が生じることはございません。利用者にとってはそのまま使えますので、何も変わりません。移行データが非常に多いわけなので、そこに点検点検で、検証検証しながらやっていく中で、１月４日で大丈夫だと進めてきたのですけれども、新たなミスが見つかって少し遅れますです。","voiceIndex":99,"id":"exchange-035"},{"speaker":"田中委員","kind":"確認","question":"今のご説明でわかったのですけれども、とにかく私が聞きたいのは、利用者の方にとっての不具合が発生しないですよねということの確認を最後にさせてください。","respondent":"池田スポーツ推進課長、安藤文化スポーツ振興部長","answer":"３月に行われるリニューアルにつきましては、利用者にとって不具合がないように進めてまいります。利用者の方々にとっては、一切不具合はありません。どの期間もありません。","voiceIndex":102,"id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"経緯を読ませていただいて、まず、スポーツ推進課長としてお伺いしたいのですけれども、品川区のスポーツは、いつでも、どこでも、だれでも……、何でしたっけ、４つの。教えてください。","respondent":"池田スポーツ推進課長","answer":"私ども品川区のスポーツ施策にとりましては、「いつでも、どこでも、だれでも、いつまでも」ということでやらせていただいているところでございまして、予約システムにつきましても、こちらをつくるときに。","voiceIndex":105,"id":"exchange-037"},{"speaker":"藤原委員","kind":"質問・要望","question":"私は３つでいいと思うのです。これを目標にやっていっていただきたいと改めて思うのですけれども、４つも書いてあるのですから。区民の方に迷惑というか、区民の方が迷ってしまうとかできないということではないということなので安心しておりますが、課長、この４つをこういうふうにうたっているわけですから、今後のシステムについてどうなっていくか、どうしていきたいか、改めてご答弁いただけますか。","respondent":"池田スポーツ推進課長","answer":"「手間なく」ということで、今回利用者の方が求めているタッチ数を少し減らすこともやらせてもらいますし、また、色覚に障害をお持ちの方にも対応できるようなこともしますので、そういったことではいろいろな方を対象にやっていくということ、それと。","voiceIndex":107,"id":"exchange-038"},{"speaker":"藤原委員","kind":"質問・要望","question":"一つ一つ伺うと、改めて言葉に合った施策をしているのだと思うのですけれども、「手間なく」と「かんたんに」がごっちゃになってしまっている感じが今の答弁で思ったのですけれども、課長、とにかく、「いつでも」「どこでも」「手間なく」「かんたんに」というシステムができて、区民の方々が本当に「手間なく」「かんたんに」できるシステムをこれからもつくっていっていただきたいと考えていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-039"},{"speaker":"田中委員","kind":"確認","question":"もう一つ確認なのですけれども、現在は引き落としのところでちょっとしたトラブルがあったとさっきご説明があったと思うのですけれども、その引き落としでのトラブルは、利用者の方がトラブルに遭ってしまったのか、それとも区と事業者の間でだったのかというところを確認させてください。","respondent":"池田スポーツ推進課長","answer":"日立からＮＥＣに移るいろいろな作業を履行していくわけですけれども、その際にシステムのちょっとした不具合が見つかって、そのままやってしまいますと利用者の方に口座引き落としの場面でお手間をかける可能性があるというところで。","voiceIndex":110,"id":"exchange-040"},{"speaker":"おくの委員","kind":"質問・要望","question":"今まで使っていたときにその辺ができなかったので、一々何とか区民集会所の部屋を全部見て、設備は何が使えるのかを今度は電話で問い合わせてということを一々やらなければいけなかったので、そこが一挙に今言ったように検索機能からできれば本当にありがたいなという感じがしますので、質問プラス要望、その辺まで考えられているのでしょうか、考えられていたらありがたいですし、考えられていなかったら。","respondent":"池田スポーツ推進課長","answer":"もう一つ、施設の細々とした、磁気ループもしくはプロジェクターやＯＨＰ、カラオケとか、そういった細かいところまではまだ、表示はありますが検索まではできてないと思いますので、その辺についてご要望として、すぐ対応できるかということになりますと、システムそのものが。","voiceIndex":112,"id":"exchange-041"},{"speaker":"おくの委員","kind":"質問・要望","question":"私の使った実感として、それがあればなというのが非常にあったもので、とにかく強い要望としてお伝えしておきますので、今後もそういうことを念頭に発展させていただければなと思います。１０名の部屋なら、ざっと品川区内から検索されるという。だから、定員とか、プロジェクターとか磁気ループ、あるいはカラオケとか、そういうので検索できるようなシステムを、少なくとも目指していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、設備とかの話は表示があるというお話だったのですけれども、そこの確認と、何が表示されるのかを教えていただきたいです。","respondent":"池田スポーツ推進課長","answer":"何がというところでは、今そこを詰めているところです。施設につきましては６０施設ございまして、会議室とか集会室の数を数えると２００以上あります。全部を今確認していますので、どのような表示になるかというのはまだはっきりとしてないところです。","voiceIndex":115,"id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2826#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":29200,"voices":121}},{"id":"h30-20181210-7","meetingId":"h30-cm12","date":"2018年12月10日","dateIso":"2018-12-10","committee":"厚生委員会","time":"午前１０時００分～午後 ２時１７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を84件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第８３号議案 品川区立障害児者総合支援施設条例","agenda":"第８３号議案 品川区立障害児者総合支援施設条例","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今回の施設の設置条例なのですけれども、これまでの流れの中でちょっと確認をさせていただきたいと思います。私も途中まで出ていたのですけれども、そのときの状況で、４月から入りたい方のご相談が結構あったのと、クリニックの部分についてのご相談があった。そこら辺で帰ってしまったもので、その説明会での状況を先にご説明いただけますでしょうか。","respondent":"飛田障害者施策推進担当課長","answer":"１１月に区民向けに、この施設がおくれてスタートが１０月になるということで、その説明会をいたしました。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"確認","question":"それを後で聞こうと思っていたのだけれども、先にその説明会の中で、クリニックの相談事が結構入ってきたところで、そこまで聞いていて帰ったのですけれども、その辺、逆に今の話になっていくと、そのときの説明会の状況と今度変わってきますよととっていいのか、そこは全く変わらないでいいのですよという状況になっているのか、そこら辺のところになってくると思うのですけれども。","respondent":"飛田障害者施策推進担当課長","answer":"今回、クリニックは指定管理にはしませんけれども、今まで同じように４つの法人とまた連携しながら、事業のほうは変わりなく行うということには変更はございません。","voiceIndex":9,"id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問","question":"自分が聞いていた範囲では、指定管理という言葉は当然その説明会の中にはなかったから、その辺は問題ないと思うのですけれども、そこら辺、もう少し後からもう一回聞きますが、全体的に説明会の中での話としては、皆さんご了解いただいたというふうに判断しているのでしょうか。大体の合意を得られたかどうか、対応について皆様理解していただいたかなということで、その辺はどうなのでしょうか。","respondent":"飛田障害者施策推進担当課長","answer":"今回説明会をやらせていただきまして、お話をさせていただいたところです。やはり楽しみにしていたという話、続けてまた１０月からどのようになるのかという話も出ておりました。","voiceIndex":11,"id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"確認","question":"説明会について、大体わかりましたので、今度条例の関係ですけれども、指定管理が出てくるので、前の７月の説明の中では４つが指定管理の対象になるということでしたけれども、これでいくと、では３つ指定管理を受けてという方向に流れが変わってくるのか。決定はまだ後ですけれども、医療がなくなって、３団体でこれから進んでいくのかということで、確認なのですが。","respondent":"飛田障害者施策推進担当課長","answer":"今回条例を策定しまして、予定では指定管理者候補が３つの法人となりますので、３つの法人と個別に協定を組んでいくという予定です。","voiceIndex":13,"id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"確認","question":"７月の段階で医療系が入ってくる、決算特別委員会でもちょっとその確認をさせていただいた中で、やはり医療系の問題というのは少し質問させてもらったのですけれども、それが変わってきたというのは、さっき言ったやはり実績という問題だけなのか、その辺はどのように判断したらいいのかわからないのですが。","respondent":"飛田障害者施策推進担当課長","answer":"相談や適正な薬の処方がされていないとか、そういう問い合わせがあった場合、医療系サービス全般にわたって正しい判断が区にはできないということで、指定管理者制度での実施が困難と判断いたしました。","voiceIndex":15,"id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"意見","question":"医療系を別の指定管理者が運営するという形になるわけですね。流れとしては法人同士の関係だけれども、区は全体を管理する立場として大丈夫なのかなというのが、今聞きながら引っかかったのですけれども、そこら辺はどのように感じていますか。","respondent":"飛田障害者施策推進担当課長","answer":"今回、医療のところでは児童精神の方を入れて話を進めていまして、児童のところでは児童学園の相談機能のところも非常に課題になっておりまして、そういうことでまた連携を図っていきたいと考えております。","voiceIndex":17,"id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"意見","question":"お金の話というのは、逆に区とではなくて、その指定管理を受けた法人と別の法人がその医療を運営するわけですね。だから区は直接ではないけれども、法人間の問題も絡んでくると思うのですけれども、そこら辺は区として何か管理しないでいいのかということです。","respondent":"飛田障害者施策推進担当課長","answer":"今回３つの法人と別々に協定を結びますので、区としてもモニタリング等で確認していきたいと考えております。","voiceIndex":19,"id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問","question":"要するにＡというところの法人が指定管理を受けたと。そこが医療系も管理しますよということになってくるのでしょう。その中でのお金の、別々の法人が２つの事業をひっくるめて、その中に医療が入っていて、そこの流れというのはちょっと何か、向こうの問題だからいいのかなと受け取ってしまうのか、これも区が管理しなければいけないのではないですか。","respondent":"飛田障害者施策推進担当課長、松山障害者福祉課長","answer":"別々といいましても、今までどおり各法人連携をとっていきます。ただ、お金の流れとしては個別となります。ですから、それぞれ３つの法人とは別々に協定を結び、医療系サービスにつきましては、一つの法人が区の建物の中で独立して実施するということになります。","voiceIndex":21,"id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"意見","question":"そこはわかりました。ではもう一つ、フリーユニティーという一般社団法人をつくりました。区は指定管理は３カ所とやりますけれども、そことその３つがフリーユニティーという法人を持っていて、そこに対するお金の流れというのは、やはり問題も絡んでくるのではないかと思うのですけれども、当然区は指定管理のお金しか出さないのでしょうけれども、その辺の管理体制はどのようになっているのかなということ。","respondent":"飛田障害者施策推進担当課長","answer":"区はあくまでも３つの法人と指定管理の協定を結ぶ予定であります。向こうの法人がつくっている一般社団法人とは、特に区は協定を結びませんので、そちらのお金の流れとか、そういうところはないように、こちらのほうでも見ていきたいと考えております。","voiceIndex":24,"id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"確認","question":"今度図面で細かいところなのですけれども、図面を見ながら思ったのは、この図面の形が６階の管理事務所だけ違うので、その関係かなと思うのですけれども、６階の真ん中辺の黄色いところに、ちょっと細かい字で「だれでもトイレ」と書いてあって、１階から５階までは何でないのかなと思ったのだけれども、まさか６階にだけだれでもトイレがあるということではないよねというその辺の確認です。","respondent":"飛田障害者施策推進担当課長","answer":"５階も肢体不自由の方などが入られる予定ですので、４カ所、ちょっと多めに予定していまして、生活介護と書かれている下の医務室の下にトイレマークがありますけれども、そこに設置しております。真ん中辺に食堂と書かれていまして、その左側のところもだれでもトイレ。","voiceIndex":26,"id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"確認","question":"丁寧にありがとうございました。当然どこかにいっぱいあるだろうと思っていたけれども、ここだけだったので、ちょっと図面上気になったので確認をさせてもらいました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、どのような施設になるのかというのを中心に伺いたいと思うのですけれども、今年の１月２２日の厚生委員会で出された資料で、改装イメージということで、地下が医療系サービスで、１階が地域活動支援センターでと色分けで出していただいた図があるのですけれども、ここにそれぞれ生活介護だったり短期入所、日中一時、放課後等デイサービス。","respondent":"飛田障害者施策推進担当課長","answer":"ただ、今回施設開設延期ということになりましたので、その間のところ、例えば今回こみゅにてぃぷらざ八潮をお借りしてということになりますので、そこの施設の大きさによっても受け入れが限られますし、また児童学園の部分でも定員は本来４０人と言っていたところですが。","voiceIndex":29,"id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"施設のキャパ等もあると思うのですけれども、この定員にした根拠等々があれば伺いたいです。次に、今日いただいた資料の中の事業のサービス内容についての施設の区分のところの２番、障害者生活支援センターということで、障害者相談支援事業と特定相談支援事業と一般相談支援事業があると思うのですけれども、この特定相談支援事業の中に児童も入るのかを伺いたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"そういうところも鑑みて、定員を１０名増やしたところです。今度の相談のところに児童も入るのかというところについては、児童も含まれております。ただ、先ほど区のほうがそっくりそのままということではなく、一部をというふうに考えてあります。","voiceIndex":31,"id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、児童の障害児の指定特定相談は、この総合施設でもできるし、区でもやるということで、２カ所になるということでしょうか。","respondent":"飛田障害者施策推進担当課長","answer":"はい、そのように考えております。","voiceIndex":33,"id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それと、３番の訪問系サービスなのですけれども、障害者の訪問系のサービスというのは、今までも区でやられていたのか、ちょっと確認をさせていただきたいなと。訪問系のサービスを区内でやるのは初めてなのではないかとちょっと思ったものでそこの確認と、あと、この訪問系も含めてですけれども、区内どこまでの範囲、区全体を対象にするのか、対象地域があるのかを伺いたいのですが。","respondent":"飛田障害者施策推進担当課長","answer":"実際今までもやっていたのと変わりはないのですけれども、受けてくれる事業所というのは非常に少ないというのが現状です。今回、区内でサービスを行っていく予定です。","voiceIndex":35,"id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"区に在住の障害を持たれている方が、訪問系サービスを受けていたかもしれないのですけれども、区内にその事業所があったということでいいのでしょうか。それを伺いたいと思うのです。","respondent":"飛田障害者施策推進担当課長","answer":"実際今、その支援をしてくださる法人がいないということが実情でありまして、今回新たにこちらのほうで行うということです。","voiceIndex":37,"id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、すごく広がるのかなと思うのですけれども、その訪問系サービスの対象地域も伺ったので、教えてください。","respondent":"飛田障害者施策推進担当課長","answer":"一応品川区内というところで、自転車で移動するという前提で考えております。","voiceIndex":39,"id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうですか、わかりました。それで、もう一度１月２２日の資料のところでは、２階に在宅介護支援センターとヘルパーステーションが入ると図で示されていたのですけれども、この在宅介護支援センターは今回のこの図面の中にはないですけれども、どうなったのか伺いたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"今のところ在宅支援センターは、今のままのところでやるということで考えておりますので、今回は図面から落としております。","voiceIndex":41,"id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"確認","question":"わかりました。そうすると、先ほどもちょっと医療系サービスのところでいろいろお話があったと思うのですけれども、確認をすると、場所を貸すということでいいのですね。この診療所がここで区に賃料を払って、ここの場所で診療をするということで、独立採算になっていくということでいいのでしょうか。","respondent":"飛田障害者施策推進担当課長","answer":"基本的には医療系のサービスのところについては独立採算ということになります。とはいえ、こちらのほうは今ちょっと言いましたように、児童精神科というところでは児童学園との連携も必要になりますので、そこのところについては必要に応じて援助等も考えております。","voiceIndex":43,"id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。ですので、もうちょっと利用対象者や地域、またその利用対象者の団体とか障害者の方々や家族、そういった方々にまだまだ丁寧な説明が必要なのではないかと思うのですけれども、この説明についてはどのように考えているでしょうか。","respondent":"飛田障害者施策推進担当課長","answer":"今回１１月に区民に向けて説明会を行ったところです。今度１０月開設になりましたけれども、４月以降、春ぐらいに新たにまた説明会を開く予定です。","voiceIndex":45,"id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問","question":"本当に期待されている施設であるというのと同時に、地域の理解と、それから利用者の方々が安全安心に利用できるというところを小まめに丁寧に説明していただけたらと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ちょっと今気になったのは、これで設置条例を制定して、指定管理者の指定は当初は来年の第１回定例会で予定ということだったのですけれども、開設は１０月になるということは、その辺の指定管理者の指定の時期というのはどのように変わってくるのか。","respondent":"飛田障害者施策推進担当課長","answer":"第１回定例会で考えております。施設条例の施行は、先ほど説明したとおり、１０月１日と考えております。","voiceIndex":48,"id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"この公布の日というのはいつなのかということと、こみゅにてぃぷらざ八潮で仮設をやるということなのですけれども、仮設をやる事業というのは改めて何なのかということと、そうすると指定管理を結ぶのはどの事業者で、第１回定例会で指定管理者が出てくるということになると思うのですけれども、それで４月から指定管理を結ぶのはどの事業者になって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"この設置条例の公布日というのはいつになるのでしょうか。それと、指定管理者として指定管理が開始されるというのは、１０月１日ということでいいのか確認いたします。","respondent":"飛田障害者施策推進担当課長","answer":"平成３１年１０月１日から施行です。","voiceIndex":53,"id":"exchange-024"},{"speaker":"若林委員","kind":"提案","question":"地下１階の診療所の部分は、この条例の中でどのような理解をしたらいいですか。この総合施設という施設の条例が今回提案をされて、事業があってフロアもしっかりこれはここに対応しているとあるのですけれども、診療所はこの条例の中には、私は出てきていないのかなと読んでしまったのですけれども、そこら辺の位置づけを。","respondent":"飛田障害者施策推進担当課長","answer":"今回の条例には、その地下１階の医療系サービスのところは入っていません。","voiceIndex":55,"id":"exchange-025"},{"speaker":"若林委員","kind":"質問","question":"施設の条例なので、さっき質疑で医療系の部分はこういう形でとありましたけれども、それは条例には本来入れるべきものではないのですか。","respondent":"飛田障害者施策推進担当課長","answer":"現在そこの地下１階のところでは、区としましては行政財産の使用許可というところで考えております。","voiceIndex":57,"id":"exchange-026"},{"speaker":"若林委員","kind":"質問","question":"ということで、この施設条例には入れなくていいと、ほかの条例もそのようになっているという理解をしようと今思っているのですが、見解を伺います。","respondent":"飛田障害者施策推進担当課長","answer":"そのとおりです。行政財産の使用許可にて行いたいと考えております。","voiceIndex":59,"id":"exchange-027"},{"speaker":"若林委員","kind":"確認","question":"一方で、やはり半年おくれた最大の理由が施設の建設に係るもので、そうするとこれは主に地域・近隣の方にちゃんとわかっていただかなくてはいけないという事柄になると思うのですけれども、そういう意味では地域での説明会というのは、町会長にお話をするということは通常あるのかもしれないのですけれども、この辺は今まであったのか、今後どうされるかをちょっと確認しておきたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"地域に関しましては、今のところは広くビラを配って、また児童学園に近いところには一軒一軒対応していく考えです。","voiceIndex":61,"id":"exchange-028"},{"speaker":"若林委員","kind":"質問","question":"工事の配慮とか、区民からすればご迷惑ということで、そのポスティングと個別の説明で果たしていいのかなという、うちの会派にも、やはりここの地域でいろいろな方のお話を伺っている議員もいますので、地域センター等でしっかりと皆様一堂に会して、希望者に来ていただいて、同じ説明で質疑を受けるということで。","respondent":"飛田障害者施策推進担当課長","answer":"現在のところでは、地域で集会所を借りて行うということは予定しておりません。ただ、やはりポスティング、また一軒一軒丁寧にお伺いして説明したいと考えております。","voiceIndex":63,"id":"exchange-029"},{"speaker":"若林委員","kind":"確認","question":"先ほどの説明ですと、いわゆる個別の説明をさせていただいて、ポスティングで、私の質問に対しては特にやる予定という言葉は一切なかったのですが、元々そういう計画があったという、これからやりますという考え方を持っておられたのですねという確認を。","respondent":"飛田障害者施策推進担当課長","answer":"工事担当の施設整備課と相談しまして、検討させていただければと思います。","voiceIndex":67,"id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、改めてちょっと確認させていただきたいのが、今度のこの設置条例が実際に開始するのが１０月だということを受けて、こみゅにてぃぷらざ八潮で仮設で一部事業を実施されるということなのですけれども、改めてそこで実施される事業というのは、４番のアとイということで確認させていただいていいでしょうか。それと、人数としてはどれぐらいなのかも教えていただきたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"施設の説明会の周知は、前回と同じように、広報やホームページとか、そういうところに載せようと考えております。それと、仮設で実施する事業は基本的には生活介護と就労継続支援Ｂ型の対象の方をと考えております。","voiceIndex":69,"id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もう一つ、先ほどの医療系サービスなのですけれども、それもずっと指定管理者ということで今まで来たと思うのですけれども、それが今回指定管理者ではないということになっていったと思うのですけれども、そういうのは、もちろん事業者は了解済みということでよろしいのでしょうかという確認もさせてください。","respondent":"飛田障害者施策推進担当課長","answer":"アとイのところですが、１０名、１０名ではなくて両方合わせて１０名と、部屋の大きさから考えてそのように考えております。","voiceIndex":71,"id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"これは設置条例ですけれども、それが１０月に開始が延びるということでさまざまな問題が起こっているということなのですけれども、１０名前後というと職員の配置は何名くらいになるのでしょうか。これは本当に受ける事業者側の責任ではなくてこういう状況になったわけですから、そこら辺のところはしっかりと対応が必要だと思うのですけれども。","respondent":"飛田障害者施策推進担当課長","answer":"先ほど１０名前後というのは、現在利用の話し合いをしている中で、保護者の希望等でそういう１０名前後かなというところで、今、対応しているところですが、そこのニーズ等もみて事業者とも今後相談しながら決めていきたいと考えております。","voiceIndex":73,"id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"この１０名前後というのは希望者があって、事業者ももう職員も確保しているということであれば、ここでは４０名・２０名というのが元々の計画だと思うのですけれども、そこまで増やせるのか、また事業者が職員を確保した分、希望者があれば増やせるということで考えていいのか。確保した職員に対しての補償という点については、区としてどう考えられているのかというところはどうでしょうか。","respondent":"飛田障害者施策推進担当課長","answer":"事業者の補償というお話がありましたけれども、そこは各事業者においてその金額を挙げていただきまして、その金額を適切にこちらのほうでも判断しながら考えていく必要はあるかなと思います。","voiceIndex":75,"id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"もう本当に事業者の責任ではなく、こういう半年おくれという形になったことに対して、区としてはそこのところが事業者と話し合いをしながらということになると思うのですけれども、きちんと補償はしていくということで確認させていただいていいでしょうか。それをお願いします。","respondent":"飛田障害者施策推進担当課長","answer":"延期してしまったというところもありますので、そこはまた法人とも話し合いながら、適正な対応をしていきたいと考えております。","voiceIndex":77,"id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もっと質問をしながら、しっかりとこの施設がどのような施設なのかということを聞いていきたいというのは、当事者からは本当に強く思われていることなのではないかというのを私はこの間の説明会で強く感じたところですので、ぜひ広報やホームページにとどまらせないで、４月をまたずに説明会をぜひしていただきたいということで、強く要望をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"自民党としては、この障害児者総合支援施設は元々望んでいた施設です。ここまで来てうまく立ち上がってきた、条例自体は賛成するのですが、先ほど来、今までの流れでいろいろありました。その辺の説明を皆様にすると同時に、区の中でももう少し整理しておいてもらいたいというところも感じますので、それは要望としながら賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-037"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、この今出されている資料の別紙２の選考基準で点数はつけられているのかどうか伺いたいのと、あと、この選考基準の中に、人材配置、職員配置とか、あとは職員研修といった項目がないと思うのですけれども、入っていないのはなぜなのか伺いたいと思います。","respondent":"大串福祉計画課長","answer":"人員配置の関係、研修云々です。項目で特にここまでの文言に触れておりませんけれども、事業者からいただく事業計画書等々にはそういった文言も入っておりまして、そういったものも加味した上で検討させていただいているです。","voiceIndex":96,"id":"exchange-038"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、やはり最低でも指定管理に関する業務の収支、今ここに資産総額というのは出ているのですけれども、この指定管理者がどのように何に使って、主に人件費のところにはどれだけ割かれているのかとか、そういったことは事業計画書に書かれていて、それに対する報告書というのも出されているというのはモニタリングのところでも報告があったのですけれども。","respondent":"大串福祉計画課長、寺嶋高齢者福祉課長、松山障害者福祉課長","answer":"指定管理といったところで本日ご用意させていただいた資料については、大きなところというかポイントでお示しをさせていただいておりまして。今回の指定管理に関係する書類の中では、先ほどの疑問について持ち合わせてはいないので、ちょっとこの場で数字を細かくお答えすることができないのですが。障害者福祉課所管の３施設も同様に、モニタリングの中できちんと財務状況、収入および収支の状況を確認しております。","voiceIndex":98,"id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そのモニタリングの中でも、管理運営委託料というのが出ているだけなのです。モニタリングでは社会保険労務士も入れた審査をしていくと、見直しがされるというふうにもありましたので、ここの委員会に出される資料についても、最低でも事業の計画書、報告書、そして指定管理に関する業務の収支という資料を出していただきたいと思うのですけれども、ご検討いただきたいのですけれどもいかがでしょうか。","respondent":"大串福祉計画課長","answer":"指定管理に対してといったところにつきましては、区全体の考え方になってまいります。全体の考え方を検討と聞いておりますので、そうした中で、この委員会での提出資料のことについても検討していきたいと考えております。","voiceIndex":102,"id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問","question":"ぜひ透明性を持って、私たちも見ていきたいなと思います。それを示すのが役割だと思いますので、ぜひそこはお願いしたいと思います。ですけれども、小規模多機能なのに現在はない。私は、小規模多機能といったら、「通い、泊まり、訪問」というこの３セットが基本なのかなと思っていたのですけれども、これは訪問介護は今もないのか、どうしてないのかを伺いたいと思うのですが、いかがでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"ちょっと私の認識と異なっている部分があるので、基本的に小規模多機能の中で行っているという認識だったのですけれども、すみません、ここはちょっと人数までは把握していなくて申しわけないのですが、小規模多機能の中の事業として行っているという認識をしています。","voiceIndex":104,"id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問","question":"今言った議事録というのは、その大起エンゼルヘルプが指定管理者になるというときに、あとまたこの地域密着型多機能ホームができるというときの審議だったのですけれども、ちょうど５年前の、また新たに５年間の指定管理を任せるというときの審議でも、「訪問介護についてはされないのでしょうか」という委員の質問に対しては。","respondent":"寺嶋高齢者福祉課長","answer":"おそらくその５年前の議事録も含めてなのですけれども、事業者指定としての訪問介護事業所を指定するのかどうかという、いわゆる２５名の登録者に対する訪問、それから通所、泊まりの小規模多機能の事業は行うのですけれども。","voiceIndex":106,"id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それと、このモニタリングのところでもあるのですけれども、人材不足のことが改善が必要な事項のところでも言われているのですけれども、株式会社ですので、離職率、やはり株式会社は基本的に利益を追求するところですので、そういったところでうまく回らなければ人件費を削ったり、または職員を削ったりというふうにもなってきかねないなと私たちは思っているのですけれども。","respondent":"寺嶋高齢者福祉課長","answer":"数字的には少なければ少ないほうがいいに越したことはないので、ただ一方でまた今お話にもありましたように株式会社ということもありますので、そのための何か特別な支援ができるかというと、例えば金銭的な部分ということについては、ほかの小規模多機能と同等の。","voiceIndex":109,"id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり離職率２０％で高いということで、それは施設のほうもモニタリングであるように、改善が必要な事項として挙げていると。それと、この地域交流もすごく重点的にかかわりを持ってやっていこうということも書かれているのですけれども、区として具体的にこの地域交流に対して求めていることは何かあるのでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"先ほどの選定理由の中で挙げさせていただいたまず１つは、併設ということもありまして、品川保育園との防災訓練をはじめとした多世代交流ということは、これはもう開設時から力を入れているところです。","voiceIndex":111,"id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"次に行きたいと思うのですけれども、第９４号議案の心身障害者福祉会館ですけれども、これは前回の厚生委員会でも、公募型プロポーザル方式でやったけれども、品川総合福祉センターだということで、それはるる伺ってきたので中身等々はあれなのですが、ここだけに限らないのですけれども、やはり障害者施設の人材確保というのも本当に厳しい状況だと思いますし。","respondent":"松山障害者福祉課長","answer":"障害者の施設の人材確保ですけれども、前回の厚生委員会でもご説明したとおり、心身障害者福祉会館も含め、ほかの２施設も、人員基準は満たしております。どちらかといえば障害者施設は、障害者支援を行いたくて採用される方というのは多くあります。","voiceIndex":113,"id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、Ｂ型になっての工賃というのはどのようになったのか。それと、Ａ型とＢ型の仕事の中身がどのように変わってきているのか、Ａ型とＢ型の内容をちょっと教えていただきたいです。","respondent":"松山障害者福祉課長","answer":"委員ご指摘のとおり、確かにＡ型は３月末で２名ということで、２名のうち１名の方が障害者雇用で就労されて、もう一名の方はＢ型に移られたのですけれども、そもそもがなかなかＡ型としての厳しい雇用状況ではなく、ご本人が就労の状況に合わせた形を鑑みると。","voiceIndex":115,"id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問","question":"モニタリングのところでは、自主製品というのに力を入れていきたいと、「自主製品の商品力向上」というのがあるのですけれども、これなどは、要は水耕栽培でとれるものということなのでしょうか。","respondent":"松山障害者福祉課長","answer":"こちらで言っています自主製品というのは、主に雑貨ですね。キャンドル、ろうそくですとか、あとくるみボタン等々が自主製品となっております。","voiceIndex":117,"id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問","question":"結ぶことが望ましいと総務省のほうも言われているし、区の条例にも書いてあると思うのですけれども、それぞれ協定は結ばれるのかということ。それは議事録というのはつくられているのでしょうか。それでここに選んだというのがその議事録に残って、それが情報公開請求をすれば見られる形にはなっているのかを伺いたいのと、あと、第三者評価というのはしているのかというのを、それぞれ伺いたいと思います。","respondent":"大串福祉計画課長","answer":"指定管理の協定については結ぶ形です。それから、選定委員会等々の議事録、これについても作成をしています。それから、各施設ごとでの第三者評価をやっておりますので、そういったところで総合的に判断しています。","voiceIndex":119,"id":"exchange-048"},{"speaker":"石田（ち）委員","kind":"質問","question":"それは情報公開とかをすれば見られるのか、それとも課に見せてくださいと言えば見られるのか、ちょっとお伺いします。","respondent":"大串福祉計画課長","answer":"議事録等々につきましては、情報公開という形にさせていただいています。","voiceIndex":121,"id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もう少な過ぎると思うのです。そういう点では、この委員会の資料というのも、モニタリングのシートというのは、多分それぞれの課で全て統一してやっていきましょうというのはあると思うのですけれども、この各委員会に出される資料というのも、この程度で出していきましょうというのは各課で統一されたものでこのようになっているということなのでしょうか。その点についてもお聞かせください。","respondent":"大串福祉計画課長","answer":"指定管理制度全体に関しましては、区全体といったところになってまいります。そうした中で、他区の事例も出していただきましたように、その辺も参考にしながら区全体として考えていくものかなとは考えているところです。","voiceIndex":123,"id":"exchange-050"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、品川区としては、先ほどもここに書かれている選考基準に基づいて評価をして、今回改めて継続という形でこの４つの指定管理が出てきたわけですけれども、この点について点数をつけてということでしたので、それぞれのところで１、２、３、４と大体ありますけれども、何点中のところ何点だったのかというのを、施設ごとに点数をお聞かせいただけたらと思います。","respondent":"大串福祉計画課長","answer":"指定管理のご議決をいただく際には、そういったところを踏まえた上での資料提供を考えていきたいと思います。各施設ごとの点数ですが、ちょっと今日はその辺は持っておりませんので、総合的に判断したという形で、本日のところは資料を出させていただいているところです。","voiceIndex":125,"id":"exchange-051"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それともう一つ、心身障害者福祉会館なのですけれども、本当に公募したにもかかわらず、品川総合福祉センターしか来なかったということで、品川総合福祉センターが指定管理者候補者ということに改めてなりましたけれども、そのようなところでは、前回もご説明いただいたように異例の附帯条件をつけて今回指定管理者候補者ということになったと思うのですけれども。","respondent":"大串福祉計画課長、松山障害者福祉課長","answer":"点数等々の掲出についてはある程度全体の流れといったところになりますので、その辺はまたちょっと検討させていただければと思います。協定書については、各法人ごとに結んでいきます。そのほかの法人につきましては、基本的にはこれまでの協定にならってということになりますけれども、心身障害者福祉会館につきましては、こちらのご参考のところで議会にも報告させていただきましたとおり。","voiceIndex":127,"id":"exchange-052"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"４議案とも自民党賛成です。ただ、今お話がありましたように、心身障害者福祉会館とか条件のついているところもあります。それから、モニタリングの中でいろいろな指摘、業務改善の視点とかいろいろ出ているところもあります。その辺を充分チェックしながら、今後も運営に努めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-053"},{"speaker":"若林委員","kind":"質問・要望","question":"４議案とも賛成です。特に心身障害者福祉会館については参考資料もつけていただいて、医療的ケアのところも含めて虐待防止のチェック、過去そういうことがあったと思いますけれども、またしっかりケアしながら充実した施設運営をお願いをしたいという要望を添えて、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-054"},{"speaker":"石田（ち）委員","kind":"意見","question":"今回もそうした職員配置だったり職員の労働条件だったり、そういったものは資料には全くなく、株式会社であるからこそさらに透明性を持って報告されるべきだと思いますし、そしてそれは今回なされていないということで見えてこないということ、そしてやはり株式会社は、今もこうした高齢者の福祉施設にはなじまないと考えますので、この第９３号議案は反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-055"}]},{"id":"topic-02","title":"第９７号議案、指定管理者の指定","agenda":"第９７号議案、指定管理者の指定","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"品川区立健康センターについてですね。ここは５年前のときに公募型プロポーザル方式で、この住友不動産エスフォルタ・ＮＴＴファシリティーズの共同事業体が指定管理者になったと。その前はコナミでしたか。","respondent":"川島健康課長","answer":"その前の前です。","voiceIndex":146,"id":"exchange-056"},{"speaker":"石田（ち）委員","kind":"意見","question":"前の前でしたか。そこからこの共同事業体に運営が変わった。前回は公募型プロポーザル方式にしたけれども、今回はこのまま継続させるというところでの、継続の判断基準というのは何だったのか。ここに選考基準というのがありますけれども、公募せずに……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"質問","question":"ごめんなさい。すみません。そうですね。では、継続の判断基準を教えてください。","respondent":"川島健康課長","answer":"先ほどの資料の中にもございましたが、まず提案内容としましては、気軽に楽しく利用できるというような工夫がある新しい提案がございましたし、それから大きかったのは、光熱水費の削減の提案というのがありまして、そちらは。","voiceIndex":149,"id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"その辺も、午前中の審議のところでは選考基準の表をいただいていたのですけれども、この品川区立健康センターについては、この選考基準等はあるのですけれども、そこもやはりこの基準に従って（１）、（２）とあるけれども、この（１）の事業実績の中では、その中でも細かく判断の項目が分かれているわけですよね。その採点の評価、点数を教えていただきたいのですが。","respondent":"川島健康課長","answer":"建物の維持管理に関する取り組みというのがもうかなり高い得点であったということです。合計得点は、１０００点満点のうちの８割以上を、今回１位の選定した事業体が獲得したです。","voiceIndex":151,"id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"提案","question":"このモニタリングの表でも利用者数が増えていて、指定管理料も１億２,９００万円余が出されているということで、これはやはりこの事業者のそういった取り組みや提案や工夫といったところで利用者が増えて、指定管理料も増えたということになってくるのですか。","respondent":"川島健康課長","answer":"指定管理料が増えてしまうと、何か逆行していくような話だとは思うのですけれども、利用料金収入が増えているということをご説明させていただいたところで、こちらの健康センターのフリー利用ですとかコース利用、プレイコートの利用料金ですとか、ホール、会議室の使用料。","voiceIndex":153,"id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"質問","question":"その人件費のところは１億７,０００万円余。この職員とか働く方の入れ替わりとかは、それほど激しくはないのでしょうか。離職率やスタッフ配置とかはどのようにされているか、先ほど言った入れ替わりや離職率のところを教えてください。","respondent":"川島健康課長","answer":"職員につきましては、まず正社員といいますか常勤の方が何名配置ということで、総括責任者の方１人と、トレーニングルームの責任者が１人、受付責任者が１人という形で、決められた体制を組んでいただいた上で、あとアルバイトというかそれぞれのトレーナーですとか。","voiceIndex":155,"id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、離職率という形でもしとるとすれば、その常勤のところでしかとれないのですか。アルバイトというところは確かに入れ替わりがあるかと思うのですけれども、そういったところを含めた離職率というのは出るのでしょうか。","respondent":"川島健康課長","answer":"そちらのほうは離職率という形では把握してございません。","voiceIndex":157,"id":"exchange-062"},{"speaker":"鈴木（真）委員","kind":"質問","question":"利用者の方何人かからお聞きして、やはり評判がいい状況です。今回も賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-063"},{"speaker":"石田（ち）委員","kind":"質問","question":"今回も、やはり職員やスタッフの入れ替わり等々も、株式会社なのでやはり利益を追求するわけですから、それがうまく回らなければスタッフや職員に響いてくるというところを鑑み、そして突然撤退ということもあり得るのが株式会社ですので、そういったところに区民の健康づくりを任せるというところはそぐわないかなと思いますので、反対します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-064"}]},{"id":"topic-03","title":"平成３０年陳情第２１号、放課後等デイサービスに関する補助事業等の実施を求める陳情","agenda":"平成３０年陳情第２１号、放課後等デイサービスに関する補助事業等の実施を求める陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私たちはいつも区民からのこうした請願・陳情への意見陳述は、議論の前にしていただきたいと思っていますし、その陳述を聞いて、そしてさらに議論を深めるということをすべきだと思いますので、ぜひ議論の前に意見陳述をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":168,"id":"exchange-065"},{"speaker":"芹澤委員","kind":"確認","question":"確認なのですが、今１２カ所あって、学校送迎しているところが８カ所というお話があったと思うのですが、逆に言えば４カ所はしていないということになると思うのですが、そこは先ほどお話のあったような何か民間とかの方法で送迎がなされているということなのでしょうか。","respondent":"松山障害者福祉課長","answer":"品川特別支援学校を逆に希望していらっしゃる方もいらっしゃいますので、今後東京都の教育委員会との面談が入るという情報を現段階では把握しております。","voiceIndex":173,"id":"exchange-066"},{"speaker":"石田（ち）委員","kind":"質問","question":"先ほど、新１年生でこの臨海青海特別支援学校エリアの人は１８人ということでした。今在校されている方は今までどおりなのですね。障害者団体からも、この品川区内を青海の学区域にしないでほしいという声なども出ていたと思うのですけれども、そこに対して、品川区からは何か当時意見などを言われたりされたのでしょうか。","respondent":"松山障害者福祉課長","answer":"ただし、臨海青海特別支援学校に行かれるのか、それともまた特別支援学級に行かれるのか、通常の学級に行かれるのかというところでは、現在はまだ決定はしておりません。","voiceIndex":175,"id":"exchange-067"},{"speaker":"石田（ち）委員","kind":"確認","question":"どこに通うかはこれから面談が始まるということですけれども、やはりこの臨海青海特別支援学校のエリアの方が、この品川区内の学校にということで越境を望むと、スクールバスは使えなくなるのですよね。そこの確認をしたいのと、やはり越境した人までスクールバスに乗せるという考えが、品川特別支援学校はそこまではしないということになっているのか、ちょっとそこを確認させてください。","respondent":"松山障害者福祉課長","answer":"品川特別支援学校に越境するとスクールバスが使えないのではないかですが、今のところ、現段階では区はそのような形での情報はいただいておりません。","voiceIndex":177,"id":"exchange-068"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、やはりこの臨海青海特別支援学校がある場所は、江東区から見てもすごく住民が多く住む場所から離れた、要は臨海の部分ですよね。ですので、品川区としてもこの臨海部に近い地域、八潮なり、そういった部分に放課後等デイサービスを誘致する、もしくは区が建てるといった対策が必要だと思うのですけれども、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"現段階では、まだわからない状況が多数ありますので、今のところは補助事業ということで実施というのは考えておりません。","voiceIndex":179,"id":"exchange-069"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"以前からも誘致をすべきだということで私たちも求め続けていましたけれども、この臨海青海特別支援学校の状況も出てきたからこそ、品川区としてさらに増やしていくということを進めなくてはいけない状況にあるのではないかと思うのですけれども、臨海青海特別支援学校に近いだろうなと思われる八潮とか、そういったところをぜひ考えていただきたいと思うのですけれども、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"今、現段階では民間の相談支援事業所からも、来年つくりたいというようなお話もいただいておりますので、その状況を鑑みると、現段階で補助事業の実施をすべきということは考えておりません。","voiceIndex":181,"id":"exchange-070"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"けれども、日数は増えたけれども、場所がないから使えない、もう受け入れてもらえないという状況もあると聞いていますので、やはりこうした補助事業をつくって、来年だけでなく引き続きさらに増やしていくということ、そして補助事業があればさらに民間も来やすくなるということだと思いますので、ぜひそこはさらに増やすという立場で検討していただきたいなと思うのですけれども、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"放課後等デイサービスにつきましては、区内の状況や民間の状況等を鑑みながら、必要性について検討していきたいと考えております。そのため、今の状況としては、なかなか私どもにまだ正確な情報がございませんので、情報をいち早く把握して検討していきたいと考えています。","voiceIndex":183,"id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問","question":"ぜひよろしくお願いします。先ほど連絡会を開かれているということで、決算特別委員会でも近隣区と連絡会を持って、情報把握をしてというような答弁があったと思うのですけれども、その連絡会というのはどのようなもので、どれぐらいのスパンで開かれているものなのか伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"１回目は６月に開催いたしまして、今のところ次回は来年早々１月に開催する予定です。各事業所と都の情報の把握も兼ねて、きちんと具体的な情報がそろった段階で、開催する時期を１月と決めております。事業所については、近隣区含めまして対象となる事業所は３９の事業所です。","voiceIndex":185,"id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問","question":"今年度初めてこの連絡会というのが始まったというのは、目的は何だったのかを伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"国のほうでも放課後等デイサービスについては、この陳情者も書かれているとおり、デイサービスガイドラインに沿った形で質の向上を図るということが、やはり国としても課題になっておりますので、私どもといたしましても放課後等デイサービスの数が増えるだけではなくて。","voiceIndex":187,"id":"exchange-073"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"例えば新１年生が１８人ということなのですけれども、そのうち、割合としてどのぐらい行くのかなというのがちょっとわかったらという思いでお聞きするのですけれども、品川特別支援学校に、その対象者のうち何人ぐらい通われているのかなというのを教えていただきたいと思います。","respondent":"松山障害者福祉課長","answer":"実際生徒数というのは学校のほうで把握していますし、そのうち放課後等デイサービスの利用者はこちらで調べるということは可能です。現段階ではちょっと持ち合わせておりません。大体一般的にというのはちょっと難しいかと考えています。","voiceIndex":189,"id":"exchange-074"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"認められるとなったら、そういうふうに希望する方がすごく多くなってしまうのではないかと思うのですけれども、そこら辺のところはどうなっていくのかがわかったら教えていただきたいと思います。","respondent":"松山障害者福祉課長","answer":"現在お通いになられている方、在籍の方はそのままなのですが、確かに新１年生で指定校の変更を認められるかどうかということにつきましては、私も臨海青海特別支援学校のほうに問い合わせは既にしておりますが、まだ東京都の教育委員会との面談がありますので。","voiceIndex":191,"id":"exchange-075"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そこら辺のところで、今は認められても、実際にまだ知的の方は１０カ所、それ以外を含めても１２カ所というところで、品川で断られているという例が結構あるとお聞きしているのですけれども、そこら辺のところでは、放課後等デイサービスが元々足りないという認識、増やしていきたいというところとあわせて、区としてどう思われているかについてもお聞かせいただけたらと思います。","respondent":"松山障害者福祉課長","answer":"確かに将来的にこの臨海青海特別支援学校が９年生までということであれば、必要性に応じてその時点で民間の状況がどうなのか、区内の状況がどうなのか、あるいはお子さんたちの状況がどうなのかを総合的に勘案して、そのときに必要性があるかどうか。","voiceIndex":193,"id":"exchange-076"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１８１名通われているということなのですけれども、そのうち、このエリアの子どもさんというのは何割ぐらいいるかということがわかったら教えていただきたいのと、あとはこのエリアということで臨海青海特別支援学校に通うようになった子どもさんが、放課後等デイサービスを送迎がないために使えないということがないように対策が必要だと思うのですけれども。","respondent":"松山障害者福祉課長","answer":"送迎がないためにサービスが使えないということがあってはならないということは認識しておりますので、実際に学校が決まりまして、放課後等デイサービスをどこの事業所と契約するのか。","voiceIndex":195,"id":"exchange-077"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひしていただきたいと思います。やはりこういった学区域が変わるということ、そして子どもたちが日々通う学校の放課後のこと、そういったところをやはり当事者とその家族であるからこそ伝えたいことはあると思いますし、準備もされてきていると思います。それが引き続き判断の材料になっていくと思いますので、ぜひ陳述をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":200,"id":"exchange-078"},{"speaker":"鈴木（真）委員","kind":"質問","question":"自民党としてもいろいろ検討させていただきました。１つ課題としては、学区域変更というのはこれは東京都の問題なのですけれども、そこは少し疑問もあるのですけれども、現状で就学相談中という話、理事者の説明にもありましたが、民間から複数申し出もあるという状況の中からも、この陳情については不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":204,"id":"exchange-079"},{"speaker":"若林委員","kind":"質問・要望","question":"結論を出すということです。不採択。理由としては、いずれにしても今の質疑でもありましたけれども、送迎が確保されないで、放課後等デイサービスに行けないという子どもは一人も決して出してはいけないという区の姿勢も確認させていただきましたので、ぜひそういうことで進めていただきたいと思います。新１年生も東京都の面談がまだないのでわからない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":205,"id":"exchange-080"},{"speaker":"石田（ち）委員","kind":"意見","question":"やはり送迎がないために使えないということがないように、やはり起きてからではおそいですので、今から対策を打っていくのは大事なことだと思いますし、そもそもこの陳情の中にもありますけれども、区内の放課後等デイサービスの供給不足を解消していく、それで区内のニーズに応えていくということで補助事業を実施していくというところでは、新たな学区になってしまった子ども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":207,"id":"exchange-081"},{"speaker":"木村委員","kind":"意見","question":"結論を出すで、不採択でお願いします。これからもう少しいろいろ議論をしていくべきであろうと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":208,"id":"exchange-082"}]},{"id":"topic-04","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"石田（ち）委員","kind":"確認","question":"だからその法定外繰入を国は解消しろと言っているのだから、それを繰り入れることはできないのだとおっしゃっていたのですけれども、その法定外繰入が保険料減免に充てるためなら、解消すべき繰り入れではないというふうに厚生労働省から出ているので、そこをちょっと品川区にも確認したいというのと、あと、差し押さえのところの質問で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":213,"id":"exchange-083"},{"speaker":"石田（ち）委員","kind":"確認","question":"法定外繰入をなくしていく、解消していくべき繰り入れの分野が出ているのですけれども、保険料減免のために充てる繰り入れは、そこに当てはまっていないというのが厚生労働省から出ているのです。ですので、保険料減免のために法定外繰入をすることはできると思うので、そこを確認したいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":215,"id":"exchange-084"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3524#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":51419,"voices":224}},{"id":"h30-20181210-8","meetingId":"h30-cm12","date":"2018年12月10日","dateIso":"2018-12-10","committee":"建設委員会","time":"午前１０時００分～午後 ２時３１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を88件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料について幾つかお伺いしたいのですけれども、この表面のほうですが、私は１１月１６日の決算特別委員会の総括質疑で、区長は国に面談に行かないのかと聞きました。それと今回、再三再四議会でも指摘しましたが、今回の面談の記録というものは公文書で残したのかどうか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"いつ、どのタイミングで決定ということは、ちょっと日時的なところはあれですが、１１月１６日の決算特別委員会でご質問をいただいたときは、その辺の詳細がまだ当然決まっていなかったということで、その旨回答したわけですが、その後。","voiceIndex":13,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"この委員会資料とかなり違う内容なのか、その辺を少しお伺いしたいということが１つあります。ぜひ資料としても提示していただきたいということが１つあります。伺いたいと思います。本会議での、おくの区議の一般質問で、区は区民の立場に立って地域の声をしっかり届けるというような答弁があったかと思うのですけれども、しっかり届けていないのではないかと思うのですが伺います。","respondent":"鈴木都市計画課長","answer":"区民理解、あるいは今委員からもいただいた反対の声があるというところにつきましては、これは区のほうでも教室型説明会、こうした実施が区民の方からも非常に声として大きいというところ、あるいは区民の意見もさまざまありますというところは。","voiceIndex":15,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"教室型説明会は今回改めて強く言ったということは、それは大事なことだと思いますけれども、区民意見がさまざまあるとおっしゃるのですが、多くの反対意見、これを届けない、届けていないということはなぜなのか、区民の中に多くの反対意見があるとは認めないということなのですか。ないものを伝えるわけにはいかないと、そういう立場なのでしょうか。伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"やはり非常に声として大きい教室型説明会をしっかりやっていただいて、国の方が直接区に来ていただいて、品川区民に向けてこの計画案を説明していただいて、その場で区民の声をしっかり聞いていただきたいというところでやりとりをさせていただいたというところでございまして。","voiceIndex":17,"id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"伺いますけれども、この冊子のこの箇所というものを区は読んだことがないのですかということを伺いたいということが１つです。それともう一つ、「事業計画への位置づけが義務付けられた落下物対策基準についてその実効性の担保を示されたい」と要望されておりますけれども、この落下物対策基準の実効性というものが担保された場合、落下物はゼロになるのかということもあわせてお伺いします。","respondent":"鈴木都市計画課長","answer":"平成２８年になりますが、環境影響に配慮した取り組みの中で、これも騒音環境の低減に向けた取り組みをそれまで区が再三再四要望してきた中で、これは進入角度というよりも着陸飛行位置をさらに伸ばして高度が上がったという実績というか、国の対応があります。","voiceIndex":19,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと落下物対策も、やはりゼロになるとは言えない。ゼロになると言える立場にない。ですから、落下物対策の実効性ということを求めるのであれば、同時にこの密集市街地の上を飛ばすことをやめてくださいということが最大の落下物対策ですから、それを求めていただきたいのですけれども、落下物との関係でいかがですか。それが最大の落下物対策ではないのですかと伺います。一旦ここで終わります。","respondent":"鈴木都市計画課長","answer":"区のほうとしては、これまでお話ししてきたとおり、落下物対策については少しでもゼロに近づけるというところの中で、国に再三再四求めてきたところですので、そうした取り組みをさらに実効性あるものとしていけるように、引き続き国のほうに交渉していきたいです。","voiceIndex":21,"id":"exchange-005"},{"speaker":"筒井委員","kind":"確認","question":"観光にも重大な支障がある。大井競馬場の近くも通り、本当にそのレースにも影響が出るかもしれない。国がこの品川区に及ぶマイナスの状況を知っているか、知らないかということはまず非常に重要でして、国がこのような状況を知っていて、それでもあえて通そうとしているのか、そういったことを確認したいので、その国の、区のマイナスの状況についての認識はあるのかということをまずお聞きします。","respondent":"鈴木都市計画課長","answer":"何も区内の状況を１つも把握していないということではないと思いますし、ただ、先ほどおっしゃっていただいた土地の評価、これにつきましては国のほうからも伊丹や福岡の事例も挙げて、その直接的な因果関係は示されていないというところのお話があったところです。","voiceIndex":24,"id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"品川区にとってマイナスな状況があるとわかっていても、やはり国としてはこの羽田新飛行ルート案、どうしてもやりたいというお立場なのでしょうか。","respondent":"鈴木都市計画課長","answer":"今、そのようなことも含めて国は実施するのかですが、これは品川区以外でも、ほかの区でも上空を飛ぶわけでございまして、そうした国のほうの説明は、やはり海外とのつながり、インバウンドを増やして海外とのつながりを強化して。","voiceIndex":26,"id":"exchange-007"},{"speaker":"筒井委員","kind":"質問","question":"ずっと申していますけれども、ほかの地方空港、茨城空港や、また新しい滑走路の実現など、そういったことも考えとしてはあり得なくはないと思うのですが、やはり影響が大きいからとか、住民の反対が大きいからとか、代替案も考えられるからほかの案もあり得ますねということは国は一言も一切発しなくて、まさにこの新ルート案だけというようなお考えだったのでしょうか。","respondent":"鈴木都市計画課長","answer":"そうした中で、ほかの空港を活用する考え方についても、これまで行ってきたフェーズの説明会の中で、あるいは資料の中で示されておりますが、そうしたさまざまな議論が行われてきた中で今の案が示されているですので、国としては。","voiceIndex":28,"id":"exchange-008"},{"speaker":"筒井委員","kind":"質問・要望","question":"国としてはそういったお考えなのでしょうけれども、今後説明会、特に教室型の説明会などでさまざまな区民のお声があると思います。それは要望で終わりますけれども、今回の、まず区長面談について、品川区としてまず常設型展示による情報発信というものを要望しているわけですが、まずこれについて国は何も回答されていないのですけれども、この常設型展示について国はどうお考えなのでしょうか。","respondent":"鈴木都市計画課長","answer":"ただ、区の捉え方としては、この２２日を迎えるまでの担当者レベルの打ち合わせの中では、常設型展示の設置についても、今会場を区のほうでも探していますし、国のほうでも探しているというところもかんがみますと、区としてはしっかり受けとめていただいて。","voiceIndex":30,"id":"exchange-009"},{"speaker":"筒井委員","kind":"質問","question":"担当者レベルでそのようなお話は進められているので、将来的には、いつかの段階では実施、実現に向かっているということでよろしいでしょうか。","respondent":"鈴木都市計画課長","answer":"この面談の中で、国のほうで具体的な常設型展示という言葉は出ませんでしたが、受けとめ方としては、これをぜひ実施していただくように、しっかり区のほうでも協議をさせていただいているです。","voiceIndex":32,"id":"exchange-010"},{"speaker":"筒井委員","kind":"確認","question":"その点、やはり区民の声で多いのは、最低限の防音措置というものをやってほしいと。特に学校施設や医療関係の施設だけではなくて、一般住宅まで防音措置というものをぜひやってほしいというお声が多いのですけれども、その点、品川区としてはお伝えはしているのかということと、お伝えしているのだとしたら、国はどのようなお考えなのか、それをお知らせください。","respondent":"鈴木都市計画課長","answer":"それから住宅への防音工事助成につきましては、これ防音助成につきましては、この新飛行ルート計画案が出される以前から、これは日本全国でもう防音工事助成というものは行われていまして、そういう意味では、この新飛行ルート案がもし実施された場合、住宅の場合。","voiceIndex":34,"id":"exchange-011"},{"speaker":"筒井委員","kind":"質問","question":"従前の法律でしたらそうなると思うのですけれども、やはりこの羽田新飛行ルートは品川区が一番大きな悪影響が出るところでありまして、また実際法律上の数値の基準ではなくて、体感的に非常に不快感をもたらすような騒音に対して、人体に本当に悪影響を及ぼすと思うのですが、ぜひ一番騒音被害がもたらされるこの羽田新飛行ルート、特に直下の地域については。","respondent":"鈴木都市計画課長","answer":"従前の法律の中でというお話を差し上げましたが、従前の法律を当てはめて、それで新ルート案で上空を飛んだ場合でこれに当てはめて、先ほどちょっと数字をお示しできませんでしたけれども、住宅であればＬｄｅｎ６２デシベル以上というところが対象になるわけです。","voiceIndex":36,"id":"exchange-012"},{"speaker":"筒井委員","kind":"質問","question":"その従前の法律というものは、なぜその基準値を設定したのかということはおわかりでしょうか。恐らく余り広げ過ぎると、莫大な費用がかかってくるとか、そういった理由だろうと思うのですけれども、わかれば教えてください。","respondent":"鈴木都市計画課長","answer":"これはもともとある環境基本法の中に、住居系の場合やその他の場合というところでいろいろ定めがありますので、そうした基準にのっとってこの数値は定められているというものです。その対象が広がるから、その数字を上げる、下げるという形で設定されているものではございません。","voiceIndex":38,"id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"学校の施設や医療施設はやってくださるということなのですか。それは法律の例外としてやってくれるということですか。","respondent":"鈴木都市計画課長","answer":"学校などといった施設については、今回示されているのが午後３時から７時、おおむねその中の３時間というところでございまして、その時間を区切った中での法改正が行われておりまして、その中でもともとは２４時間の中で均す形で騒音を測定していたものが。","voiceIndex":40,"id":"exchange-014"},{"speaker":"筒井委員","kind":"質問・要望","question":"だからそれを例外として国が認めたということなのですね。これはもう品川区は一番最悪な被害を受けるところですから、それは、その程度は認めていただかないと、区民にとってもマイナスしかないと思いますので、品川区としても区民の安心・安全を最優先というのでしたら、ぜひともそこは一般住宅の防音措置もやっていただきたいのですけれども、その点を改めてよろしくお願いします。いかがお考えでしょうか。","respondent":"鈴木都市計画課長","answer":"住宅の場合は先ほどご説明したＬｄｅｎ６２デシベルですが、その他の施設についてはＬｄｅｎ５７デシベルと。この５７という数字は変わってございません。基本的にその時間を限定して対象を広げたです。","voiceIndex":43,"id":"exchange-015"},{"speaker":"筒井委員","kind":"質問・要望","question":"それを２４時間で時間をならすという考えは、ぜひ国のほうに改めていただいて、今課長おっしゃられたように、従前からお願いしているということなのですけれども、ぜひこの後に至ってはさらに積極的に、一般住宅の防音措置ということを要請していっていただきたいと思います。その点もう一言、よろしくお願いします。","respondent":"鈴木都市計画課長","answer":"どういった形で住宅まで広がるかというところは、何度もこれはやりとりさせていただいて非常に難しいといいますか、もともと設定しているベースがございましたので、ただいろいろな場面、担当者レベルのやりとりの中では、その話はさせていただきたいというふうに考えてあります。","voiceIndex":47,"id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問・要望","question":"区長が国交省において航空局長と面談をされたという資料から、ちょっと確認を含めて質問させていただきたいのですが、順番からいうと常設型展示について、また高度の引き上げ、落下物対策基準ですね。それで質問としては、この４番目のゴーアラウンドについてのことなのですが、これ発生したときには適時的確な区への情報提供を図られたいというところでわざわざ要望されている、その背景。","respondent":"鈴木都市計画課長","answer":"これは当然ながら実施計画に位置づけたそれぞれの会社、航空会社でしっかり取り組んでいくですが、それをいかに国のほうでその取り組みを確認していくかという枠組みといいますか、そういったものがなければ、やはり実効性のあるものとなっていかないということの認識から。","voiceIndex":50,"id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それと落下物対策基準について。これは答弁は結構です。それと、あとこの教室型説明会の実施についてなのですが、ここに周知方法として広報しながわ、ホームページ等とあるのですけれども、例えばそのチラシには、いわゆる教室型ではなくてオープンハウス、第５フェーズですか、しか載っていなかったのですが、これは載せられなかったのかという疑問、これについて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"それからもう１点が、教室型説明会の周知ですが、区のほうでも事前にこの１２月上旬の新聞折り込みに入れるということは聞いておりましたので、ちょっとその交渉もしたのですが、なかなか間に合わなかったというところと、やはり大井第一地域センター管内。","voiceIndex":52,"id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問","question":"一歩前進かなとは思うのです、周知に関しても。一歩前進かなとは思うのですが、そのようなところでもう少し本気で国として周知をしていただけたらなと。はこの説明会において、私も自分の地域は、自分の地域ですから出たいと思っているのですが、当然ここには区の職員もいらっしゃるということでよろしいでしょうか。","respondent":"鈴木都市計画課長","answer":"説明していただくのは国のほうが前面に座って説明していただきますが、区のほうでもその会場には参加といいますか、当然いるようにしたいです。","voiceIndex":54,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"「区議会公明党は国交省に対して品川区上空を飛行しないルートの再考を強く求めていきたいと考えている」ということだったので、大臣も公明党だということもありますので、ぜひこの再考を強く求めていきたいと思いますし、こういった説明会のことに関しても強く言っていただきたいのですけれども、この再考というものは求められたのか、その結果などはどうだったのかということをぜひ知りたいといいますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-020"},{"speaker":"あくつ委員","kind":"意見","question":"はっきり言わせていただきますけれども、共産党とは我々ちょっとスタンスが違うので、先ほどから議会として一致しているとか、そのようなことは、すみません、そちらがそのように捉えるのは構いませんけれども、はっきり言えば我々としては区長選の党利党略であったり、選挙にこれを用いるような、区民の不安を利用するようなことは我々はくみしない、このように考えておりますので、それが全てです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"選挙に利用したこともないし、選挙というのは、選挙で政治を変えるということは当たり前の合い言葉になっていますから、私は今の批判がよくわからないと思うのですけれども、再考を強く求めていただいたのかということの答えがないのですが、答えられないということなのかわかりませんけれども、ぜひその辺は明らかにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問","question":"今のこちらに対する質問ですけれども、先ほど申し上げたとおりです。党利党略に利用されるつもりはありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"やめますけれども、別に党利党略のために聞いているわけではないということだけはご理解いただきたいと思います。いろいろ解釈の仕方というものはそれぞれ会派によってあるかもしれませんので、これ以上はやめます。成果だと思っています。それで当たり前のことなのですが、この主催は国なのか、区なのか伺いたい。これは間違いなのでしょうか。伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"区が要望して国に来ていただいて、そこで当然説明をしていろいろなご意見、質問を受けるのは事業を進める国ですから、そういった受けとめ方です。","voiceIndex":60,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"共催ということになるのでしょうか。ですから、共催なら共催と書いていただきたいと思います。これを作成してホームページへの掲載や希望者への配布や地域へのポスティングなど求めたいのですけれども、あとポスターですね。チラシを引き伸ばしたようなものでもいいと思うのですけれども、各地域センターに案内、ポスターなど、ぜひ掲示していただきたいのですが、それぞれいかがでしょうか。","respondent":"鈴木都市計画課長","answer":"ただ、全てのマンションに掲示するなどということはなかなか現実的ではないのかなというところで、まずはやはり管内の町会の方に回覧をもってしっかり、あるいは区のホームページをもってしっかり周知をするです。","voiceIndex":62,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"行政ですから。ポスターとポスティングについてはどうでしょうか。参加者の希望で延長を認めるべきだと思うのですけれども、延長不可能なのでしょうか。伺いたいと思います。その説明の内容なのですけれども、最小限にしていただいて、質疑の時間を十分確保すべきだと思うのですが、いかがでしょうか。ただ、質疑の時間を十分確保すべきだということについてはいかがなのかと。これも伺います。","respondent":"鈴木都市計画課長","answer":"その時間も、質問時間についても、今現在国のほうとは協議中ですが、どの程度説明に時間を要するか等も含めて、一定時間の質問時間のほうはとりたいというふうに区としても考えてありますので、その辺は国と協議してまいりたいです。","voiceIndex":64,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"ポスターのほうは、その強い意思を持って、同じ区の部署なのですから、地域センターには少なくとも最低限張るようにお願いしたいと思います。なぜ難しいのか伺います。ですから機械的にやらずに、ここは、例えば道路の説明会でも、区がやっていますよね、今。お尻のほうを書いていないのです。別に延長は当日なかったのですけれども、別にそのような要望もなかったから。その辺を少し確認したいと思います。","respondent":"鈴木都市計画課長","answer":"そうした方には、今国のほうともやりとりをしていますが、これはオープンハウス型でも手法として実施されておりますけれども、そういった声を書いていただいて国のほうに寄せていただくとか、そうしたところはしっかり考えていきたいというところでございまして。","voiceIndex":66,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"すみません、ごめんなさい。言い忘れました。チラシのほうはなぜ難しいのかということをお伺いしたいのですが、今決まっている内容について一定程度のチラシ配布というものは、それは区としての最低限の説明責任を果たしていくことになるのではないかと思うので、その周知がなければ説明会も空振りに終わってしまいますし、その辺なぜ難しいのかということを伺ったのでお答えいただきたいと思います。","respondent":"鈴木都市計画課長","answer":"先ほどのポスティングの話ですが、一定程度地域の中でポスティングを実施すべきというお話でございましたけれども、やはり今区のほうではホームページ、これはいろいろな事業、説明会実施に当たって、再開発などはそのエリア内にポスティングということもありますが。","voiceIndex":68,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"でもその届ける内容が非常に机上の空論といいますか、実態を捉えていないといいますか、さまざまな意見がある、反対もある、賛成もあるというぐらいではないですか。アンケートを自分でやらないで、どのようにしてその声を届けられるのですかと伺いました。区民の声をつかむ必要があるのではないですかということを伺いたい。そもそも区民の意向をつかむ必要があると区は考えていないのでしょうか。","respondent":"鈴木都市計画課長","answer":"区民の声につきましては、これまでもさまざまな機会を捉えて国のほうには伝えているところでございまして、その１つとして教室型説明会が今回実施されると。その中でも国のほうでしっかり説明いただいて、質疑の中でも地域の声をしっかり国のほうに届けていただくです。","voiceIndex":71,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"国がやるべきと言いますけれども、国は東京都全体にこの計画をかぶせようとしているわけですよね。だからまずしっかりと区が住民の意向をつかむこのアンケート、これは必要だと思います。そもそも区民の意向をつかむ必要がないと区は考えていらっしゃるのですか。そのアンケートをやらなければ区民の意向はつかめませんよ、正直言って。区民の意向をつかむ気がないと、そのようなことなのでしょうか。","respondent":"鈴木都市計画課長","answer":"区民の意向を区が把握する必要がないということは、これまでも全く申してございません。それを実施していくのは、これは事業主体である国が行うべきというところを再三申し上げているところです。","voiceIndex":74,"id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"それはつまり計画を容認してほしいということを求めてやっているわけです。ですから、何というのでしょう、私たちも、共産党区議団も２０１７年２月にアンケートをとりました。ですからこういったことを区がなぜやらないのか。届けられるのですか。区が今やると言っていることすらもやれないのではないでしょうか。アンケートの必要性についてどのように考えているのか、最後にもう一度伺います。","respondent":"鈴木都市計画課長","answer":"先ほど委員からもご紹介いただきましたが、これ説明するべきは国です。地域の理解を得ること、丁寧に説明していただくこと、これは事業主体である国がしっかり行っていただくと。","voiceIndex":76,"id":"exchange-031"},{"speaker":"大沢委員","kind":"質問","question":"これは区の範囲ではないかもわからないですけれども、ご存じであればそこのところを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"やはり区民の方から不安の声、あるいは何だったのでしょうかという問い合わせに対して、これは先ほどご紹介いただきましたが、国がしっかり、これは国のほうでもそうした窓口といいますか、電話番号を公表して窓口を設置しているというようなところもございまして、今。","voiceIndex":79,"id":"exchange-032"},{"speaker":"大沢委員","kind":"質問","question":"同じということで、では実際に他の自治体、他の空港に関しても、品川区と同様で情報の提供を図るということで終わっているという、このようなことでいいのですか。","respondent":"鈴木都市計画課長","answer":"結果としてほかの自治体も同じだと思うのですけれども、区民の方がなかなか空港に直接お問い合わせをするという思いに至ることはなくて、やはり自治体に直接問い合わせをするというところで、やはりそういったゴーアラウンドがあった場合はいろいろ事象を調べて。","voiceIndex":81,"id":"exchange-033"},{"speaker":"大沢委員","kind":"質問","question":"気象、気流等々で難しいと思うのですけれども、このゴーアラウンドについての決まった航路という、そのようなものはあるのですか、ないのですか。","respondent":"鈴木都市計画課長","answer":"基本的にはそこに待機している飛行機の数や、そのときの進入ルート等で判断するので、決まった定期ルートはないというところは聞いてあります。","voiceIndex":83,"id":"exchange-034"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、今後実施される教室型説明会について、先ほど課長はその対象地区の方を優先にされるというような旨のお話をされましたけれども、その点何か、その対象地域の人かどうかということを判断する方法というものは、どのようにお考えなのでしょうか。","respondent":"鈴木都市計画課長","answer":"それも今ちょっと国のほうと協議中なのですが、やはりどのような説明会もそうですけれども、まず一定お名前とご住所をお書きいただくと。","voiceIndex":86,"id":"exchange-035"},{"speaker":"筒井委員","kind":"意見","question":"次に請願内容についてなのですけれども、アンケート調査についてなのですが、先ほど国の責任においてやるべきというご答弁がありましたけれども、この請願の理由にも書いてあるとおり、昭和５１年の９月には区がやられておるのです。この場合は品川区が主体としてやったのですけれども、なぜ今回は国でやるべきというご主張なのか。","respondent":"鈴木都市計画課長","answer":"今質問として、当時と何が違うのだですが、今は、これは飛行ルート案について、事業主体の国のほうが行う事業として説明を行っているものですので、これは当然、もしアンケートをするのであれば、実施するべきは国のほうが行うべきというものです。","voiceIndex":88,"id":"exchange-036"},{"speaker":"筒井委員","kind":"質問・要望","question":"わかりました。ただ、今「国のほうが、国のほうが」とおっしゃいましたけれども、品川区としては国に対してそのようなアンケート調査をやるべきだということを求めているのかということと、また私は、品川区としてもこの区民のご意見、また要望というものを把握するためには、品川区でもそのアンケート調査をやったほうがいいと思うのですけれども、その点いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"やはりこれまで国のほうに求めているとおり、丁寧な周知、説明というものを今求めて、具体的な形として教室型説明会が実施されるです。","voiceIndex":90,"id":"exchange-037"},{"speaker":"筒井委員","kind":"質問・要望","question":"それでこの間の、平成２８年９月１日の広報しながわに載っていますとおり、将来の技術進歩に応じた影響軽減や、また比較的影響の大きい地域への重点的配慮、コミュニティやまちづくり面での支援の検討、訪日外国人旅行者の区内誘致、空港の活力を地域に活かすための区政・地域と連携した取り組みの支援など、これ非常に羽田新飛行ルート、残念ながら通ってしまった場合において。","respondent":"鈴木都市計画課長","answer":"その具体的な内容をこれから行われる教室型説明会で国が行うかどうかは、やはりまず区民の方がどういったところをしっかりお聞きになりたいかというところもあろうかと思います。","voiceIndex":92,"id":"exchange-038"},{"speaker":"筒井委員","kind":"質問","question":"私が申したのは、今後実施される教室型説明会ではなくて、またそれとは別に品川区が主催でやる、教室型説明会で品川区関連事項の説明をやってはいかがですかというお話なのですけれども、この請願趣旨も「区が」ということが主語になっていますので、品川区が主催で、品川区関連事項のお話をするという説明会、この実施についてなのですが。","respondent":"鈴木都市計画課長","answer":"なかなか実施されなかった教室型説明会が今回これから実施されていくということで、この機会を捉えてというところと、今ご質問いただいた区独自にというところは、やはりこれはいろいろなお願いをしているところで。","voiceIndex":94,"id":"exchange-039"},{"speaker":"松永副委員長","kind":"確認","question":"私からは確認でご質問します。そこで確認ですが、その中で説明会での資料というものは十分に用意されるとは思うのですけれども、そこで多分ご質問等があるとは思うのですが、例えば録音や撮影は可能なのか、また、マスコミ等は初めてということで来られるのか、その状況についてお伺いしたいと思います。","respondent":"鈴木都市計画課長","answer":"それからマスコミですね。マスコミについては、今のところ特段取材をしたいというところの問い合わせはございません。これもほかの地域も順次行っていきますので、マスコミについてもどう対応していくかについては、しっかり国のほうと協議をしていきたいです。","voiceIndex":97,"id":"exchange-040"}]},{"id":"topic-02","title":"平成３０年請願第１９号 特定整備路線 放射２号線 現状を見直し改善を求める請願","agenda":"平成３０年請願第１９号 特定整備路線 放射２号線 現状を見直し改善を求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"現在の放射２号線の土地の買収率といいますか、取得率をお伺いすることと、それと資料の写真の中に車がとまっていると思うのですけれども、これは誰が使っているものなのか、わかれば教えてください。","respondent":"鈴木都市計画課長","answer":"それから写真ですが、これは地域の方に貸し出し、あるいは何か民間の団体に貸し出しということは聞いておりませんので、想定になりますけれども、確認がとれていなくて申しわけございませんが、都の職員等々がこちらに来て、この放射２号線関係で仕事をするに当たって。","voiceIndex":132,"id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"１９％程度ということなので、これは整備がかなり難しいと考えています。もともと必要ない道路でもある上、このように遊んでいる土地は有効活用すべきだとは思います。伺いますけれども、区内ではこのように暫定公園として活用されてきた例というものは結構あると思うのですが、このような将来の事業予定地ですね。それらがどこにどのような例があるのか、わかれば教えていただきたいと思います。","respondent":"鈴木都市計画課長","answer":"これまでさまざまなところで都市計画道路が進められ、都であったり、区であったりですが、過去の事例としては、一定程度の形がまとまったところは協議をして、そうした区民への貸し出し等のために、一定暫定的に使わせていただいたという事例はあります。","voiceIndex":134,"id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと請願項目の２番目のほうにかかわってくるのですけれども、ここに書いているとおり、区議会でも、区でも、これは都の事業なのだということにせず、やはり本当にこの道路に対して区民にどのような意向があるのか、あるいは必要なのかどうか、求められているのかどうかということをしっかりと、区民の代表としても、行政としましても、つかんだ上でチェックしていくということが私は必要だと思うのです。","respondent":"鈴木都市計画課長","answer":"先ほどの過去の活用の事例で、少し説明が不足していたところがあります。この請願にありますように、避難路として、あるいは避難空地として、例えば公園整備をして活用すると、そういった事例はこれまでは一切ございません。","voiceIndex":136,"id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"しかも都と連携しながら進めようと、進めてほしくないのですけれども、区が言っている事業のところなので、私はこれ可能なのではないかと思うのですが、もう一度伺います。このようなことで事業を進めていいのですか。それでまともな道路、まともな都市計画になるのですかと私は思うのですけれども、これでいいのでしょうか。伺いたいと思います。","respondent":"高梨木密整備推進課長、鈴木都市計画課長","answer":"あのような形で整備させていただいているのは、今後またさらに隣地との交渉状況においては、さらなる、いわゆる防災広場としての拡張が見込まれるといったようなことで、暫定的にあのような形で整備しているです。当然ながら今回事業決定するに当たっては、東京都において住民説明会、あるいは法に基づく公告縦覧など、しっかり手続きを踏んで計画が進められているです。","voiceIndex":138,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"私も放射２号線や２９号線の事業説明会には何度も参加しましたが、そこでの説明というものは、まず冒頭に「これは決定されました」ということが出されるのです。「何年に都市計画決定されました」というところから始まっているので、私が伺ったのは一度も計画の賛否を問われることなく、この計画が事業化されているということでいいのですかと伺いました。お答えください。","respondent":"鈴木都市計画課長","answer":"手続きの適否、あるいはいいのかどうかというところは、これは我々が判断するものではなくて、事業主体の東京都がしっかり手順を踏んで進めていっているですので、東京都のほうは、先ほど申しました延焼遮断帯の形成。","voiceIndex":141,"id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"本当に身近な自治体としてどうなのですか、そのスタンスは。請願の３つ目の理由について関連して伺うのですけれども、これは実際にこの道路というものは延焼遮断帯ということもありながら、避難ルートだというお話が、説明でもありました。伺います。この事業目的そのものが崩れているということにならないでしょうか。","respondent":"古巻防災課長、高梨木密整備推進課長","answer":"今、避難路のお話が出ましたので、少しお話をしますけれども、実際まだ道路として供用されているものではありませんので、そのときにどのような形になるのかということは想定以上の話はできないのですが。私からは、今このような道路予定地が囲われて、何の効果も発しないといったところについてご説明をします。","voiceIndex":143,"id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"この時点で。これからはそうした空き地になったところをどう市民のために活用するかということを考えていくのですとおっしゃっておりました。ですから、膨大な労力と膨大な経費と、そして犠牲を払って、このような道路を遮二無二つくっていくということは、私は見直すべきだと思います。以上、意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-047"},{"speaker":"大沢委員","kind":"質問","question":"公園について伺いたいのですけれども、あいた土地に公園をつくるとなると、やはり近隣の住民の方、近隣の隣接する家屋、住居について理解を得られなければいけないので、そのように簡単に公園というものはできるものではないと私は思っているのですけれども、そこのところをどのように考えているのか教えてください。","respondent":"溝口公園課長","answer":"そういった中、区の一定の方針としましては、町会内に公園がないところ、そういったところを重点的に整備していくように考えているところですので、引き続き公園の整備、そういったものには取り組んでいきたいと考えているところです。","voiceIndex":148,"id":"exchange-048"},{"speaker":"大沢委員","kind":"質問","question":"ここの今、資料に示されているあたりはやはり密集をしていて、公園が２つぐらい近隣にはあると思うので、私は必要性は感じていないのですけれども、実際地域からそのような声というものは、事業主体が都でありますが、説明などでは都と一緒に区も回られていたので、地元の自治体である品川区の皆さんが近隣の住民の方とお話をされている部分も多いと思うのですけれども。","respondent":"鈴木都市計画課長","answer":"個別具体の対応は東京都が行っているわけですが、具体的に地域の方から、この地域に公園が少ないので、暫定的といえどもこの空間を公園として整備してほしいなどという具体的なお話はいただいておりません。","voiceIndex":150,"id":"exchange-049"},{"speaker":"あくつ委員","kind":"確認","question":"本日結論を出すで、会派の地元の議員にも確認をしてまいりましたが、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":154,"id":"exchange-050"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択です。計画そのものを見直すべきだということもあわせて、採択したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":155,"id":"exchange-051"},{"speaker":"筒井委員","kind":"意見","question":"本日結論を出すで、不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":157,"id":"exchange-052"}]},{"id":"topic-03","title":"平成３０年請願第２１号 都営地下鉄中延駅（東中延２丁目口）のエレベーターなどの設置に向け、品川区が東京都と連携して取り組むことを求める請願","agenda":"平成３０年請願第２１号 都営地下鉄中延駅（東中延２丁目口）のエレベーターなどの設置に向け、品川区が東京都と連携して取り組むことを求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"品川区は、中延駅のこの当該箇所へのエスカレーターまたはエレベーター設置について、東京都と意見交換をしたことがあるのか伺いたいと思います。あるとしたらどのような内容だったのでしょうか。Ａ３口の利用状況について、どのような結果だったのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今委員のほうから、東京都がこのエレベーター、この出入り口についてエレベーター設置の検討を行ってるという状況についても、具体的な内容については今現在報告のほうは受けていない状況です。","voiceIndex":166,"id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"この件で都議会のほうでも、１２月３日の公営企業委員会のほうで請願が出て審査されたようなのです。この流動調査を行ったと。お伺いしたいのですけれども、この駅利用者数の推移というのですか、そしてこのＡ３口の利用割合というものはどれぐらいなのか、教えてください。それと、区としてはこのＡ３口へのエレベーター、またはエスカレーター設置の必要があると考えているのかどうか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"駅全体として、あるいは東京都交通局のほうがほかの駅も踏まえて、非常にこのような駅というものは都営地下鉄に限らず、ほかの駅でも出入り口が地下から地上に出ていますので、東京都としてどう考えるかというところもありますが、利用状況からいって。","voiceIndex":168,"id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから年々増えていると。Ａ４口のほうを私も現地で改めて確認したのですけれども、この写真にあるように、非常に歩道も狭いということもあり、なおかつ高齢者の方にとってはかなり歩くのです。ですから非常に、請願に書いているように、高齢者や障害者の方などにとっては、やはりＡ３出口にエレベーター、エスカレーターがないと、なかなかこれは大変な状況だということを現地で私も実感をいたしました。","respondent":"鈴木都市計画課長","answer":"その部分にエレベーター、エスカレーターをつけるというところは、現地も見ましたが、これは当然目視だけですけれども、いろいろ検討しなければいけないところが、もともと建物だけの部分で建てようとすると、なかなか技術的には難しいところがあるのかなというところは。","voiceIndex":170,"id":"exchange-055"},{"speaker":"安藤委員","kind":"確認","question":"技術的に難しいということですけれども、区としては技術的に無理だということはないと。設置不可能だということではないことでよろしいのか、確認をお願いします。","respondent":"鈴木都市計画課長","answer":"今申し上げましたように、目視ですので技術的な検証は全くしてございませんので、当然ながら技術的に検証を行うべきは東京都ですので、できるかどうかということは、ちょっとこの場ではお答えできないです。","voiceIndex":172,"id":"exchange-056"},{"speaker":"安藤委員","kind":"質問","question":"その辺はどうなのか。今言ったような課題というものは、区としては特に把握していないということなのか、もう一度お伺いします。","respondent":"鈴木都市計画課長","answer":"今ご紹介いただいたように、周辺というか、そこの部分に都市計画道路補助３０号線、また国道のほうは放射１号線、都市計画道路が入っているというところは区としても承知していますが、今ご紹介した公式な資料、東京都の委員会での資料ですけれども、承知してございませんので。","voiceIndex":174,"id":"exchange-057"},{"speaker":"安藤委員","kind":"質問・要望","question":"このように、まだ地元の自治体である区と都の、しかもその設置に当たっては３０号線という都市計画道路の計画などもかかわっていたりするので、ただ、設置されることによって利便性は向上するということですから、連携して、ぜひここに設置ができるような方向で、さまざまな議論が必要だと私は思いますし、今の議論を聞いてますます、若干生煮えの状況といいますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":176,"id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問・要望","question":"その上で私も地元の議員に確認をさせていただいて、確かに言われてみればこちらのほうにあったほうがいいのは決まっている話なので、先ほど安藤委員からもありましたけれども、ぜひ東京都のほうとこの件については東京都の見解、先ほど安藤委員はあえておっしゃられなかったのかもしれませんが、かなり否定的なご意見が出ていますけれども。","respondent":"鈴木都市計画課長","answer":"今、東京都の委員会におけるやりとりということでご紹介いただきましたが、その点についても含めて、区のほうでも、今ご紹介いただいたように、ワンルートは確保されていると、先ほど述べさせていただきましたが、やはり利便性が高まるということは間違いないですので。","voiceIndex":178,"id":"exchange-059"},{"speaker":"あくつ委員","kind":"質問・要望","question":"失礼しました。私、協議という言い方をして大変失礼申し上げたのですけれども、連携をとっていただいて、そこについては確認をしていただきたいということであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-060"},{"speaker":"筒井委員","kind":"質問","question":"今、拡幅予定があるというお話が出ましたけれども、これ実際拡幅された場合は、逆にエレベーター、エスカレーターの設置は難しくなるのですか。それとも容易になる方向に行くのですか。どうでしょうか。","respondent":"鈴木都市計画課長","answer":"現在の出入り口が、先ほどご説明した第２京浜、またそれに交差する形の補助３０号線、その拡幅後のラインを避けた形で建ってあります。","voiceIndex":182,"id":"exchange-061"},{"speaker":"筒井委員","kind":"質問・要望","question":"わかりました。これは要望で終わります。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-062"},{"speaker":"安藤委員","kind":"質問","question":"今のところは、この３０号線の予定があるということなのですけれども、この用地、３０号線の道路は区道の都市計画道路の予定ですが、そこの三角の土地である用地の所有者というものは、今現状どうなっているものなのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"その隅切り部分のことだと思いますが、その部分については東京都の所有地です。","voiceIndex":185,"id":"exchange-063"},{"speaker":"安藤委員","kind":"質問","question":"今東京都の用地ということなので、そこに都がエレベーターをつくるために、つくれるかどうかということを検討するために調査を行ったのですが、そこには区道の都市計画があるという構図なのです。ですから品川区が東京都と協議して、この計画線はあるにしてもエレベーターを設置するということは、私は区民の理解は得られると思いますし、必要なことだと思うのですけれども、いかがでしょうか。","respondent":"長尾建築課長、鈴木都市計画課長","answer":"計画道路におきましては、現状ですと建物ですと３階建てまで、地上１０ｍの高さまでということで、あと地下の構造物等はつくれないというところが制限になっておりまして、その一定の制限の中で建物を建てていただいているということが。今所管のほうで道路内の建築制限についてご説明差し上げましたが、基本的には通常の建物であればある一定程度は都市計画道路内に許可を受けて整備できるですけれども、どうしても今回地下構造物が伴うというところで。","voiceIndex":187,"id":"exchange-064"},{"speaker":"安藤委員","kind":"質問・要望","question":"不可能と書いているわけではないのです。私が伺ったのは、地階を有しないことと書いているのですけれども、エレベーターというものがつくれないという法律的な根拠はあるのですかというか、その法律の内容を説明してほしいのですが、そこはちょっとしっかりとお知らせいただきたいと思います。ですから、ちょっとそれはおかしいということを言いたいと思います。","respondent":"長尾建築課長","answer":"都市計画道路内に仮にエレベーターをつくる、つくろうとした場合、こちらの中延駅の場合ですと、当然地下の駅にエレベーターを通過させるということは、地下の構造物をつくるということになりますので、都市計画法の第５３条の許可要件に合致してこないということになりまして。","voiceIndex":190,"id":"exchange-065"},{"speaker":"安藤委員","kind":"質問","question":"大崎駅にもありますが、それは１１５cmぐらいなのです。ただ、すごい人がここを通ってくるので、それでいいのですかという問題はあるかもしれないですけれども、例えばピーク時の時間帯には下り運行にするなど、運用の工夫でこういった混雑にも対応できるのではないかと。だからエスカレーターの設置というものは現状でも可能なのではないかと思うのですけれども、区のお考えがあればお伺いします。","respondent":"鈴木都市計画課長","answer":"今ご紹介いただいた、やはり細い１人乗り用のエスカレーターを設置すれば、ある意味今の階段の幅が確保できずに、朝のラッシュ時にどういった影響を与えるかということも含めて、これは東京都がしっかり検討いただくことですけれども、その検討の中において。","voiceIndex":192,"id":"exchange-066"},{"speaker":"大沢委員","kind":"質問・要望","question":"利用者の利便性を向上するための取組みとして、さまざまなものの１つにエレベーター、エスカレーターの設置を求めるという声が請願として出てきておりますけれども、この駅の利便性を増すことについては、都との協議というか、やりとりをしていくということで、これ非常に前向きな今後の姿勢を感じることができましたことから、これは今後の成り行きを見ていきたいということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":195,"id":"exchange-067"},{"speaker":"松永副委員長","kind":"意見","question":"理由を述べします。しかし、乗降客や今後のことも考えますと、Ａ３出口を利用される方は約８割を超えておりますので、ぜひ東京都と今後協議をしていただき、それから議論をし、決めていかれることが望ましいと考えまして、この請願については継続とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":200,"id":"exchange-068"},{"speaker":"筒井委員","kind":"質問","question":"私は、先ほども課長からご答弁ありましたとおり、都と協議や話し合いをされていくということで、その都との話し合いの内容を、引き続きその推移を見守っていきたいと。それでまた議論していきたいということで、継続でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":201,"id":"exchange-069"},{"speaker":"安藤委員","kind":"質問","question":"私はこの書いているとおり、そうすべきだと思うのですけれども、区はそれぞれどのように考えているのか、またどのように検討していくお考えなのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"どういった形で検討を進めるのかというところもご質問いただきましたが、質問のご趣旨としては、検討会議体のことでよろしかったかと思うのですけれども、会議体につきましては平成２６年に設置しております地域交通検討会、この会議体を活用しながら。","voiceIndex":206,"id":"exchange-070"},{"speaker":"安藤委員","kind":"質問","question":"今の時点でどのように考えているのか、伺いたいと思います。それと検討会のほうはこれから聞こうと思っていたのですけれども、その前にちょっとごめんなさい。料金を低額にすべきということです。私もそうあるべきだと思うのですけれども、これについての区の考えは、現時点でどうなのか伺います。","respondent":"鈴木都市計画課長","answer":"それからあと、導入するに当たって区の基本的な考え方ですが、これも第３回定例会でご説明しましたけれども、例えば鉄道、バス等が区民の生活には本当に必要不可欠なインフラだというようには認識しています。","voiceIndex":208,"id":"exchange-071"},{"speaker":"安藤委員","kind":"質問・要望","question":"それ以外は１００円程度の低廉な料金にするようにということを会派としては求めたのですけれども、やはりなぜこの場で事業採算性という言葉が何度も出てくるのかと。このコミュニティバスというものは、採算をとることが目的ではなく、やはり区民の生活向上、そして移動する権利をしっかり保障するという観点から必要な事業なので、そこはなぜなのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"やはりそこは事業採算性という視点をバスの運行、状況によっては民間と協定を結ぶ等でやっていただく、あるいはどういったやり方があるかということもこれからですが、その中でこの視点を抜きにして進めるということは、当然ながらあり得ないわけでございまして。","voiceIndex":210,"id":"exchange-072"},{"speaker":"安藤委員","kind":"質問・要望","question":"その視点だけが突出しないようにといいますか、その視点を強調する余り、このコミュニティバスの本来の目的というのですか、それを外さないように、しっかりその辺は気をつけていただきたいと思います。その会議体の話で、先ほど平成２６年設置の検討会を活用しながらという話もありましたけれども、あの検討会というものは今開店休業状態ですが、これを再開するということなのですか。","respondent":"鈴木都市計画課長","answer":"これ行く行くは法定会議、導入する場合の法定会議体もありますので、おおむねそのメンバーは同じメンバーになりますが、しっかり国の運輸局と交渉していく中では、そうした法定会議体への移行が必要になってきますので。","voiceIndex":212,"id":"exchange-073"},{"speaker":"安藤委員","kind":"質問・要望","question":"そして私は、例えば各地域から満遍なく複数の公募の区民の参加というものも、しっかりと区内にある交通不便地域、駅からの距離だけにとどまらない、暮らしている方々や各地域からのニーズをくみ上げる点でも、八潮地域、品川地域、大崎地域というようになるのかはわからないのですけれども、各一定のエリアそれぞれから満遍なく、複数の公募区民の参加というものが必要だと思うのですが。","respondent":"鈴木都市計画課長","answer":"地域交通検討会のメンバーについてですが、現在学識が２名、それからバス事業者、タクシー事業者、それから住民または利用者の代表の方、それから交通管理者、道路管理者、区の職員が入っているというところが、今の会議体です。","voiceIndex":214,"id":"exchange-074"},{"speaker":"安藤委員","kind":"質問・要望","question":"このようなものはやるべきだと思うのですけれども、いかがでしょうかということをもう一度お伺いしたいと思います。あわせてこの内容です。行きたいのだけれども行けない。ですから、区民ニーズが高い行き先、今述べたようなそれぞれについて、ニーズが高い行き先にアクセスしているバス停や鉄道の駅の位置、距離というものがどうなっているかという、このような基礎調査が必要なのではないかと。","respondent":"鈴木都市計画課長","answer":"それからルート等のところですが、その会議体において検討いただくための準備、資料づくり、これはいろいろ本当に断片的なところではなくて、しっかりご議論いただくように準備をして、よりよい形に進んでいくように、ご議論が活発になるように。","voiceIndex":216,"id":"exchange-075"},{"speaker":"安藤委員","kind":"質問","question":"しっかりここに書かれていること、請願の内容というものはやはり区民の願いを書いているとすごく思うのです。最後、ごめんなさい、１点だけ。自分で言うのもなんですけれども。行き先との関係での調査というものはしないと、そこの行き先と各エリアとの位置関係、ネットワーク関係、そういうもの、行き先との関係での調査というものはどうしても必要だと思うのですが、その点についてもう一度お伺いします。","respondent":"鈴木都市計画課長","answer":"今ご紹介いただいた内容も含めて、しっかり検討していきたいです。","voiceIndex":219,"id":"exchange-076"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、品川区としては地域公共交通会議等々で想定外の出来事がない限り、品川区としてコミュニティバスを運行させるという方向でよろしいのでしょうか。","respondent":"鈴木都市計画課長","answer":"基本的には実施していく方向で検討していきたいですが、まずはどういった枠組み、あるいはそういった事業採算性を含めて、ゼロベースというわけではございませんけれども、導入を見据えておりますが、やはり基礎的なところから積み上げていきたいと考えています。","voiceIndex":221,"id":"exchange-077"},{"speaker":"筒井委員","kind":"質問","question":"地域公共交通会議でいろいろとお話しされることだと思うのですけれども、まずこのコミュニティバスは完全に区営でやっていくのか、それとも民間委託でやっていくのか、その辺の方向性は今どの程度お考えなのでしょうか。","respondent":"鈴木都市計画課長","answer":"そこもしっかり検討していく予定なのですが、ほかの自治体の今までの事例を見ますと、区営でやっているということは余り、やはりノウハウ等もありますし、交通安全、バスの安全性の問題などといったところから、区が直営でやるということは。","voiceIndex":223,"id":"exchange-078"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。事業採算性というお話も出ております。いろいろアイデアやお考えはあると思いますけれども、ただ漫然とコミュニティバスを走らせるだけではなくて、走らせることによって、今言ったように防災や環境、シティプロモーションなど多分野にわたって効果があるようなものにしていったらいいのかなと思っていますが、その点品川区としてはいかがお考えでしょうか。","respondent":"鈴木都市計画課長","answer":"それにプラスアルファして、今ご紹介いただいた、そうしたプラスアルファといいますか、検討していく中で、経費削減として車両の小型化や維持管理費の削減、あるいは路線ごとの、これもまた具体的な話になりますが、その路線数や曜日での増減、そうした。","voiceIndex":225,"id":"exchange-079"},{"speaker":"筒井委員","kind":"質問","question":"特に今までの地域交通検討会ですと、町会の場合は町会連合会の会長だけしか参加されていないようですけれども、このコミュニティバスという性質上、やはり品川区の１３地区から代表を出して参加していただくことや、また、適宜区民アンケートやパブリックコメントというものをやっていかれて、幅広い区民のお声を聞いていったほうがいいかなと考えていますが、その点いかがお考えでしょうか。","respondent":"鈴木都市計画課長","answer":"地域交通検討会と、後に移行する法定会議体での、特に区民の方の参加の仕方については、平成２６年に設置して、一定程度時間もたってありますので、この会議体を基本に、まず来年度検討を開始したいところですが、そうしたメンバー、特に区民参加について、そこも含めて。","voiceIndex":227,"id":"exchange-080"},{"speaker":"大沢委員","kind":"質問・要望","question":"その中には他区がやっている、他自治体がやっているからとか、時流の中での雰囲気を感じてならないのですが、１回これ路線を走らせてしまうと、やめることはなかなかできないものですから、いろいろな課題もあると思いますけれども、そこのところはしっかりと、先ほど来お話に出ているように、１００円バスなどいろいろな名前、名称がありますが、採算性はある程度考えてやらないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":230,"id":"exchange-081"},{"speaker":"あくつ委員","kind":"提案","question":"継続ですが、一言意見を述べします。その上で私どもの会派で、まずこの法定の地域公共交通会議というものを設置して調査をしてみたらどうだというご提案をさせていただいて、区のほうでは法定ではないけれども、地域交通検討会というものをつくっていただいたのですが、２回開いて３年間とまっていたという事実もあります。私はこのように感じています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":231,"id":"exchange-082"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択でお願いしたいのですけれども、やはりコミュニティバス導入ということは、切実な区民の暮らしの実態から出てくる声なのです。やはり世論と運動の結果だと私は思っております。この請願については、ここに書いてあることは非常に実効性ある、コミュニティバスを実現させるに当たっては必要な内容だと思いますので、私は採択ということでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":232,"id":"exchange-083"},{"speaker":"松永副委員長","kind":"意見","question":"我が会派は、継続とします。理由は前回と同様で、今後関連団体などと地域交通検討会で既存路線との競合などの議論を検討されていくということでしたので、その検討会の動向を見て、今後について考えていきたいと考えていますので、この請願に関しては継続とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":233,"id":"exchange-084"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、採択ですが、コミュニティバスの運行をしてくださいという内容なので、採択していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":239,"id":"exchange-085"}]},{"id":"topic-04","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"報告第２４号で、これ「同車の後輪等を破損した」ということで、損害賠償云々かんぬんで修理費等という、「等」には何が含まれるのですか。","respondent":"多並道路課長","answer":"それ以外に、この方は自転車で通勤されている方で、その修理に１日かかってしまった関係で、その関係での代替の交通費用も含めてということで、この方が碑文谷から通っている方でしたので、そのバスの費用と電車の費用ということで。","voiceIndex":247,"id":"exchange-086"},{"speaker":"安藤委員","kind":"質問","question":"現場の検証のようなものをしたと思うのですけれども、その状況から、なぜ街路樹が強風に耐えられなかったかなどの原因というものは判明したのでしょうか。報告第２４号は、こういったことで今回はパンクだということなのですけれども、歩行者や自転車の転倒、けがなどにつながる可能性もあるのかと思うのですが、同様の箇所がないかという点検の体制というものはどうなっているのかお伺いします。","respondent":"多並道路課長","answer":"それが風で、今回のこの９ｍぐらいの風でそれが落っこちてきたということが原因だと判断しておりますので、今後の対応といたしましては、やはり剪定作業や、あと定期的な点検の中で、そのようなことがないかということで、点検を徹底していきたいということで。","voiceIndex":249,"id":"exchange-087"},{"speaker":"筒井委員","kind":"質問","question":"この２件とも、過失というのは区の点検義務違反によるものだということ、そういった意味で過失とおっしゃったのでしょうか。","respondent":"多並道路課長","answer":"今委員のご指摘のとおり、我々の今までの事例と、あとは契約されている保険会社といろいろなほかの過去の事例などを勘案して協議させていただいて、ご本人と示談した結果、やはり区のほうが全体的に過失があるということで、このような結果となりました。","voiceIndex":252,"id":"exchange-088"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4250#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":62568,"voices":257}},{"id":"h30-20181210-9","meetingId":"h30-cm12","date":"2018年12月10日","dateIso":"2018-12-10","committee":"文教委員会","time":"午前１０時００分～午後 ２時０３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第９２号議案、指定管理者の指定","agenda":"第９２号議案、指定管理者の指定","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"４の候補者選定経過のところの（１）、候補者を公募せず現在の指定管理者を候補者とするという、ここの品川区指定管理者制度活用に係る指針のところにかかわって教えていただきたいと思います。よろしくお願いします。","respondent":"吉田保育施設調整担当課長","answer":"ホームページでも公開しておりますけれども、品川区指定管理者制度活用に係る指針というのがございまして、その中で、一定程度、継続性とか、特殊な事情が必要なものにつきましては、候補者を公募しないで選定委員会を行っても構わないこととなっております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"１０月でしたか、モニタリングの総括があったのですが、そこの総括の改善の必要性のところで、１つ質問したのですけれども、保育士の確保が依然厳しい状況ということと、職員の定着化、離職・転職の防止、処遇改善という項目があったので、その辺をどう捉えていらっしゃるのかということと、第三者評価の率がとてもよいという報告があったので、第三者評価。","respondent":"吉田保育施設調整担当課長","answer":"職員の処遇の面ですけれども、キャリアアップ補助金、保育サービス推進費等を活用しまして、特別賞与を上げるなど、そのような対応を積極的に行っております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"第三者評価のところも、やはり保育園のところだけ。ということは、３歳以上の、ここのＮＰＯ法人で行われています乳幼児の教育施設で、乳幼児のところの評価というのは、第三者評価的なものできちんと評価をされているのかどうか、そこをもう一回お伺いします。","respondent":"吉田保育施設調整担当課長","answer":"そこのところは、現行の仕組み自体がゼロ歳児から２歳児までが保育園でございまして、３歳児から５歳児までにつきましては幼児教育施設、認可外保育施設という形になっているところは、今も変わっておりません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"今のところはすごく大事です。一般の幼稚園とか区立の幼稚園に勤めると経験年数が加算されるけれども、ぷりすくーるのここは加算されない。前からの課題だったと思うのですが、認定こども園に移行すれば、ここのところは改善されていくのかどうか、そこがとても気になっているので教えてください。","respondent":"吉田保育施設調整担当課長","answer":"認定こども園に移行した場合は、認定こども園という施設になりますので、認定こども園で働いたというキャリアになるところです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"よくわからないですが、認定こども園に移行すると、保育園のところも、乳幼児教育の幼稚園の部分も、両方きちんと経験年数としてカウントされるのかどうか、そこをもう一回お伺いしたいのと、この先の見通しが何かあるのだったら教えていただきたいと思います。だから、そういうところも含めて、改善がされて評価がされているのかというのを私は知りたいと思っているので、１点そこを教えてください。","respondent":"吉田保育施設調整担当課長","answer":"そこで例えばゼロ歳児から２歳までが保育園だというわけではなくて、認定こども園という枠組みの中では、あくまで就学前のゼロ歳から２歳までは保育を実施する、それから、それ以降のところでは教育を実施する。このようなイメージです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つは、児童福祉法だけではなくて、子ども・子育ての法律ができたことでの一方の中身だと思って受けとめました。この間のモニタリングの総括の中で、幼保連携型の認定こども園の移行について、若干議論になったかと思うのですけれども、今の形から認定こども園に移行するに当たって、課題が何なのかをもう一回明確に教えてほしいのですが、この間、園庭が今の状態だと認定こども園にならない。","respondent":"吉田保育施設調整担当課長","answer":"幼保連携型認定こども園に移行するに当たっては、２点の問題があります。１点は、認定こども園につきましては、都で申請する際に、各年代層に何人いるか、それによって園庭が何平米要るかというところを細かく定めてあります。","voiceIndex":15,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"意見","question":"今、社会福祉法人化が平成３２年ということなのですけれども、指定管理が今回５年です。この途中でＮＰＯから法人になることについて、問題はないのかというお答えがなかったので、その辺の課題、何かクリアするような問題があるのかどうか、聞かせてください。","respondent":"吉田保育施設調整担当課長","answer":"答弁が漏れました。ＮＰＯ法人で今回受託して、その後、例えばＮＰＯ法人が社会福祉法人になった場合、そのまま継続して指定管理をするということについては、他の自治体でも例はありますので、特に問題がないと認識しております。","voiceIndex":17,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"園庭問題は、具体的に足りないのを、あそこの周りを見ても、どうするのかなと思ったのですけれども、それはどのように改善できるのか、何かめどがあるのかどうかを教えてほしいのと、途中で社会福祉法人に変わっていくことは問題ないということなのですけれども、社会福祉法人化されたらプロポーザル方式を使ったりとか、そういうことはないのか、今までどおり。","respondent":"吉田保育施設調整担当課長","answer":"プロポーザルとかをやるかどうかですけれども、今回、もしご承認いただけた場合、この５年間につきましては、ＮＰＯ法人が社会福祉法人化したことによるものですので、特にその間にプロポーザルをする等、そういうことは予定しておりません。","voiceIndex":19,"id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、もっと努力をしていただきたいと思っているのですけれども、その辺について、どういうふうに考えているのかというのが１つと、それから、一般的には公務員の保育士も、私立で働いてきた部分は２分の１加算というのがあります。そういうことが該当できるような工夫というのはないのかなと、さっきの質疑を聞いていて思ったのですけれども、その辺についてどうなのかを伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"その制度として、例えば勤めたところが私立保育園でも認可保育園であれば、認可保育園に勤務したという経歴になりますし、ぷりすくーるの幼児教育部門であれば、幼児教育部門という対応になると考えております。","voiceIndex":22,"id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"できるだけ私は長く、４.４年にとどまらずに、１０年、１５年とその地に足をしっかりつけて、保育という仕事に専念していただきたいと思うわけです。しかし、平均ですけれども４.４年しか長く勤めてこられないという状況をなくしていくには、どうしたらいいかというところでの考え方を、区としてはどういうふうに持つのかという、そこのところをまず聞きたいと思っているのです。","respondent":"吉田保育施設調整担当課長","answer":"区としましては、例えば長く勤めていただくというのは、ある意味、質の向上につながるのかなと考えておりますので、キャリアアップ補助金とか、各種補助金とか、その辺を含めまして、できる支援を行っていくところです。","voiceIndex":24,"id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"そういうのもあるので、次のところに行くに当たって、キャリアにならないのだったら、短い期間で次に転職をしていったほうがいいのではないかというマインドが働くのは当然だと、あり得ると思うので、そういう点で私は、キャリアにしっかり定着できるように、カウントできるように、私立保育園の２分の１保障するということに、同じように該当させるべきではないかと思って。","respondent":"吉田保育施設調整担当課長","answer":"現行の制度上、いろいろなところに履歴書などを出す場合にも、次の採用される側がどう受けとめるかというところであると思います。一般的には、履歴書とかに書かれたところを受けとめて、どう評価するかというのは、採用する側の判断と考えております。","voiceIndex":26,"id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"そうであれば、長く定着することなど、あまり期待できないと思うのです。そういうときに、こういうＮＰＯで、他の働いていた期間が加算されないということになると、その人にとって不利益になるわけですから、そこはきちんと保障するということが大事であって、そういう方策を何らかの方向で検討するということが、今はとりわけ人材確保という点からも、必要なのではないかと思うのです。","respondent":"福島子ども未来部長","answer":"それともう一つ、キャリアという面では、認定こども園化も区としては支援していきたいと思います。ただ、どういった形での認定こども園になるかは、これから検討しますけれども、いずれにしましても、国から認められるような認定こども園化を目指す。","voiceIndex":28,"id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"社会福祉法人化の中で解消できるという話なのですけれども、それはそれとして受けとめたいと思っています。しかし、１５年間の間のその部分の不利益というところは、一定考慮していくべきではないかと思いますので、繰り返しますけれども、ぜひ検討していただきたいということを強くお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"賛成します。意見を２点。今、職員の方の処遇のお話がありましたけれども、児童福祉法に子ども・子育て支援法と、新しい法律ができて、２つの法律の中で、私は保育園もすごく複雑な状況になっていると思いますけれども、新しい法律の中で社会福祉法人化が進めば、いろいろ改善されるところも出てくると思うので、ぜひその辺の支援を十分していただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"意見","question":"賛成です。今の社会福祉法人化と認定こども園化を目指すということで、これを区として支援し続けるという部長のお話がありましたので、ぜひスピーディーに進めて、品川区の施設のさらなる発展のために、ぜひ区として支援をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":37,"id":"exchange-015"}]},{"id":"topic-02","title":"第９８号議案、訴訟上の和解","agenda":"第９８号議案、訴訟上の和解","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"品川区、また教育委員会の立場はおいておいて、当然６年前のことで中学生ですから、亡くなられた方も被告の方々も成人を迎えるようなお年ごろになって、これから生活を続けていただくわけですが、今回、和解がこのタイミングで、話し合われていたということで丁寧な説明をいただいたのだけれども、出てきたというのは、あくまでも聞きたいのは１つ、それを私たちも議会だから審議していかなければならなくて。","respondent":"有馬庶務課長","answer":"全体の補足ですけれども、裁判の関係は、この間３５回、いろいろ審議されたということですが、最終的に証人尋問が終わったのが平成３０年１月１０日ということで、これまでずっと審議が続いてきたということで、和解のタイミングもそこになったということです。","voiceIndex":43,"id":"exchange-016"},{"speaker":"渡部委員","kind":"質問・要望","question":"わかりました。これは私たちも当然、賛成をしていくところですし、これ以上何を言うわけではありません。ただ、この先、品川区が義務教育学校を含め、小・中学校をずっとやっていく中で、こういう機会ですし、今後このような議案が出てこないことは当然なのだけれども、そういった意味で、これからいじめに対する取り組み、教育委員会の考え方を、一言ここで聞かせていただきたいと思います。","respondent":"大関教育総合支援センター長","answer":"これまでも、いじめはどの学校にも誰にでも起こり得るということを大前提として踏まえながら、早期発見をして、できることであれば未然に防止するため、今後とも対策チーム、またオール品川で、地域の方やさまざまな団体の方とも情報を常に共有しながら。","voiceIndex":45,"id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"今、渡部委員もおっしゃったけれども、本当につらい問題でした。本当に、いじめ防止のためのいろいろな仕組みをつくったにもかかわらず、そういう状況になってきているというところについて、この件とはちょっとそれますけれども、まずそこは伺っておかなければいけない問題だと思いますので、その点について、区の見解を伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"したがいまして、いじめを見逃したことにより命が失われてしまうという事案は、その後は起きていないと教育委員会事務局としては認識しています。","voiceIndex":49,"id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"何回か自死がありました。それは、今の答弁を聞くと、いじめではなかったのかなと思ったのですけれども、そういうふうに言い切ってしまっていいのですかということを伺いたいと思います。区としては、そこをどういうふうに思っているのか、見解を伺いたいと思います。それと、２ページを見ると、校長が、必ずしも調査が十分でなかったと裁判でおっしゃっているのでしょうか、ここに書いてありますから。","respondent":"塚本委員長、大関教育総合支援センター長、有馬庶務課長","answer":"かなり裁判の中身の非常に難しいところにも触れているので、答えられる範囲でということでお願いします。今後とも学校といたしましても、全校でストレスの出し方という部分は継続して子どもたちに指導してまいります。教員の対応が十分でなかったのではないかということについてということですけれども、今回、被告教諭・校長それぞれ、この和解文を確認していて。","voiceIndex":51,"id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"必ずしも十分でなかったと認めたと。具体的にどこが十分ではなかったのかというところは、はっきりさせなければいけないと思います。一般論で終わらせたら、再発する可能性があると私は思いますので、改めて具体的なところを、ぜひ指摘していただきたいと思います。それを全ていじめではないと思っていいということですか。最終的に確認をしたいと思います。","respondent":"大関教育総合支援センター長、有馬庶務課長、熊谷指導課長","answer":"いじめを起因とする事案はないと認識しております。いろいろ裁判所がこの間、事実関係を調査しましたけれども、最終的には、全体として和解するときにこのような表現になって。こちらの調査なのですけれども、調査報告書が不十分であるということではなくて、いじめがあるかどうかということについて。","voiceIndex":55,"id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"だから、私はむしろ、そういうところが問題だと思うわけです。そういうことをしてはいけないと指摘をして、改善を求めるという質問をしました。きちんと、どんなに忙しくても、命にかかわる問題だから、いの一番にその子どもの言っていることを聞いた結果、「何だ、こんなことか」と思うこともあるかもしれないけれども、しっかり聞く。しかし、そういうことが……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"簡潔です。人の命がかかっている問題だから、議案ですから言っているのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"もちろんです。わかりました。したがって、ぜひそういうことについての見解を伺いたいと。教員は普段忙しいですから、ついついということがないようにしてほしいということを強調したくて繰り返しましたので、よろしくお願いします。それと、この和解については両当事者の間の合意ですから、これについてどうこう言うつもりは全くありません。","respondent":"大関教育総合支援センター長","answer":"例えば相談を受けた担任が、１人で課題を抱え込んでしまうことのないように、学校が組織的に対応して、さらに教育委員会がそこを支援できるように、学校支援チーム、ＨＥＡＲＴＳも応援に当たっております。","voiceIndex":63,"id":"exchange-023"},{"speaker":"つる委員","kind":"質問・要望","question":"本議案については先ほど来、確認があったとおり、それぞれの原告・被告という形、裁判上ですけれども、そうなっている方々の和解ということで、それはそれとして、しっかりとこの委員会で、私としては受けとめ、そして対応していかなければいけないというところがある前提の中で、あえて言うと、そうしたことについて、この委員会の場で先ほどあったような言い争いで。","respondent":"大関教育総合支援センター長","answer":"品川区いじめ根絶協議会では、教育委員会だけではなく、地域の方あるいは関係各所の皆さんから、ご意見を毎年、毎回いただいておりますので、今後ともこれを継続して、二度とこのような悲しい事案を生まないように、努力を継続してまいります。","voiceIndex":66,"id":"exchange-024"},{"speaker":"つる委員","kind":"質問","question":"亡くなった方も含めて、その思いをしっかりと受けとめながら、前に進んでいくという教育委員会、さらに現場の教員の方々の支援も含めて、児童・生徒が本当に明るい未来に進んでいけるように、私自身が当時の教育委員会をはじめ、教員の方々に育てていただいたから、今ここにこうやっていられるわけですから、そうした希望となる現場の教育の支援になることを、これからも一生懸命お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"原告のご両親の深い悲しみは、絶対薄れることはないだろうし、またこの間、どうして、なぜという思い、疑問がとれることもないと思っています。人の命がとても大事なのだということを本当に体感したところで、今後の人生に活かしてほしいと思っています。だから、教育委員会だけの問題ではありませんが、そういうのを発信する教育委員会に変わっていただきたいと思うのですが、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"これは今も継続しておりますし、今後も続けていきたいと考えております。","voiceIndex":70,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"子どもの権利条約の話をしましたけれども、本当に日本の教育全体についても、ぜひ発信をしていただきたい。なぜかというと、受験のストレスはとても多いし、教育要領が変わるたびに授業数が増えて忙しくなっている子どもたち。私は本当に日本の教育行政は、とても子どもにストレスを与えていると思うのです。そういった立場に立っての発信をしていただきたいと思うのですが、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"あるいは、中には直接教育総合支援センターに来て、学校生活について相談したいということで、ＨＥＡＲＴＳのカウンセラーのところへ直接来てくれた案件等もありますので、いろいろな形で子どもの意見というものは拾っていき、丁寧に対応していきたいと考えております。","voiceIndex":72,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"表面化していないところにも、ぜひ目を向けていただきたいという意味で、私は教育総合支援センターの部分をもっと充実させていただきたい。この間、名古屋に視察に行ったときは、いじめの問題とかそういった問題を、経験豊かな人たちが、独立したところで扱っているというのを聞いたので、ぜひ教育総合支援センターの充実をお願いして、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-028"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"特に、被告側の子どもたちも、これを機に新しい人生というのを迎えるわけでありますので、ぜひ原告側・被告側両方の一歩を踏み出すときに何かあれば、それは教育委員会はじめ、品川区としてもサポートできることは、しっかりサポートを続けていっていただきたいと思いますが、その点について何かあれば、お聞かせください。","respondent":"大関教育総合支援センター長","answer":"教育委員会といたしましては、命に関するさまざまな、心のフリーダイヤルですとか、そういったところで専門の心理士が対応していますので、今回の件もまた、原告の方・被告の方それぞれ立場はあるかもしれませんが、何か相談という部分が入りましたら。","voiceIndex":76,"id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"質問","question":"それはなぜかというと、改めて今後の品川区の教育をこうしていくのだということを、きちんと示すことになるのだと思いますので、そのことについて。もう一つは、もしお答えできなければ全く構わないのですけれども、（７）の品川区が賠償をするという本件解決金ということなのですが、これは教諭と校長の監督責任といいますか、区立学校ということで、それを含めてということなのでしょうか。","respondent":"有馬庶務課長","answer":"教諭の部分については、教諭それぞれ考えていただくべきものかなと捉えてあります。今回の解決金については、品川区に関する内容ということになっているものです。","voiceIndex":79,"id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれありがとうあります。公表に関することと、解決金の話ですけれども、そういったことも含め、今後の対応は未来につながるような形で、しっかりやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-031"},{"speaker":"鈴木（博）副委員長","kind":"質問・要望","question":"だから、子ども同士できちんとそれをキャッチして、大人にしっかり援助を求める態度というのは非常に大切だということを、かなり強調されていたのですが、それというのは、電話が来るのを待っているのではなくて、正規の授業でしっかりと援助希求的態度を自殺予防の一環として強調して、教育するべきだと思うのですが、今現在、教育されているのかと。","respondent":"大関教育総合支援センター長","answer":"ゲートキーパー研修をはじめ、大人の教育の部分ですが、これは保健予防課とも連携を進めておりまして、ゲートキーパー研修に各校教員が参加することもしておりますし、また、品川教育の日として、教育委員会主催の教員研修の中で、命の大切さ、今度は教員として。","voiceIndex":83,"id":"exchange-032"},{"speaker":"鈴木（博）副委員長","kind":"質問・要望","question":"いじめというのは一部だけですから、その飛び飛びが一番すごく大切で、自殺するとみんなが不幸になりますから、その辺はもう少し高度な取り組みというのが必要なのではないかと常に思っているので、１つの希望も交えて、質問させていただきたい。","respondent":"大関教育総合支援センター長","answer":"保健予防課と教育委員会で、これまでも自殺予防について協議している中で、ＳＯＳカード等も生まれてきておりますが、今後につきましては、またご提案いただいたような医師ですとか専門家の方に助言をいただいたり、あるいは必要な内容について講義いただくなどの機会。","voiceIndex":85,"id":"exchange-033"}]},{"id":"topic-03","title":"平成３０年請願第２３号、学校給食の牛乳にプラスチックストローを使用しないことを求める請願","agenda":"平成３０年請願第２３号、学校給食の牛乳にプラスチックストローを使用しないことを求める請願","exchanges":[{"speaker":"南委員","kind":"確認","question":"企業が紙のストローを使用することにするということも新聞等々で報道されていますけれども、自治体が率先してそういうことをやっていくように、検討を始めるということが必要なのではないかと考えていますけれども、改めてその点について、先ほどの話ではなかなか難しいというのが先に立ってしまう答弁かなとは思うのですけれども、改めてその辺を確認したいと思います。","respondent":"篠田学務課長","answer":"かといって、このまま放置しておこうということではなくて、社会的な動きですとか、他自治体の動きですとか、さまざまなものを注視しながら、なかなか私どもの教育委員会が先行してということは考えていないですけれども、きちんとした対応を今後もとっていきたい。","voiceIndex":98,"id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"確かに先ほどの説明で、瓶のリユースを考えていくということも１つの方法だと思いますし、私も子どものときですから、はるか何十年も前ですけれども、瓶による牛乳が給食で出て、先のとがったものでふたを外して、その処理というのは新たにありますけれども、それで飲んでいたと。教育のところで、いろいろ議論はありますけれども、品川区の教育行政は、先行してやっているではないですか。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"いずれにしましても、先ほどの瓶の使用に関しましては、申し上げたようないろいろ解決しなければいけない課題がありますので、そういったものを踏まえまして、現状このままということではなくて、今後。今回、区内の小学校でストローに関する授業等は、マスコミ等の報道でも案内があったところですので、その学校だけでなく、ほかの学校でも、関心を持っている子どもたちは確実に増えていると思いますが、今、何が一番いいかということは。","voiceIndex":100,"id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、ここの請願では、品川区から都・学校給食会・乳業者の３者へ声を挙げて頂きたく要望させて頂きますという請願の内容なので、本当にそういう形で上げていけるような結論を、この委員会で導き出していく必要があるのではないかと私は思っているのですけれども、先ほどの説明の中では、関係機関に働きかけていくのは可能なことなのだという区の認識も紹介されましたので、私としてはぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-036"},{"speaker":"渡部委員","kind":"質問","question":"３者に伝えることは伝えられるというところなのだけれども、実際問題として、さまざまな取り組みがあるではないですか。例えば、ストローをまずやめることを考えて、つけてもらうのをやめて、コップを持ってきて飲みましょうとかというのは、みんなで話し合って、そこからやっていこうよとかというのは、難しいのか、簡単にできるような気もしないではないのだけれども、実際どうなのですか。","respondent":"篠田学務課長","answer":"大人であれば、あまり気にならないところも、お子さん方一人ひとり違っていますので、そういったところをどういった形で対応ができるのかということを考えざるを得ないと思っていますので、いろいろな形の提案はあろうかと思いますけれども、そういったものを踏まえながら。","voiceIndex":105,"id":"exchange-037"},{"speaker":"渡部委員","kind":"意見","question":"ただ、そうなっても、ＣＯ２の排出量がというところにもなっていくから、すごくイタチごっこというか、そういうところがあると思うので、ウミガメのおなかの中にとか、例えばマイクロプラスチックというのは、２３区の場合は私は事情が違うと思うのだけれども、世界的環境のことを考えると、やはりみんなで考えていかなければならないことなのかなというところも鑑みて、今回は採択していこうと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":107,"id":"exchange-038"},{"speaker":"つる委員","kind":"確認","question":"今、各委員からあった、至極そのとおりだと思います。幾つか確認で、先ほどご説明の中では、紙ストローが１０倍ぐらいになる様子である。逆にプラスチックストローの、学校に今、供給されているもので結構なのですが、プラスチックストローの単価というのはお幾らなのか、わかれば教えてください。","respondent":"篠田学務課長","answer":"ただ、一般的なところで調べたところ、給食で出されているようなストローが、市販でいくと１本当たり０.５円ぐらいで販売されていますので、当然、大量にメーカー等は仕入れていますから、それよりはるかに安い金額ではあるのだろうなと考えているところです。","voiceIndex":109,"id":"exchange-039"},{"speaker":"つる委員","kind":"質問","question":"それはそれで、まだ単価が高いとかいろいろあるので、基本的には区としては、この請願にもあるとおり、特に乳業者か、製造メーカーというところになっていくのかわかりませんが、そうしたところに技術開発だとか、大きい部分では依頼したりとかという流れにはなるのかなと思うのですが、まず現状のもので、コップを持参してもらうとかということも含めてあるのですが、そもそも今。","respondent":"篠田学務課長","answer":"今、各学校で提供されている紙パックは、例えば５００ミリリットルとか１リットルの牛乳パックと同じような、頭が三角になったものが非常に小さくなってコンパクトになったような形で、その上の斜面のところをめくると穴があって。","voiceIndex":111,"id":"exchange-040"},{"speaker":"つる委員","kind":"質問","question":"当然、大前提はエコだとかというところであるそうなのですが、各地域によっては保護者の方から、マナーとか、衛生的にどうなのかとあるわけですが、基本的に各児童・生徒一人ひとりに配られる牛乳というのは、飲み切りサイズというか、２００ミリリットルぐらいになるのでしょうか。だから、まずマナーとか、また自分で飲み干すのだから、衛生的にどうだという、この辺の考え方を教えてください。","respondent":"篠田学務課長","answer":"ただ、１つは、ストローになれている地域の方から見ると、結構抵抗があるようですので、そういった形でのご理解、品川で実施した場合に、どういった形でご理解を得ていくかといったことが１つと、それからもう一つは、衛生的な部分とか取り扱いの部分で、おそらく小学校の中学年。","voiceIndex":113,"id":"exchange-041"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう社会的な動きも当然、もっともっと動いていただきたいというところがあるのですが、その部分で、あとは、これは可能性ですけれども、例えばお膝元の私たちの品川区で、実は来年の４月の製品発表に向けて、区内にある企業の方、紙コップの国内シェア最大の企業があって、そこが紙ストロー、それから紙のふたの製造販売を今、進めているということを確認できました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-042"},{"speaker":"石田（し）委員","kind":"質問","question":"東京都と学校給食会と乳業者がいて、品川区だけでプラスチックストローを使わないということが、現実的にできるのかどうかというのが、まず１点。できないのであれば、どうやったらそれが可能になるのか、その方法というのがあるのかどうか、まず教えてください。","respondent":"篠田学務課長","answer":"ただ、そうしたときには、その代替の手段がきちんと確立していないと、当然それは話ができませんから、その代替手段をどうするかという形で、先ほど来お話が出ていたような形で、利用していく必要があるのか考えていく必要があるところです。","voiceIndex":116,"id":"exchange-043"},{"speaker":"石田（し）委員","kind":"質問","question":"わかりました。ということは、逆に乳業者がメイン。要は、飲み口がついているパックというのが今はあるわけではないですか。既に市販であります。皆さん飲んだことありますよね。先ほどから直飲みの話も出ているけれども、ストローを使わないで、そっちでやりましょうというのは、契約上可能なのではないかと思うのですけれども、そういうやり方もできなくはないのかどうか、教えてください。","respondent":"篠田学務課長","answer":"ただいまご提案のありましたような形での、パックにプラスチックの飲み口、キャップがついている形のものです。そうしますと、容器の形態自体が変わりますので、１つはそういった形態のものが、学校給食用として業者が対応できるのかどうかという検討が必要になると思います。","voiceIndex":118,"id":"exchange-044"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それをコストだとか、どうこうとかという話ではなくて、本気で品川区の教育委員会として、子どもたちも巻き込んで、こういう環境教育を、肌でみんなで感じようよというアクションを持てるかどうかだと思うので、私はこれはぜひ進めていっていただきたいと思うし、ただ先ほど、可能か不可能かわからないけれども、そういったことを品川区から発信して、２３区でみんなでやろうよというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"質問","question":"そんなところで、都内の教育委員会の指導課には課長会があるとお聞きしているのですが、今みたいな形で、課長会の中でこういった話題は出たりしているのでしょうか。そこを伺います。","respondent":"篠田学務課長","answer":"ただ、せんだって学校給食の乳業者が集まる会があったとお聞きしていまして、そこの中では各校、一部そういった声が上がってきているという形ではあったようなのですけれども、具体的に乳業者にもアクションがあったということではないと伺っていますので、まだ全体として。","voiceIndex":122,"id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"意見","question":"何らかのそういったアクションが少しずつあるということはわかりました。ぜひ、先ほどのお話にもありましたけれども、品川区が先頭に立ってというところも期待したいと思います。それこそ直飲みに合うようなパックを考えつく方も、必ずいると思いますので、そっちの方向もいいかなと思ったりします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":124,"id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ほかの委員から出ました直飲みというのも１つの考えだし、直飲みでこぼれてしまうのだったら、１年生などはコップを用意すればいいと思うのです。教育なので、現状のごみになったものがどうなるかというのも、しっかり教えてほしいと思っています。質問は、紙のパックとストローと包んである容器が、飲み終わった後、どういうふうに処理されているのかを教えてください。","respondent":"篠田学務課長","answer":"こちらに関しては、まとめて廃棄をして、品川区内では燃えるごみとして扱われますので、焼却処分がされているというものです。","voiceIndex":125,"id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は周りの袋は容器なのかなと思って。廃プラスチックを燃やすと地球の温暖化につながっていくという、そういうところも含めて、利用するところから後の処理のところまで、きちんと子どもたちに伝えていきながら、どうしたらこの地球環境を守れるのかという立場で、身近な問題ですが奥の深い問題なので、ぜひ教育に役立てていただきたいと思うのですが、その点はいかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"実際に自分たちが出したごみがどのように処理されているのか、子どもたちは見ておりますので、極力ごみは出さないようにしようと品川の子どもたちは自分で考えだしていると認識しています。","voiceIndex":127,"id":"exchange-049"}]},{"id":"topic-04","title":"平成３０年陳情第２２号、すまいるスクールの利用者ニーズ把握のためのアンケート調査の実施を求める陳情","agenda":"平成３０年陳情第２２号、すまいるスクールの利用者ニーズ把握のためのアンケート調査の実施を求める陳情","exchanges":[{"speaker":"南委員","kind":"質問","question":"今、説明があり、アンケート調査は３,０００世帯ということで説明がありましたけれども、その調査とは、ここの陳情に書かれてある、「利用者ニーズを的確に把握し」ということに応える内容でやるという理解でいいのか、そのことを１点伺いたいと思います。","respondent":"高山子ども育成課長","answer":"２点目の保護者・子どもの意見というのをどのように捉えられるかという点につきましては、繰り返しになりますが、今回の調査につきましては、保護者の意見を中心としつつも、子どもの意見もいただくような形での調査形式で進めてまいりますので、そうした意味におきましては。","voiceIndex":144,"id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"そういうところの、１８時まででいいですという家庭はともかく、それ以降も、少なくとも１９時までは見ていただきたいという方に対しては、利用者アンケートでどの程度の割合でいるのか、少なくても実態的にはあるということであれば、それも受けとめて検討しようというふうになるのだろうと思うのですけれども、具体的な１つの例を挙げて質問ですが。","respondent":"高山子ども育成課長","answer":"まさに利用者の満足度、現制度、制度改正後の今のすまいるスクールの仕組みについて、どの程度利用者と保護者の理解が得られ、そして満足度が得られているかというところを調査するものですので、例えば利用時間でありますとか、あるいは利用料金なども含めて。","voiceIndex":146,"id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"アンケートをするということなので、それはそれとして、今も質問してご説明があったので、ぜひやっていただきたいということで、見守っていきたいと考えていますが、実施時期はいつなのかと、それから来年度に向けて、そういう検討したものを活かせるというか、具体的に具現化するのは来年度からと受けとめていいのかどうか、その２点をお願いします。","respondent":"高山子ども育成課長","answer":"その関係で、適用の時期につきましては、分析の中身によって費用等を伴って、一定程度予算立てをしないと実現できないようなものにつきましては、平成３１年度を検討期間とする見直しに反映させてまいりたいと考えております。","voiceIndex":148,"id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"最後にしようと思ったのだけれども、申しわけありません。利用料金についても調査をとるような説明でした。上げるのか下げるのか、そこは不鮮明なのですけれども、上げるということではない方向で検討もしていただきたいと思っているのですが、その辺についての感触というのは、もしあれば伺いたいと思います。","respondent":"高山子ども育成課長","answer":"同時に、他区と比較いたしまして、特に品川区のすまいるスクールの利用料金が過大に負担を強いているということでもございませんし、また同時に、減免の制度もこの月額の利用を導入する際に検討して、導入した経緯もありますので、そうした減免の制度も含めまして。","voiceIndex":150,"id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"私はできれば上げない方向で検討していただきたい。その理由は、やはり子育て費用の負担感です。そういう負担感を拭っていくということが大事だし、これは少子化を克服する大きな条件になっていると考えていますので、検討するというところでは、負担感のところと、できるだけ負担を和らげるという角度で検討をするべきだと考えていますので、意見として申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"下のところで、トワイライトステイのサービスもあるけれども、料金負担が非常に大きくなると。この中身も具体的に、トワイライトステイの料金体系とかを教えていただきたいと思います。もう少し下のところで太い字で、区の対応として、利用者ニーズを的確に把握し、不断の見直しを図ってまいりますと書いてあるのですが、この辺はいつ、どのような中身で見直しをしていくのか、この３点をまずお伺いします。","respondent":"高山子ども育成課長","answer":"３点目の不断の見直しにつきましては、まさにすまいるスクール事業を継続的にいいものにしていく、利用者そして保護者に資する事業として展開する上で、行政のみでニーズについて一方的に考えるのではなく、利用している保護者と児童からの直接の意見を踏まえて。","voiceIndex":154,"id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１点目の３年生までというところは、放課後の生活の仕方の多様化と、子どもの成長に合わせてといった意味においては、特にここに書かれているのは、ひとりで過ごすことが困難な支援学級や支援学校在学の４年生、６年生ということで書かれているので、子どもの成長・発達をと考えたら、個別に特別な配慮の必要な、例えば障害者差別解消法とか、成長に合わせた対応をしていくという意味では。","respondent":"高山子ども育成課長","answer":"我々としても最大限努力はしてまいりますが、すまいるスクールが本来持ち合わせます集団生活の中での学びと成長という部分においては、ある程度事業の中で実現していける中身については、全てをかなえるということはなかなか難しいという状況もあるかと思いますので。","voiceIndex":156,"id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これは意見です。地域に住んでいる子どもが、教育と同じくひとしく選んだところで、よりスムーズに一日が過ごせるという立場においては、ぜひ差別なくというか、その子に合った利用方法を考えてほしいと思います。いろいろな手だてがあるので、それを選んでほしいというのではなく、そこの要求が満たされるようなすまいるスクールになっていただきたいと思うのですが、この点はいかがでしょうか。","respondent":"高山子ども育成課長","answer":"なかなか重い課題だとは思いますが、そうした職員の資質向上ともども、今後考えていくべき内容ではないかと考えておりますので、決してその必要性がないということを申し上げているつもりではなくて、受け入れる体制の底上げというのも一方では必要だと考えておりますので。","voiceIndex":158,"id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ総合的に。最後に、ここに、子ども・子育て会議において多くの委員から意見を求めたうえで検討するようにしてくださいとありますが、今後の制度について、ここは当然、識者の方もいろいろな方が参加をしている会議ですので、ぜひここのところは活かしていっていただきたいと思いますが、最後にお考えをお聞かせください。","respondent":"高山子ども育成課長","answer":"そうした議題として、もとより想定しているものですので、今後議題として取り上げていくことは十分考えられると考えております。","voiceIndex":160,"id":"exchange-058"},{"speaker":"渡部委員","kind":"意見","question":"友達と遊びたいから。だから、そこに関して利用しない方は、必要ないから利用しないのであって、利用される方にとって使いやすいすまいるスクールである必要が私はあると考えますから、そこはアンケートを３,０００もサンプルをとる。３,０００もという言い方は変かもしれないですけれども、３,０００は立派な数でして、そんなにとるのだなと思っていて、その中でいろいろなお話があると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":163,"id":"exchange-059"},{"speaker":"つる委員","kind":"質問・要望","question":"結論を出すで、態度は不採択です。そもそも論で、アンケートをとる統計調査の基本では、そうしたとり方が基本だということも伺いました。ただ、この陳情にあるアンケートというところを取ってみれば、先ほど冒頭に言ったとおり、既にやられるということですので、それをまた、アンケートに寄せられる声を中心に、見直すべきところは見直していただくということを、しっかりとやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":164,"id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"採択を主張したいと思います。子どもたちが、本来放課後ですから、学校が終わった後、勉強勉強と、勉強も大事ですけれども、どう楽しく遊んで、お友達と交流できるのかなど、幅広く意見が聞かれるようなアンケートにしていただきたいと思っています。どの子も大切に、成長と発達を支えていくすまいるスクールであってほしいと思う観点から、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":165,"id":"exchange-061"},{"speaker":"石田（し）委員","kind":"質問","question":"結論を出すで、不採択です。理由は、ほかの委員も言っていらっしゃることですが、アンケートは３,０００サンプルとるということなので、特段、それ以上のものが必要というのはどうなのかなと思って、ぜひその範囲内でしっかりと声を聞いていただいて、必要なものに関してはしっかり見直しも含めて、やっていかれるかと思いますので、この陳情に関しては不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-062"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ただ１つだけ、３,０００世帯ということで、１万のうちの３,０００ということですから、かなり有効なものになると思うのですが、ただ、支援が必要な方々にどのぐらい届くのかなということがあるので、そこはなかなか難しいのでしょうけれども、そういうのを抽出して、またアンケートを依頼するというのもなかなか難しい面もありますけれども、ぜひ支援を必要とされて通われている方の意見を十分に集めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4958#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":55548,"voices":173}},{"id":"h30-20181210-5","meetingId":"h30-cm12","date":"2018年12月10日","dateIso":"2018-12-10","committee":"総務委員会","time":"午前１０時００分～午後 ２時３６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を87件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"「議案審査」を行います。 初めに、(1)第８４号議案、品川区議会議員および品川区長の選挙における選挙運動の公費負担に関する条例の一部を改正する条例","agenda":"「議案審査」を行います。 初めに、(1)第８４号議案、品川区議会議員および品川区長の選挙における選挙運動の公費負担に関する条例の一部を改正する条例","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"公費負担の額は、区長選挙が７円５１銭で、１万６,０００枚、区議会議員選挙が新たに創設されて７円５１銭で４,０００枚とのことですが、この公費負担額の算定根拠を教えてください。","respondent":"秋山選挙管理委員会事務局長","answer":"７円５１銭についてですけれども、これは公職選挙法に規定をされておりますので、それを条例でも横引いています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"これは公職選挙法で定められているものなので、どうすることもできないと思うのですが、通常であれば、枚数が多ければ多いほど単価は下がるということが考えられますが、これは別に変えてくれとかではなくて、枚数が多ければ単価は下がるということを頭の中に入れておいていただきたい。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"ビラを公費負担とした理由を伺いたいと思います。それから、条例で定めるところにより無料とすることができるということは、できる規定なのかと思うのですけれども、選挙管理委員会としてどういう判断をしたのか、その理由についても伺いたいと思います。","respondent":"秋山選挙管理委員会事務局長","answer":"今回、法の改正の趣旨は、候補者の政策等を有権者が知る機会を拡充するためということで、従前、公職選挙法では、お金のかかる選挙をやめるというか、そのためにいろいろ規制がかかっていましたが、今回、候補者の政策を有権者が知る機会を拡充させるということで。","voiceIndex":8,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"理由はわかりました。具体的に説明していただきたいのですけれども、この新たに使えるビラというのは、いわゆる選挙期間中も、名前、顔写真、政策を記すことができるというものなのか、あと、選挙管理委員会に届け出たというところですけれども、これは立候補のときに届けるのでしょうか。最後に、紙のサイズにも条件があるのか。改正する条例の内容をご説明いただきたいと思います。","respondent":"秋山選挙管理委員会事務局長","answer":"使用できるビラですけれども、サイズはＡ４に決まっておりまして、内容に関しては特に基準はありませんが、頒布責任者の氏名、住所、印刷者の氏名を記載しなければならないということがあります。それから、証紙の貼付が必要になります。","voiceIndex":10,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"今の続きみたいなのですけれども、政策を知らしめるための手法がありますね。ビラの使い方について品川区として何か規制があるのかないのか、その点について教えてください。","respondent":"秋山選挙管理委員会事務局長","answer":"この条例に関しましては、公費負担の条例になりますので、区として条例で使い道を定めているものではないのですが、公職選挙法上、ビラの頒布方法は決まっておりますので、使い方はそちらに定められております。","voiceIndex":12,"id":"exchange-005"},{"speaker":"伊藤委員長","kind":"質問・要望","question":"１点だけ私から要望ですけれども、この条例が仮に可決した場合、これは全ての立候補者にかかわることだと思われるので、例えば、立候補予定者説明会とか、そういうときにはぜひ、具体的でわかりやすい説明をしていただきますようにお願いをしておきます。他にございませんか。ないようですので、以上で質疑を終了いたします。自民党・子ども未来からお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"}]},{"id":"topic-02","title":"順番を変更しまして、(6)の第８９号議案、第二戸越幹線整備工事（上流部シールド）請負契約","agenda":"順番を変更しまして、(6)の第８９号議案、第二戸越幹線整備工事（上流部シールド）請負契約","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"区立宮前坂広場に深さ３０ｍの立坑を掘ると説明がありましたが、この辺は道が狭いのだけれども、ここから残土を搬出するのではなくて、西品川公園まで持ってきて出すのか、それとも、この区立宮前坂広場公園で残土を搬出するのかということを確認します。","respondent":"持田河川下水道課長","answer":"残土に関する搬出のご質問ですが、区立宮前坂広場での工事につきましては、道は狭いのですが、この場所から残土を搬出するという形で考えてあります。","voiceIndex":27,"id":"exchange-007"},{"speaker":"いながわ委員","kind":"質問・要望","question":"狭いですし、そこは坂になっていると思うので、４ｔダンプなのか、６ｔダンプなのかわからないですけれども、もちろん大型のものは入れない。どれぐらいの残土が出るかわからないですけれども、結構なダンプの台数が出入りするのでしょうか。それと地域への説明とかはお済みになっているのか、それとも、これからなのか、教えてください。","respondent":"持田河川下水道課長","answer":"地元への説明ということでいきますと、今回こういった形で契約を締結しました後には、しっかり事業者とともに地元で工事の説明という形で、ダンプでの搬出なども含めて説明をしっかりと行っていきたいと考えています。","voiceIndex":29,"id":"exchange-008"},{"speaker":"いながわ委員","kind":"質問・要望","question":"とにかく狭い道路なので地響きとかいろいろあろうかと思いますので、可決した暁にはしっかりやっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"公園を利用されている方や、その周辺の方への説明は丁寧に行っていただきたいと思います。それで、この第二戸越幹線自体は、いつ完成するのか。今後の見通しだけご説明いただけますでしょうか。","respondent":"持田河川下水道課長","answer":"第二戸越幹線の事業につきましては、現段階では、平成３６年度の完成という形で、少し時間もかかりますが、事業を進めているところです。","voiceIndex":32,"id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"おそらく仕入れ値も人件費も違ってくるというのが当たり前だと思うのですが、入札金額がこのようにぴったり合うということは、何か不思議だなと、入札価格が漏れていて、こういうふうになったのかというような疑問を私は抱くのですが、この辺について、経理課としてはどのように考えられていますか。","respondent":"立木経理課長","answer":"予定価格は東京都等の積算価格等から適正に算出しているものなのですけれども、あとは、それぞれの共同企業体で、積算した金額と予定価格を見まして、おそらく社内で戦略的な価格づけ等を行った上で入札をしてきているものと考えております。","voiceIndex":34,"id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"こういうものに本当に疎くて申しわけないのですけれども、概要書が１２ページに出ていて、そこに工程表があるのですけれども、今、審査している議案の工事自体は、平成３１年からの債務負担行為による工事だと、それで記載されている工程表は、すごくざっくりしたものなので、平成３１年に始まっている工程はないわけですが、この工程表でいうと、どこに当たるのでしょうか。","respondent":"持田河川下水道課長","answer":"それが終わりましたら、今の予定では平成３２年度の頭からシールド工に入っていくということで、全体の事業としましては、平成３０年度から平成３３年度までとなっています。","voiceIndex":36,"id":"exchange-012"},{"speaker":"吉田委員","kind":"確認","question":"平成３０年度だけれども、もう平成３１年に実際は入っていて、この真ん中の棒の当初からの分というふうに理解してよろしいですか。それだけ確認させてください。","respondent":"立木経理課長","answer":"契約自体は、こちらの議決をいただいた後、契約をするということで、工事自体が終了するのが平成３３年ということになりますので、その分までの債務負担行為を今年度中に定めするという形のものですので、契約ができましたら平成３０年度中に始まるという形のものです。","voiceIndex":38,"id":"exchange-013"}]},{"id":"topic-03","title":"第９０号議案、第二戸越幹線整備工事（下水道本管立坑整備）請負契約の変更","agenda":"第９０号議案、第二戸越幹線整備工事（下水道本管立坑整備）請負契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどの説明ですと、変更理由はシールドマシーンの到達部を補強する必要があるということですけれども、資料に記載してある変更内容は、どういうものなのか、どういう状況があって補強する必要が生じたのか、もう少し具体的にご説明いただきたいと思います。","respondent":"持田河川下水道課長","answer":"そういった中で、今年の７月に、第一三共の土地について譲渡の時期も決まりましたので、それにあわせてこの補強タイプのセグメントに変えまして、下流部にシールドマシンが到達しても構造的に大丈夫なような形に変更した。そういった理由により変更を行う案件です。","voiceIndex":53,"id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、あそこの公園は、山になって高いですね。この深さ約４０ｍというのは、路面から４０ｍ掘るということですか。そういうことでいいのでしょうか。","respondent":"持田河川下水道課長","answer":"そのとおりでございまして、公園のところを少し掘削をして１ｍほど下げた基盤面から４０ｍ、これから掘っていくです。","voiceIndex":57,"id":"exchange-015"}]},{"id":"topic-04","title":"平成３０年請願第２０号、国に対し「消費税増税中止を求める意見書」の提出を求める請願","agenda":"平成３０年請願第２０号、国に対し「消費税増税中止を求める意見書」の提出を求める請願","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"委員長が冒頭説明されたとおりだと思います。１０％にすれば、消費不況が一層厳しくなることは明らかですので、消費税自体の是非ではなく、請願にあるとおり、来年１０月の消費税１０％は中止してほしいと、この１点で議論を通じて一致点が見出せたらと思いますので、各委員の率直なご意見をお伺いできたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"意見","question":"やはり、現在の深刻な財政難の中で、少子高齢化に伴い、増え続けている社会保障費の財源確保のため１０％にするというところです。ただ、少子高齢化に対応するための増税は、私は当然それは必要なのではないかと考えています。国も軽減税率制度、少しややこしい部分もありますけれども、そういった制度も導入していただきながら、１０％は当然必要ではないのかと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"ですから、品川・生活者ネットワークは、消費税という制度自体には必ずしも反対ではない。さきほど、中塚委員の発言でありましたけれども、消費税そのものへの反対意見ではなくて、今回の１０％引き上げへの中止を求める意見書というのは、区民のそういう声を代弁する区議会としてはあってもいいのではないかというふうに品川・生活者ネットワークは考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-018"},{"speaker":"いながわ委員","kind":"質問・要望","question":"医療費が上昇しているから何とかしなければいけないと一方で言われているわけですから、この辺はしっかりやっていただきたいという思いの中で、その財源はどこだと言ったら、やはりどこかで確保していかなければいけないことだと思っていますので、８％が１０％になるというのは、私はやむを得ない。それから、委員長、今回は理事者に何も聞いてはいけないのですか。","respondent":"伊藤委員長","answer":"そんなことはありません。例えば、現状の方向性であるとか、制度の考え方などについては、当然、聞いてくださって結構です。","voiceIndex":76,"id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問","question":"わかりました。それが国の役割だと思っています。これは、平成３１年度の予算には載っていなければいけないことだと思いますし、むしろ平成３０年度予算ですでに準備をしていかなければいけない段階なので、補正なり何なりを組んででも積極的に行う必要性があるものはやるべきだと思っているのですけれども、その辺について行政側としてはどうお考えなのでしょうか。","respondent":"品川財政課長","answer":"過去を見れば、いろいろと対策も打っているというような状況もありますけれども、現時点で具体的にどのような対策というのは、まだまだとることは難しいかというふうには考えております。","voiceIndex":78,"id":"exchange-020"},{"speaker":"いながわ委員","kind":"質問・要望","question":"たしか品川区は商店街連合会を通して、地元の商店街を通して、どうしますかなどという、そういう話はちらっとされている、動き出しているのは出しているので、さっき言ったレジのシステム系を変えると、普通の飲食店のものは３００万円ぐらいかかるという話も漏れ聞いているので、さらに言うのであれば、今度、国がこの税率を上げたときに、クレジットカードを推進すると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、今、日本の国の借金は１,０７０兆円を超えて、本当に財政再建しなければいけない時期に来ています。私は、それだけは避けるべきではないかといつも思っております。今回、タイミングが悪い消費税増税中止を求める意見というのはわかりますけれども、国の将来、次の世代のことを考えたら、消費税増税はやむを得ないというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-022"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"一方で、やはり事業主にとっては大きな負担が生じるわけですから、そこにも目を向けていかなければいけないということで、ここは理事者に確認をさせていただきたいのですけれども、既に国では２０１６年度から軽減税率の対策補助金を創設しておりまして、レジの導入とか買い替え、システム改修などへの支援をしておりますが、区の中でこういうことの周知はどこでされているのか、また今現在。","respondent":"伊東税務課長","answer":"区といいますか、これは税務署のほうで、さまざまな機会を捉えて、各種団体、税関係の団体とかに軽減税率の話ですとか、先ほどのレジの改修費用等の補助金の関係の話ですとかを行い進めているというふうに聞いております。","voiceIndex":82,"id":"exchange-023"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"消費税は大事な財源でありますし、年金、医療、介護はもとより、これから進めていく幼児教育の無償化や、また、給付型の奨学金の大事な財源にもなっていくわけでありますから、ここで消費税が上がることがとまってしまったら、財源が確保できない、いくべきところに給付がいかないという、そういう事態にもなりかねないので、公明党としては、この消費税の１０％というのは、上げた上で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"それぞれご意見ありがとうございました。消費税そのものの捉え方については、なかなか一致点を見出すというのは、今のご意見を聞く限り難しいのかなと私も思いました。単に財源が足りないイコール消費税増税では決してないだろうと考えています。ただ、皆さんのご意見を伺う中で、この厳しい経済の中で１０％にしてよいのかというところでは、さまざまな一致点はあるのではないかと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-025"},{"speaker":"須貝委員","kind":"質問・要望","question":"そんなにお金がないなら、どこかで経費を削減するとか、そういうことをやりつつ、法律をつくっている議員の皆さんも、自分たちの給与、ボーナスなどを削減した上で、国民に理解を求めるというのならわかるのですけれども、片やじゃぶじゃぶお金を使っておいて、片や赤ちゃんから寝たきりのご老人の方まで全員に負担のある消費税からとっていくというのは、私は大半の国民には理解されないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"なので、やっぱりタイミングの問題とか、もっとほかに財源はないのかというようなことも考え併せた上で、社会保障の財源確保について結論を出すべきだと思いますので、そういう意味でも、今回のこの８％から１０％への増税というのは、一地方自治体の議会として、区民生活を鑑みた場合に、中止を求める意見書というのは妥当性があるのではないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-027"},{"speaker":"中塚委員","kind":"意見","question":"本日結論を出すということと、一言述べますけれども、消費税そのものについては一致していないと思いますけれども、この不景気の中で、来年１０月に１０％に引き上げるべきではないというのは、多くの皆さんの共通する考えだと思いますので、その点をもって意見書を出したいと思います。結論としては、採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-028"},{"speaker":"いながわ委員","kind":"質問・要望","question":"本日結論を出すということで、この請願に関しては不採択でお願いします。ただ、その政府で埋めきれない部分は、ぜひ品川区も緊急経済対策をしっかり打ち出して、いろいろな所管に分かれるかと思いますが、そこはしっかりとやって区民がマイナスにならないよう、不利益を被ることがないようにフォローをしていただきたいということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-029"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、本日結論を出すということと、先ほども申し上げましたが、国の借金、また、福祉を拡大していくためには、次世代の子どもや孫たちにツケを回してはいけないということを思えば、中止するという意見書には反対をします。本当に大半の国民にとってかなりの負担になると思いますが、そこは理解していただきたいというふうに思います。今回の請願に関しては、不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"繰り返しになりますけれども、消費税そのものへの反対の意見書ということではなく、今回の消費税増税中止を求める意見書ということであれば、意見の中身はまた考える必要はあるかと思いますけれども、今の時点で区議会として意見書を出すということはありではないかというふうに思いますので、今日結論を出すということで、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-031"},{"speaker":"松澤委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-032"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そこには高齢の入居者がいらっしゃる中で、会社ががらっと変わってやり方や経営方針が変わってしまうということは危惧する部分なので、やはりしっかりと指導などを行う中で指定管理を継続していくという流れを、私の頭の中で考えているのですが、それはそういう感じなのですか。私の会派、民主党時代からずっと要望していたのですが、労務監査というのもたしか今、試行的やられていると思います。","respondent":"柏原企画調整課長","answer":"そのことによって区のセルフチェック以外で外部のチェックが入るということで、ほかの外部チェックについても今検討しているところですが、そういったものを入れながら、公平性を担保していきたいと思っているところです。","voiceIndex":104,"id":"exchange-033"},{"speaker":"いながわ委員","kind":"質問・要望","question":"しっかりそういうようなものが機能して、しっかりとした指定管理者の管理をしていただき、あと、創意工夫のある自主事業の実施を妨げると資料に書いてあるのですけれども、品川区がＡをやってくださいと、Ｂはやってはだめですよ、こういう事業はやってはだめですよと言えば、創意工夫を阻害するとか、妨げるという話なのですけれども、やはり指定管理制度全体を考えたら、独自性とか自主性、創意工夫、創造。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"指定管理者制度について、現状の何を課題と捉え、どこが課題と考えているのかをご説明いただきたいと思います。冒頭の説明で、いわゆるガイドラインに沿うという説明だったのでしょうか、指針を検討しているとの説明がありましたけれども、この指針というのは、現在は非公開だけれども、公開を行うということでよろしいのか、そこについてもご説明いただきたいと思います。","respondent":"柏原企画調整課長","answer":"課題といいますか、認識といたしましては、指定管理者制度は、平成１７年以降行ってきているところです。当時は管理委託のところから引き継ぎで指定管理に移っていったという状況であります。","voiceIndex":107,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"チェックのあり方について、外部によるチェックを含めて今検討しているということですけれども、指定管理者制度の課題の１つに、議会に議決を求める際の資料や、また区民への情報公開も課題として捉えていただいて、検討を進めていただきたいと思いますけれども、この点について、お伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"前段のほうのご質問については、今後の資料等のあり方であるとか、選定の透明性といったところを含めて、どういった形の資料のあり方がいいのか、今、検討していますので、どういった形がいいかは引き続き検討させていただければと考えています。","voiceIndex":109,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"前半の今後の課題ですけれども、情報公開については強く求めておきたいと思います。そのためにも、陳情にあるとおり制度をよく理解し、制度運用できるよう人材の育成は必要な視点だと思いますけれども、この指定管理者制度の改善に向けた制度設計や人材育成について、今後どのように行っていくのか、重なる部分もありますけれども、改めていかがでしょうか。","respondent":"柏原企画調整課長","answer":"今後の指定管理の考え方の部分ですけれども、先ほどと重なる部分はありますが、例えば、募集をかけたときに一社しか来ないような場面で、これはやはり事業の困難性であったりとか、特殊性というのはどうしてもありますので。","voiceIndex":111,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"品川区がどのレベルを求めていてというのがもう少し明瞭でないと、確かに法人としては手が挙げにくいのではないかと思いますが、その辺の今の現状、上限額も決めずに公募をして、指針も示さずに公募していて、それで自由な発想を阻害しないようにそうしているという、何かちょっとその辺が、何をどう目指しているのかがよくわからないので、その辺をもう少し詳しく手順、どういうふうな募集の仕方をして。","respondent":"柏原企画調整課長","answer":"説明会等での質問のやりとりなどがありますので、公開で質問が来たことに対しては、それをもとにしながら、その場で答える、返事を出す、いずれにしても一社だけに返すのではなくて、全てに対して、こういう質問にこう答えたということを流したりしておりますので。","voiceIndex":113,"id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"少しはわかりました。そうなると、やっぱりそちらのほうが応募しやすいというのは現実的にあるのです。もちろん安定的な事業を行うというためには、同じ法人がという面もあるかもしれませんけれども、競争原理とか、そういうことを考えると、いろいろな法人が手を挙げやすい、その中で品川区がどういうふうに選定していくかということがすごくまた品川区としての力量も求められるのではないかと思います。","respondent":"柏原企画調整課長","answer":"そういった中で、先ほどの議論にもありましたけれども、その内容や考え方などを入れながら、区の指定管理者制度をどういった形でお示しできるかというのは十分検討しながらやっていきたいと思います。","voiceIndex":115,"id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういうことについて区としてもスキルを上げていかなければいけないと思うのです。後の評価ということと、まず最初の意欲ある事業者が手を挙げやすいような制度の運用の仕方というのは、ぜひ検討していっていただきたいと思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"意見","question":"本日結論を出すということでお願いします。今回のこの陳情は、区として、今現在、やるべきことをやっておられると思いますので、不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":119,"id":"exchange-041"},{"speaker":"新妻副委員長","kind":"意見","question":"本日結論を出すでお願いいたします。ただいまご説明をいただきましたとおり、現在、しっかりやっていただいているということとともに、指針等についてもしっかりと検討されているというお話がございましたので、そのことも含めて、この陳情は不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":120,"id":"exchange-042"},{"speaker":"中塚委員","kind":"質問","question":"本日結論を出すということと、趣旨採択でお願いします。その理由は、福祉施設の継続性は大事だと思います。一方で、新しい法人の応募により、新しい風を入れて活性化させるという点もあわせて大事だと思います。その手法はさまざまありますが、陳情にある制度改善や研修などの必要性について、その趣旨は理解できますので、趣旨採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-043"},{"speaker":"いながわ委員","kind":"質問・要望","question":"本日結論を出すで、不採択です。先ほど質問したように、指定管理者制度に係る基本方針など、いろいろあろうかと思いますが、今度新たにお考えの社会保険労務士を入れた労務管理は、実現に向けてしっかりと検討していくという説明がありますので、しっかりそれは公平性の担保がなされるよう、行っていただきたいと思います。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-044"},{"speaker":"須貝委員","kind":"質問・要望","question":"陳情の趣旨は、ガイドラインの作成と人材研修の実施を求めるということですが、区として、さまざま取り組んでいる中で、こういう陳情が出たということは、区民、また事業者から見えにくいため指摘されてたと思いますので、今後とも区民や事業者にわかりやすい制度に向けて、明確なガイドライン等を作成したり、いろいろと努力して、品川区の指定管理者制度をよりよいものにしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-045"},{"speaker":"吉田委員","kind":"質問・要望","question":"本日結論を出すということと、採択を主張したいと思います。内部の指針があるということは不勉強で今日知りました。一般的には品川区指定管理者制度活用に係る基本方針しか見れないわけです。指定管理者がどういうふうな事業者かは、区民のサービスを利用する人にとってはとても重要なことだというふうに思いますので、それを区議会から区に求めるというこの陳情については採択が妥当ではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-046"},{"speaker":"吉田委員","kind":"質問","question":"確かにこの文章のとおりでなくても、例えば、指針でもいいわけですし、とりあえずはガイドラインなり指針の作成ということで、人材研修というのは、それに伴うものですから、この文章のとおりではないという意味では、趣旨採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-047"}]},{"id":"topic-05","title":"第８５号議案、（仮称）品川区立障害児者総合支援施設新築工事請負契約の変更","agenda":"第８５号議案、（仮称）品川区立障害児者総合支援施設新築工事請負契約の変更","exchanges":[{"speaker":"いながわ委員","kind":"意見","question":"それと、この（仮称）品川区立障害児者総合支援施設新築工事に関しては、地中埋設物を撤去しなければいけないため、その分、費用がかさんでしまうというのは、当初見込んではなかったので、その追加費用は全然問題ないと思うのですが、それ以外の躯体ではない（仮称）品川区立障害児者総合支援施設給排水衛生設備等に関しても、多いものだと５００万円の費用がプラスになっているのでけれども。","respondent":"小林施設整備課長、飛田障害者施策推進担当課長","answer":"１つ目につきましては、所管課の障害者福祉課のほうで利用者向けに、１１月１５日に、２回に分けて説明会を開いたということです。説明会では、利用者の方から代替施設は早めに決めてほしいという話をいただきましたので、こちらのほうでも早急に動きまして、現在、こみゅにてぃぷらざ八潮３階の講習室で話を進めているところです。","voiceIndex":137,"id":"exchange-048"},{"speaker":"いながわ委員","kind":"質問・要望","question":"よく理解できました。それでも、もしかしたらご納得されない方もいらっしゃるかもしれないですが、そこは根気よく、品川区の施策としてやっているものですので、理解を求めるよう頑張っていただきたいというと言い方はおかしいですけれども、ご努力をしていただければと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":140,"id":"exchange-049"},{"speaker":"中塚委員","kind":"質問","question":"今回の工事の延伸に伴う契約金額の変更ということですが、第４回会定例会に契約議案が提出されたわけですけれども、いつの時点で金額の変更が必要だと判断されたのか伺いたいと思います。いつの時点で４月の開設が延び、契約金額を変更するという判断に至ったのか、その状況を伺いたいと思います。","respondent":"小林施設整備課長","answer":"今回の変更理由における、近隣配慮、これは振動、騒音、いろいろな要望等、それから、地中障害物関係は、工事の前半のほうにありましたので、そこにかかった時間は当然あったのですけれども、その間、何度も建築工事業者、電気工事業者、空調工事業者。","voiceIndex":141,"id":"exchange-050"},{"speaker":"中塚委員","kind":"質問","question":"経理課か、障害者福祉課か、どちらに聞いていいのかわからないのですけれども、契約議案として上程するにあたり追加の金額が出てくる関係もあるのでいろいろ精査しなければならないでしょうが、１０月上旬に一定の判断をしたのであれば、速やかに議会や利用者の保護者に説明する必要があったのではないかと思うのですけれども、現時点で振り返ってみてどう思われるか、ご見解を伺いたいと思います。","respondent":"小林施設整備課長","answer":"今回、４カ月の延伸ということで、業者も含めて打ち合わせが済んだ後、先ほどのご質問にありましたけれども、人件費にかかわる経費とか、そういうものを出していって、今度は、そちらの経費が妥当なのかをまた精査をして、いろいろそういう準備を行い。","voiceIndex":143,"id":"exchange-051"},{"speaker":"中塚委員","kind":"質問","question":"経費などの積算もあるでしょうから、固まった時点で変更の議案を出すということはよくわかるのですけれども、４月の開設が間に合わないということ自体は、１０月上旬の判断で、利用者はもちろん、議会にも示すことができたと思うのです。その点を振り返ってみて、やはり、直接利用される方へのとりわけ丁寧な説明が必要だったのではないかと思うのですけれども、その点はいかがでしょうか。","respondent":"飛田障害者施策推進担当課長","answer":"区民の方にも、もちろん早く説明しないといけないというところで、早急にどういうふうに周知をしようかと考え、今回、１１月１日の広報しながわに説明会の開催を掲載し、１１月１５日に説明会を２回に分けて実施したところです。","voiceIndex":145,"id":"exchange-052"},{"speaker":"中塚委員","kind":"質問・要望","question":"とりわけ利用者にとっては、４月から、どこに行くのかという問題にかかわってきますので、ほかの施設とは少し性格が変わってくると思いますので、今後はしっかりと利用者への丁寧な説明を強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-053"},{"speaker":"吉田委員","kind":"確認","question":"気になるのが、本当に今、この４カ月延伸ということで、きちんとでき上がるのだろうか。今度、ここでこの契約を通すというのは、本当に責任があると思うのです。４カ月延伸の契約できちんと立ち上がるということを確認しないといけないかというふうに思っております。１０月に判断されたということですけれども、今は１２月ですから、それからまた進んでいる部分があるわけですね。それをお聞きします。","respondent":"小林施設整備課長","answer":"今現在、そういう状況で進めていて、その状況で、先ほど言った会議を何回も開いて、今後、どの程度の工期が必要で、今言った４カ月、これは業者からも言われている数字です。","voiceIndex":148,"id":"exchange-054"},{"speaker":"吉田委員","kind":"質問・要望","question":"決算特別委員会の中でも、危険負担条項というのですか、もし不測な事態が起きた場合は区が負担するという契約だということは確認しましたけれども、そのほかに、やっぱりそういう報告がきちんと、これはもう工程管理上、現時点では難しいのではないかという報告は、事業者のほうが上げるべきという条項も入っているのではないかと思うのですけれども、その辺、どうなのでしょうか。","respondent":"小林施設整備課長","answer":"徹夜だとか突貫工事で工事を進めていくには、少し危ないのかなというところも論議をしながら、定例会議で話し合いをして、１０月の上旬にいろいろと検討していったところ、いろいろやっていったのですけれども、最終的に一定の判断を下したです。","voiceIndex":150,"id":"exchange-055"},{"speaker":"吉田委員","kind":"質問","question":"だから、それをきちんと管理していく、ここまで進む予定だったけれども、今はここまでしかできていないということを、もう少し細かくやるべきだったのではないですかと、それがきちんとされていたのですかということなのです。私も本当に素人なのでわからないのですけれども、施工管理にはそういうものが入るのではないですか。だから、それがどう機能していたのでしょうかということなのです。","respondent":"小林施設整備課長","answer":"それが初めの段階でそれを取り戻せるよう打ち合わせをし、努力をしたところです。ただ、先ほども言いましたが、１０月上旬に、このままいくと事故にもつながる可能性もあるので、一定の判断、本当に苦渋の決断をし、４カ月の延長となったところです。","voiceIndex":152,"id":"exchange-056"},{"speaker":"吉田委員","kind":"意見","question":"突貫工事で何が何でも２月竣工を目指すべきではないと判断されたのも理解できるのです。だけど、それがなぜ、実際に細かくそれだけ打ち合わせをしていて、工程表だと、本来ここだけれども、今はここまでしかいっていないという現実はそこで突きつけられるわけですよね。事情はよくわかります。そして今回、これで大丈夫という判断をされたのかがよくわからないので、その辺をもう１回だけ。","respondent":"小林施設整備課長","answer":"そういう努力を業者がやっているところも我々は見ておりますので、そういうところを見て、ずっと進めていたところなのですけれども、繰り返しの答弁で申しわけございませんが、１０月の上旬に、苦渋の選択をしたです。理由はそういうものもいろいろあります。","voiceIndex":154,"id":"exchange-057"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういうことがないように、工程管理のところも、現実的なところを見据えながら、きちんとされていかないと、結果として、事業者への努力を求めながら、結局こういうふうに突然延伸ということになってしまったので、その辺は今後はそういうことがないように、ぜひ工程管理をきちんと、そのための工程管理ではないのかというのがどうしても疑問が残ってしまいますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":156,"id":"exchange-058"},{"speaker":"須貝委員","kind":"質問","question":"本体工事もおそらくこういうわけで、今、工事を止めなければいけないということは、社内でもきっと話が通っていると思うので、その中で、４カ月ぐらいなら、民間ではこういう工事費が増額するということは、私はないと思うのです。区の契約条項には、工期が延びた場合には、その分、増額しなければいけないというルールがあるのですか。その点についてお聞かせください。","respondent":"小林施設整備課長","answer":"そういうことを考えて、４カ月延びることによる人件費、あと、仮囲いだとか、積み上げの仮設だとかあるのですけれども、そういった４カ月分の経費を見込んで、今回、変更を提案したです。","voiceIndex":157,"id":"exchange-059"},{"speaker":"須貝委員","kind":"質問・要望","question":"いろいろな皆さんからご意見があったと思うのですが、トラブルなり何かあったときは、仮に延伸するなら延伸するで先に言って、そして、いや、実はこういうわけで早くなりましたと言ったほうが影響が少なかったのではないかと私は思うので、今回も事故のないように工事を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":159,"id":"exchange-060"},{"speaker":"高橋（伸）委員","kind":"確認","question":"ご説明ありがとうございました。延伸になったということで、工程表については、やはりそのとおりになかなかいかないと私は思っています。そこで１点だけ確認ですけれども、先ほど、週１回、業者との打ち合わせがあるとおっしゃられたのですが、参加しているのは、ジョイントベンチャーの現場監督、もしくは下請け、孫請けなのかどうか、お聞きしたいと思います。","respondent":"小林施設整備課長","answer":"参加する業者につきましては、建設共同企業体、建築でいくと３つの会社が共同でやっているのですが、今回はナカノフドー建設の所長、副所長、場合によっては専門の工事担当者、いろいろその中でも分かれておりますので、基本的には所長と副所長は入っています。","voiceIndex":160,"id":"exchange-061"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。１つだけ確認をさせていただきたいのですが、当初、２月２８日に工期終了で４月開園という予定になっておりました。今回は、６月２８日に工期終了で１０月開園に変更となったということなのですけれども、この間の期間が、当初は工期終了から１カ月間ですが、今回、３カ月間あいている理由は何でしょうか。","respondent":"小林施設整備課長","answer":"そちらの仕様説明をまずその後にします。それと、その設備の使い方の練習をしたいという要望も上がってきましたので、今回そういうものも見て、３カ月後の１０月という形をとらせていただいたところです。","voiceIndex":163,"id":"exchange-062"},{"speaker":"新妻副委員長","kind":"質問","question":"当初は１カ月しかなかったということはそういうことをしないということですか。","respondent":"小林施設整備課長","answer":"その後の２カ月については、そういう機器の説明、それと慣らし、もう１カ月については、向こうの運営事業者の職員が１０月にオープンに向けてのレッスンというか、研修というか、そういう形になってきましたので、本来は２月のところの中でおさめようと思っていたのですけれども。","voiceIndex":165,"id":"exchange-063"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。とにかく利用者の方が一番心配されているところかと思いますので、これ以上の工期の延びがないということは担保されていることとは思いますけれども、またそこも確認をしていただきながら進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"必要な工事ですので賛成いたしますが、一言、まず利用者への丁寧な説明はしていただきたいということと、もちろん今回も工期をしっかり守っていただきたいと思いますが、やはり工事は安全が第一ですので、そこも強調した上で賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":171,"id":"exchange-065"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、その辺の区としての責任はとても重いものですし、こういう工期の契約を議会として議決をするというのも議会としての責任もとても重いわけですから、今回、賛成いたしますけれども、その辺は区として工程管理を含めてきちんとしていただきたいということを、あえて要望としてつけ加えさせていただいて、賛成といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":174,"id":"exchange-066"},{"speaker":"中塚委員","kind":"質問・要望","question":"工事を管理する施設整備課の出席を求める内容の陳情ですけれども、さまざまな疑問や質問に答えるためには、事業の日程が変更される理由とあわせて、工事内容についてもさまざま質問に答えるために、施設整備課であったり、必要な職員の出席は必要だったのではないかと思うのですけれども、その点、いかがでしょうか。","respondent":"小林施設整備課長","answer":"事前に障害者福祉課と打ち合わせを何回も設けているのですけれども、その際に情報共有を図って、所管でも内容的なものは把握しておりますので、あくまでも今回のところについては、施設を利用する方への説明会ということでありましたので。","voiceIndex":209,"id":"exchange-067"},{"speaker":"中塚委員","kind":"質問","question":"そういう意味では、今回の障害児者総合支援施設に限らず、さまざま工事の説明をすることがあると思いますけれども、事業を進める担当課と、あわせて工事に責任を負う所管が出席をするというのは必要な対応ではないかと思うのですけれども、いかがかということと、今後、この陳情にあるように、説明会を開催すべきと思いますけれども、いかがでしょうか。","respondent":"飛田障害者施策推進担当課長","answer":"ですので、今、骨組みのところはでき上がったところという説明をしました。本当に１０月には開設できるのかというところで、そちらには１０月開設を目指して今頑張っているところですという説明をしております。","voiceIndex":211,"id":"exchange-068"},{"speaker":"吉田委員","kind":"質問・要望","question":"その辺の見解を教えていただきたいと思いますが、いかがでしょうか。","respondent":"飛田障害者施策推進担当課長","answer":"実際に質問票を出された方としては、たしか１５名程度いたのですけれども、そういうところでまた丁寧に対応していきたいと考えております。","voiceIndex":213,"id":"exchange-069"},{"speaker":"吉田委員","kind":"質問","question":"施設整備課が参加する説明会は行われないということなのでしょうか。その辺をお願いします。","respondent":"飛田障害者施策推進担当課長","answer":"どちらかというと、やっぱりこの施設の運営面について皆さんから聞きたいというお声をいっぱいいただいているので、そちらのほうに時間をかけたいと考えております。今のところは、施設整備課からの説明は時間の関係でもできないかと考えております。","voiceIndex":215,"id":"exchange-070"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。今後のこともありますし、確かにこういう視点の説明も必要だということを、私もこの陳情を見て気がついたというようなところもありますし、ぜひそれは検討の方向で考えていただきたいと思います。工事という以上、どうしても遅れとかそういうこともありますし、それは妥当な理由であれば皆さん納得するわけです。もし何か施設整備課のほうで見解があればお伺いいたします。","respondent":"小林施設整備課長","answer":"先ほども所管のほうでお話ししましたけれども、今回の説明が利用者のための説明ということと、なおかつ、１時間以上、質疑応答を行ったということと、さらに、その場で質問ができなかった方、しづらかった方につきましては、質問票ということで丁寧な対応を行っているところです。","voiceIndex":217,"id":"exchange-071"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのときに、工事の専門的な説明がその場ですぐきちんとできるという人が同席する説明会について、ぜひ今後検討していただきたいと思います。これは要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":219,"id":"exchange-072"},{"speaker":"いながわ委員","kind":"質問・要望","question":"先ほど質問したのですけれども、確認したいのですけれども、例えば、騒音に伴う近隣配慮とこの陳情に書いてある1)と、車両出入口の縮小の2)、これは要するに、近隣への配慮なわけですね。だって、工事をしながら説明しているというのはおかしな話ですから、このニュアンスからいくと。そうなってくると、また延伸する可能性も出てくるという考えも１つあるという認識でいいのでしょうか。","respondent":"小林施設整備課長","answer":"やはり、二手から工事をやるところ、１つのところからやり始めたものですから、施工の方法だとか手順だとか、全て見直しを行い、先ほどの打ち合わせを何回も繰り返して、工法から手順から全てを変えて１つのところからやって。","voiceIndex":220,"id":"exchange-073"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。今もさまざまありましたけれども、利用者の方がまず第一ですけれども、近隣の方々への配慮というのも大事かと思います。１１月１５日の説明会は、大きくは利用者の方のためのものであったというふうに認識をしているのですけれども、工事期間が延びるわけですので、近隣の方々への配慮ということでご説明は今後どのようにされていくのかというところを１点だけ確認をさせてください。","respondent":"小林施設整備課長","answer":"今回、第８５議案から第８８号議案を提案し、議決いただきましたので、その後、契約という形で変更契約を結びます。変更契約後に速やかに近隣を回って、これは１軒１軒訪問して、個別対応による説明をしていこうという考えを持っています。","voiceIndex":222,"id":"exchange-074"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。その中で、例えば地元町会、または団体なりからまとまった形での説明会の実施についても、ご要望が出るようであれば、それはまたしっかりおこたえいただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":224,"id":"exchange-075"},{"speaker":"新妻副委員長","kind":"確認","question":"本日結論を出すでお願いします。結論としては不採択です。丁寧な説明をしていただいているということも確認できましたけれども、また今後も引き続き丁寧な説明をお願いして、不採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":227,"id":"exchange-076"},{"speaker":"中塚委員","kind":"意見","question":"本日結論を出すということと、採択でお願いいたします。理由といたしましては、とりわけ説明会のあり方ですけれども、今回のご担当となる障害者福祉課の説明はもちろんのこと、やはり工事、その方法、スケジュールについても質疑があることは十分考えられますので、両方の出席が必要だと思います。よって、陳情の要旨や理由等に賛同しますので、採択ということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":228,"id":"exchange-077"},{"speaker":"いながわ委員","kind":"意見","question":"結論を出すということで、不採択。理由は、先ほど言った説明をするというのは当然やるべきことなので、それがどうこうというよりは、むしろ１日も早く、安全にスムーズに竣工していただくことを祈っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":229,"id":"exchange-078"},{"speaker":"須貝委員","kind":"質問・要望","question":"本日結論を出すということと、今回このような陳情が出ていますが、本当に珍しいケースだと思います。今後、区民の信頼を損なうことがないように努めていただきたいと思います。この件に関しては、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":230,"id":"exchange-079"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほどのいながわ委員からご質問がありましたけれども、やっぱり今後の工事の適切な工程管理を区に求めるというのも陳情内容に入っております。ぜひその辺、工事管理の所管課主催、所管課主催と限らなくてもいいという気もしますが、所管課が入った説明会の実施と、適切な工程管理ということは、ぜひ区に求めていきたいと思いますので、この陳情については採択をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":231,"id":"exchange-080"},{"speaker":"松澤委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":232,"id":"exchange-081"}]},{"id":"topic-06","title":"「」を聴取いたします。 初めに、(1)専決処分の報告","agenda":"「」を聴取いたします。 初めに、(1)専決処分の報告","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ、損害賠償額の算定といいますか、決め方について伺いたいのですけれども、車の場合は、保険の中でいろいろ金額が決まっていくのかと思うのですけれども、今回のような、ブロック塀とエアコンの室外機等の場合は、修理費と書いてありますが、実際は新しく設置するための撤去費や設置費等なのか、この損害賠償額の決定の経過についてご説明いただきたいと思います。","respondent":"島袋人権啓発課長","answer":"こちらは、区の契約しております保険会社との内容に基づきまして確定させていただいたものでございまして、修理費とありますが、撤去費、新たな工事費など全てのものを含んです。","voiceIndex":238,"id":"exchange-082"},{"speaker":"須貝委員","kind":"質問・要望","question":"前回も申し上げたのですけれども、皆さん、忙しいのだから、車に安全装置をつけて、バックして物に当たりそうだったらとまる。人にぶつかりそうになったら、そのときもとまる。やっぱりそういうふうに安全にお金をかけて、もし区民に万が一のことがあったら、ご本人も、ぶつけたほうも大変です。だから、そういう工夫をやっていく時期に来たのではないかと思いますので、要望だけいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":240,"id":"exchange-083"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そもそも前にも言いましたけれども、保険を使うということは保険料が上がるということですから、それは人権啓発課の所有の車だけが上がるのか、それとも品川区の庁有車、リース以外の品川区が保有している車全部の保険が上がるのか。そういう部分も含めて、今後やっぱり全体的に考えていかなければいけないと思うのですが、車のリースをどうこうではなくて、保険に関してはわかる範囲で教えていただきたい。","respondent":"立木経理課長","answer":"リースか購入かという部分に関しましては、どういったものが一番いいのかというのは、いろいろ研究している最中でございまして、現在、区長車、議長車、それから新たに入りました電気自動車はリースで行っておりますが、耐用年数や金額などの兼ね合いの中で、その都度その都度。","voiceIndex":241,"id":"exchange-084"},{"speaker":"いながわ委員","kind":"意見","question":"今後、事故を起こしたら、例えば掛け金が１００万円上がります。でも、それは１回起こそうが、２回起こそうが１００万円増えて終わりなのか、それともどんどん上がっていくのか、その仕組みがわからないのですが、検討していただければと思います。事故を起こした方も、何カ月か運転をしてはだめですという話なのか、それとも１回、教習所に行ってもらうのか、いろいろ考え方もあると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":243,"id":"exchange-085"}]},{"id":"topic-07","title":"「その他」を行います。 まず、今定例会の一般質問に係る所管質問でありますが、今定例会の一般質問中、総務委員会にかかわる項目","agenda":"「その他」を行います。 まず、今定例会の一般質問に係る所管質問でありますが、今定例会の一般質問中、総務委員会にかかわる項目","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"質問の項目を正確に覚えていないのですけれども、本日の陳情の審査にもかかわるところなのですが、本多議員の指定管理のご質問で、モニタリングに関する部分だったと思います。その試行というのが具体的に、今、どのように行われていて、現段階の検討段階がどの辺まで来ているのかとかなどについてもう少し詳しいご説明があればしていただきたいという質問です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":250,"id":"exchange-086"},{"speaker":"吉田委員","kind":"質問・要望","question":"そうです。検討の中にそれが入っているのだと思うのですけれども、客観性を担保するため社会保険労務士と公認会計士へのモニタリングの委託の検討が試行的に進んでいるということだったのですが、その検討段階、どういうふうに検討されているのかということと、現在どの辺まで検討が進んでいるのか。できることなら、いつぐらいから本格実施になるのかとかまでわかれば教えていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":252,"id":"exchange-087"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2124#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":58979,"voices":255}},{"id":"h30-20181211-6","meetingId":"h30-cm12","date":"2018年12月11日","dateIso":"2018-12-11","committee":"区民委員会","time":"午前１０時００分～午後 ２時０９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"渡辺委員","kind":"質問・要望","question":"だから、それを大前提に行政も事業計画の中に社会実験であるとか、チャレンジというのは冒頭で打ち出すべきぐらいなものとまず考えますが、その辺のお考え。それと、そうやっていく中で第一歩が踏み出せれば、２回目あるいは２年目・３年目に改善していくのが世の習いだと思うのです。最初からパーフェクトを求める事業はおそらく民間も含めて易しいことではないと思うのです。その辺のお考えを２つ目に質問。","respondent":"立川文化観光課長","answer":"行政の立ち位置ですけれども、一番行政が重要だなというのは、さまざまな主体を結びつける役割、そこは信頼していただけていると自負しておりますので、行政としましてはさまざまな団体が、団体同士ではなかなか交流が進まないところを、それをまずくっつける場を設けるとか。","voiceIndex":7,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問・要望","question":"品川区も広いですから、多くのイベントやっています、近隣に同じ人がかぶればノウハウは共有できるのですが、もっと全区的にノウハウだとかおもしろみのある企画をほかで生かすのが、多分、行政が役割として求められている、「つなぐ役割」、情報センターであり総合マネジメントの部分だと思うのですが、行政マンだけがやれるかと言うと、多分物理的にとか人手的にも難しいと思うので。","respondent":"立川文化観光課長","answer":"定評のある方は全国各地の自治体のアドバイスをしていますので、観光や文化芸術・スポーツといった分野でも施策についてご意見、またまち場のいろいろな課題を解決するためにご意見をいただけるような仕組みを今後検討・研究していく必要があるのかなと考えております。","voiceIndex":9,"id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"でも、受け手からしたら、１位は何だろうとか上位の方に関心が行くではないですか。それはときによってテーマによって違っていいと思いますし。容姿に限らず、例えば笑顔が素敵だとか、好感度、今は動画の時代ですから、「ようこそ品川へ」というテーマで３０秒コメントしてくださいとか、何か感じいいねとか、そういうのを総合的に判断する「ミス品川」でもいいし、「何とか品川」でもいいのです。","respondent":"立川文化観光課長","answer":"ただ、遊び心は、タイトルとかそういったもので強調できると思いますので、事業によってはその辺を発信力として活用してやっていくというのは、大変貴重なご意見だと考えています。","voiceIndex":11,"id":"exchange-003"},{"speaker":"渡辺委員","kind":"質問","question":"やり方はほかにもあるのですけれども、伝わるかどうか。正しいことを言っていても難しすぎて伝わらなかったら意味がないし、人と人なので、伝わり方の手段としてやっていったらどうかと思います。それも１つかなと思います。前も伺ったことあるのですが、品川区が何かしらでもっと上位に行ってほしいなと。これは多分オール品川で気持ちが１つになれると思うのです。それを最後に教えてください。","respondent":"立川文化観光課長","answer":"一方で、その辺は港区や中央区、渋谷区、新宿区、実際何もしなくても人が集まるような地域と品川区が張り合うようなことはしたくないと考えております。","voiceIndex":13,"id":"exchange-004"},{"speaker":"渡辺委員","kind":"意見","question":"今まさにご答弁いただいたことに魅力を感じます。大田区に対しての敬意があって、ライバルという。今聞いた中でも具体的な工場めぐりだとか、視察と同じ趣旨ですよね。そう言い合える課長同士の連携で、やはり連携ができているからこそライバルと言えたり、そういうのを意識されるってとても大事なことだと改めて思いましたので、またそういう情報があったらぜひお知らせいただけるといいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"この一覧表があるから私もわかったのですけれども。しかも、これ見ていると、平成二十四、五年ごろから平成２８年ごろにかけて各区ともいろいろな計画を出されている。全然勉強できていないですから、素朴な疑問として思ってしまったのですけれども、そこら辺を解説いただければありがたいなと。","respondent":"立川文化観光課長","answer":"区ではショートトリップと言っていますが、その辺も、いわゆる従来型の観光ではなくて日常生活の中にそういった観光を意識していこうといったことが平成２０年前後から各区で広がってきたと捉えています。","voiceIndex":17,"id":"exchange-006"},{"speaker":"おくの委員","kind":"質問・要望","question":"そういう住民の要望なり、あるいは口に出して言う要望ではなくても、何となくそういう雰囲気が平成２０年ごろからできていったという、実態としてあったということですかね。","respondent":"立川文化観光課長","answer":"一覧表にお示ししました、いわゆる各区の観光関係のビジョンやプランの作成年度、改訂して新しい年度のところもありますけれども、ざっと見ますと平成２０年ごろから始まっていますので、そういったまち場のご意見であるとか、議会からの要望だとか。","voiceIndex":19,"id":"exchange-007"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、外から人を呼び込む観光というよりは、住んでいる人に楽しんでもらう、気持ちよくなってもらうというか、そういう趣旨の観光ということですか。","respondent":"立川文化観光課長","answer":"ここ数年外国人旅行者が増えておりますので、そういった方々にもまち場に出たときにまちの資源、日常生活などに触れてもらうことで楽しんでもらう、そういったところで都市型観光は展開されております。","voiceIndex":21,"id":"exchange-008"},{"speaker":"おくの委員","kind":"意見","question":"例えば、品川区としては、今のご説明では、日常的なものが、住民のためのものもあるし、それから、外から来る方のため、両方兼ねているのだというお話ですけれども、品川区としては目標というか、平成２８年策定の都市型観光プランの目標としては、これだけ外側から呼び込みたいとか、持たれているわけですよね。","respondent":"立川文化観光課長","answer":"平成２８年に都市型観光プランをつくりまして、観光のコンセプト・目標についてもう一度ご説明いたします。それまでも観光に関するプランはありまして、平成２８年に改訂をしています。","voiceIndex":23,"id":"exchange-009"},{"speaker":"おくの委員","kind":"質問","question":"平成２８年からまだ２年ですが、効果はこれぐらい上がったとか、こういう流れになってきたよとかいうのはあるのでしょうか、ないならないで仕方がないなと思うのですが、まだ２年たっていないわけですから。","respondent":"立川文化観光課長","answer":"外国人観光客、シニア世代、こういった方々が具体的なターゲット、マーケットの考え方です。実際に商店街などで聞きますと、やはり日本の商店街自体が物珍しいということで訪れていただける方は増えています。","voiceIndex":25,"id":"exchange-010"},{"speaker":"大倉委員","kind":"質問","question":"回遊性を上げていくために、例えば、大井競馬場のイルミネーション、入場料１,８００円は少し高いというお話もあったと思うのですけれども、例えば、そこで終わりではなくて、水族館から大井競馬場に行くとか、大井競馬場終わった後に商店街に行くと楽しめるみたいな、割引とか連携とか、そういうのがうまくできないかなと非常に感じたのですが、そういうようなうまく回遊していく。","respondent":"立川文化観光課長","answer":"そのつなぎ役として行政としてできることがあると思いますので、その辺については検討していきます。","voiceIndex":28,"id":"exchange-011"},{"speaker":"大倉委員","kind":"意見","question":"そのためにも、やはり先ほど言った分析とか調査とか、チャレンジしていくところでもしっかりとそのチャレンジがどうだったかということも精査しながら進めていくといいと思うので、ぜひよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"そもそも論をお伺いするのですが、この資料を今回つくったと思うのですけれども、１番が千代田区、２番が中央区、３番が港区となっていますけれども、この順番の根拠は何ですか。","respondent":"立川文化観光課長","answer":"こちらは行政順ですので、いわゆる市区町村の整理上の順番です。品川区は９番ということで昔から決まっていて、背番号みたいなものです。","voiceIndex":31,"id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"それで、続けてお伺いしますけれども、例えば、個人的な考えでいいのですけれども、いわゆるこの品川区の文化観光課長として答えていただくと、必ず品川区のことが出てしまうと思うのですけれども、今日この都市型観光でほかの区が出ているのであえてお伺いしますが、例えば、課長のご出身はどこだかわからないですけれども、友人なりご親戚の方なりが地方から来たときに、東京観光をしたいと言ったときに。","respondent":"立川文化観光課長","answer":"常々意識しております。区内でお話ししますと、区内においては、八潮にある新幹線の基地です。それから、広町の山手線の基地、区外におきましては、近いところで東京タワーのふもとに行って見上げてもらいます。お金を払って上までは行かないと。","voiceIndex":33,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問・要望","question":"話を戻しますが、と言いつつ、歴史館の特別展等においても過去やっていたら申しわけないのですけれども、伊藤初代総理大臣のことはあまりやられていないような、今回も明治維新という形で特別展をやられていたけれども、そんなに伊藤さんについてはあまりやっていないと思うのですけれども、大井の人間としてはこれからまた都市型観光の１つとして盛り上げていっていただきたいのですけれども。","respondent":"立川文化観光課長","answer":"過去に取り上げたかどうかはいま確認できないのですけれども、全国的に有名な方ですので、歴史館等と連携して、どういうふうに伊藤博文公を品川の観光資源としてアピールできるかは研究していく必要があると思います。","voiceIndex":35,"id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"今年のいつだかにも伺っているのですが、都市型観光に力を入れている区を幾つか以前教えていただいたと思うのですけれども、それをまた教えてください。","respondent":"立川文化観光課長","answer":"そのとおりの答えができないかもしれないのですけれども、近隣では、港区、大田区、その辺は間違いないです。","voiceIndex":39,"id":"exchange-016"},{"speaker":"田中委員","kind":"意見","question":"でも、先ほどあったように、品川区としては、まず住民に地域を楽しんでもらうためにというお話をされていたと思うのですけれども、どちらなのかを聞きたいです。","respondent":"立川文化観光課長","answer":"都市型観光の考え方としましては、その挨拶文にあるとおり、来街者の方に満足していただきたいということがあるのですけれども、ターゲットとしましては、先ほどお話ししたとおり、区民、区内在勤・在学者、または近隣区民、沿線市民。","voiceIndex":41,"id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどあったように、新幹線の基地だったり、中央公園なども電車が通る公園だということで子どもたちにも大人気です。そういうものもあるので、イベントだけを盛り上げていくとかではなくて、ここにも書かれているように、生活文化に根ざした資源という、今ある資源を活用してほしいというのを強く要望したいです。何かあったら一言いただければと思います。","respondent":"立川文化観光課長","answer":"ただいまご指摘のありました、いわゆる生活文化、身近な資源、こちらは大変大切だと。同時に新たな観光資源として区の目玉になるようなものも必要かなと、総合的に施策については推進していきたいと考えております。","voiceIndex":43,"id":"exchange-018"},{"speaker":"本多委員長","kind":"質問","question":"私から１点だけ質問させてください。もしないならこれから働きかけしていくのか、その辺だけ簡潔に教えてください。","respondent":"安藤文化スポーツ振興部長","answer":"今の大森貝塚、大井貝塚という名称自体について、今実際に動きがあるかと言うと、特にありません。","voiceIndex":45,"id":"exchange-019"},{"speaker":"藤原委員","kind":"質問・要望","question":"大井という地名は井戸から来ているということで載っていて、違うかもしれないですけれども、逆に大森という地名は、どこから、どういう語源というか来ているのか、わかれば。何で大森貝塚なのという思いがあって。改めて品川区が元祖でいいのですよね。それももっと強く言っていただきたいのと。何で大森という名前がついてしまっているのというのも、まさに委員長と一緒の考えなので。","respondent":"安藤文化スポーツ振興部長","answer":"藤原委員のご質問の中でも、貝墟と貝塚の話ですけれども、かつてお答えしましたとおり、品川区の大森貝塚が正解ではないですけれども、正しい場所です。大森の由来については知識がありませんので、今ここで答えることは難しいです。","voiceIndex":48,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2828#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":17956,"voices":57}},{"id":"h30-20181211-7","meetingId":"h30-cm12","date":"2018年12月11日","dateIso":"2018-12-11","committee":"厚生委員会","time":"午前１０時００分～午後 ２時１０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)「第３期品川区地域福祉計画（素案）」およびパブリックコメントの実施","agenda":"はじめに、(1)「第３期品川区地域福祉計画（素案）」およびパブリックコメントの実施","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ご丁寧な説明ありがとうあります。パブリックコメントの実施についてというところで、地区懇談会をされています。それから、策定委員会が３回行われてきましたけれども、ここで出された意見というのもこの中に紹介もされているところですけれども、これは議事録などは公開されているのでしょうか。そこの点についても教えていただきたいと思います。","respondent":"大串福祉計画課長","answer":"ほとんどの地区が支え愛活動会議にお邪魔をして、ご説明または意見交換をさせていただいたところ、その支え愛活動会議につきましては、それを構成するメンバー各地区でそれぞれです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ありがとうございました。パブリックコメントをただ閲覧して区民の皆さんが意見を言うというのはなかなか難しい部分があるのではないかというふうに思いますので、一般区民、活動に参加している方だけではなく、一般区民に対しての説明会、これを説明していただく機会をぜひつくっていただきたいと思うのですけれども、その点について１つ。","respondent":"大串福祉計画課長","answer":"２点ご質問をいただきました。住民への説明といったところですが、前期だけでも１４回、また、これからもずっと各地区を回らせていただきます。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これからもずっと地域センターごとに懇談会をされるということなのですけれども、その懇談会のところに一般区民もどうぞ参加してくださいという形で、関心のある方は参加をして意見も言えるような、そういう場面をぜひつくっていただきたいと思うのですけれども、この市町村地域福祉計画策定ガイドラインというところにも、やはり策定上の留意事項というところでは、住民参画によって策定される計画と。","respondent":"大串福祉計画課長","answer":"したがって、そこのところに一般区民をといったものは、その支え愛活動会議、あるいは町会長会議のほうでのご判断になってくるところかと思いますし、また、そうした中でお話をするですので、一般の区民の方が入るのは少し難しいというふうに思っております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だけれども、さまざまないろいろ思いは持っていらっしゃると思うのです。そういうところの声も広く聞くという、こういう計画ができるときというのは一番の機会なので、ぜひ説明会を行っていただきたいと強く要望しておきたいと思います。","respondent":"大串福祉計画課長","answer":"基本的には、この第３期地域福祉計画につきましても、メンバー構成については今現在検討中ですけれども、各会の方、皆様お集まりいただいて、特に重点施策に位置づけているものについての事業の進捗状況をご確認いただき、ご意見をいただきながら。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もし、その推進委員会のメンバーなども、ここに書けるのであれば知らせていただきたいということと、それから、１年間に１回ということなのですけれども、そうしますと、品川区がおおよそのところをまとめて、推進委員会にかけて、ご意見をいただいて、そのご意見をもとにしてまた１年間のまとめをつくるような、そのようなイメージになるのでしょうか。","respondent":"大串福祉計画課長","answer":"この計画は本当に多くの部・課にかかわってくるものですので、そちらと調整しながら、おっしゃるように、我々のほうで一定程度資料をつくらせていただいて、それを委員会にかけさせていただいて、我々のほうからの説明、またご意見。","voiceIndex":13,"id":"exchange-005"},{"speaker":"こんの委員","kind":"質問・要望","question":"人と人とのつながりという、その共生社会の中で生まれてくるものというのは、想像できるようで想像できないと言うか、でも、想像しながら、こういった理想に向かっていくという活動であったり、私がそこでいつも思うのは、人と人とのつながりだからこそ、その困っていらっしゃる方にかかわっていこうとする人がかかわりやすい環境をつくっていただきたいなと。そうした考えはいかがでしょうか。","respondent":"大串福祉計画課長","answer":"そうしたところでのちょっとした気づかいであったり、そういったものからまずは始めてみてはどうだろうといったところで、この計画では最初のところを提案させていただいていると、最終的には包括的な相談支援といったところで、行政であったり。","voiceIndex":18,"id":"exchange-006"},{"speaker":"若林委員","kind":"質問・要望","question":"章は普通、基本目標とか理念とか定義というのは別の章にして、経緯というのは別ではないですか。その辺を丁寧にしていただきたいというのが１つです。いきなり４０ページ、４１ページを見たときに、その体系図との位置関係がどうなっているか、この施策の１）は、この図で見ると、ああ、ここに位置しているのだなというのが、最近の計画はそういうふうにつくっているものではないですか。","respondent":"大串福祉計画課長","answer":"体系図との関係です。どういう形で入れられるか検討はしてみたいと思います。一定、色分け等はさせていただいているところですが、もう少しわかりやすくといったところで、検討させていただければと思います。ありがとうございました。","voiceIndex":21,"id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"品川の地域包括支援センターは、３職種配置されていないので、ほかのところは結構地域包括のところで、地域の課題を全部洗い出して、体系立てて、それをどう地域づくりに生かしていくかというふうなところを地域包括が中心になって行っていると聞いているのですけれども、その辺のところは、品川区の場合は、それが支え愛・ほっとステーションになるのか。","respondent":"大串福祉計画課長","answer":"したがいまして、各課の個別計画、各部の個別計画で取り組んでいる事業につきましては、あくまでも個別の計画の中に委ねるといったスタンス、あくまでもそうした中で一定程度網羅的に行われるような事業。","voiceIndex":24,"id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"本来であれば、やはり厚労省が求めている地域包括ケアシステムの拠点は地域包括支援センターがなるべきだと言っているので、そこのところが支え愛・ほっとステーションがそういう形になり得るのだろうかという思いが、私はするのですけれども、その辺についていかがでしょうか。","respondent":"大串福祉計画課長","answer":"そうした中では、高齢者においての在支、高齢者に特化した形での専門機関、こういったところの連携も図りながら地域での課題の抽出、または解決に向けた考えといったものをコーディネートしていくことも求められているということで、こちらにも一定。","voiceIndex":26,"id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"そこで、医療も権利擁護も、それから総合相談もという、そういう位置づけにされていて、それが地域包括ケアシステムの中心で進めるということになると思うのですけれども、そこのところが３職種配置されていないままコーディネートだけのところを品川区が行っていくというシステムだと、無理があるのではないかという思いがするのですけれども。","respondent":"大串福祉計画課長","answer":"我々品川区においては、これまでも２０在支をつくって、そうした中で地域の高齢者の関係については従前にならって、また、各地区１３に分かれての地域センターの役割であるとか、そこに改めて支え愛・ほっとステーションを配置したといったところでは。","voiceIndex":28,"id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"最後に要望だけ。私はやはり改めて、その３職種配置の地域包括支援センターはどうしてもしっかりとつくっていただきたいという要望をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-011"},{"speaker":"石田（秀）委員長","kind":"質問","question":"私から１、２点お伺いします。各町会、いろいろ四苦八苦しているではないですか。確かに、３世代同居しているところは、例えば孫に当たる子どもたちは結構おじいちゃん・おばあちゃんが、小さいころからそういうふうに一緒にいると、認知症になったりしても、それはそれで対応も結構違うというのが、もう現実にあるではないですか。それは違うでしょうというのを、地域でずっと言っているわけではないですか。","respondent":"大串福祉計画課長","answer":"我々としてはそうした動きをよく捉えて、この計画の中でご紹介しながら、地域の皆さんと今後、地域福祉の向上推進、あるいは共生社会の実現を進めていきたいと考えているところです。いただいたご意見については検討します。","voiceIndex":31,"id":"exchange-012"}]},{"id":"topic-02","title":"国民年金第１号被保険者の産前産後期間の保険料免除","agenda":"国民年金第１号被保険者の産前産後期間の保険料免除","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"そういうところからすると、抜けないやり方、例えば出生届は必ず出すので、そのときにこれをまたもう１回、リーフレットを渡すとか、その方が国民年金か、厚生年金かというのはわからないので、もしも国民年金だったらというようなことになるのかもしれないのですけれども、そういうふうな形で、国民年金なのに申請を忘れないチェックであったりとか、その辺の周知の仕方は。","respondent":"三ツ橋国保医療年金課長","answer":"非常に、周知の仕方は広く周知したいと思っているところですが、この出生届の部分は非常に難しい問題がございまして、そのあたりもよく勘案しながら、できる限り広く周知をしてまいりたいと考えています。","voiceIndex":37,"id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"せっかくこういう形で４カ月間の国民年金が免除されて、それも払ったという形で年金が受け取れるという制度ができたのに、申請しなかったためにそれが適用されないということがないような形での取り組みをぜひ工夫していただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-014"}]},{"id":"topic-03","title":"産後ケア日帰り型事業の拡充","agenda":"産後ケア日帰り型事業の拡充","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"現状ありがとうございました。１１時から３時の間で、この客室でしていただくケアの内容について、もう少し具体的にご説明いただきたいのですけれども、いわゆる４カ月未満までのお母さんなので、その期間、自分のお子さんを連れてきて、一緒に、あるいは預けてご自分だけという場合もあるのでしょうかね。","respondent":"榎本荏原保健センター所長","answer":"満足度という形でアンケートをとっているのですけれども、話を聞いてもらえたかというのは、もらえたと、できたという方が９７％で、ややできたという方が３％ということで、ほぼ１００％で、５項目ぐらい聞いているのですけれども、できなかったという回答は。","voiceIndex":47,"id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"拡充ということで進めていっていただきたいのですけれども、訪問型、宿泊型もあるし、それで検討していってもらいたいのですけれども、前に質疑を行ったとき、今回も東京医療保健大学ということで、そのときに助産師会という話が出たのではないかと思ったのですけれども、助産師会との連携というのはどうなっているのかというところをお聞きしたいのと、今回、これで完全に運営委託になるということで。","respondent":"榎本荏原保健センター所長","answer":"助産師会との関係ですが、１つはこの日帰り型の産後ケア事業は助産師会とよりかかわって、つくり上げるのに１年近く、東京医療保健大学と助産師会と区と３者でずっと話し合いを進めて、こういった形でつくって、ケアの内容も含めてつくり上げてきたというのが１つあります。","voiceIndex":52,"id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。私が聞き違えていたのかと思ったので、何かあまり連携がとれていなかったようにとっていたので、その辺は続けて連携をとってください。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-017"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"この中で課題はやはり相談員の体制だと思うのですけれども、区として課題はどういうふうに捉えているのか、それから、相談員に対する研修体制とか、その辺まで考えているのかどうか、その辺はどうでしょうか。","respondent":"松山障害者福祉課長","answer":"もう１つは、研修についてですけれども、こちらにも拠点相談支援センターからのご意見というのがありますけれども、初任者研修のみではなかなか難しいのではないか、また在支のほうからもさまざまな障害がある中でやはり勉強していかなければならないということで。","voiceIndex":63,"id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問","question":"区としていつごろから実施を考えているのかというのと、それから、障害児者総合支援施設、今度できるところに区の分室をつくるということで、こういうところもいろいろな研修の場に使えるのではないかと思うのですけれども、この辺はどういうふうに考えているのでしょうか。","respondent":"松山障害者福祉課長","answer":"実施予定ですけれども、恐らく来年、まだ３月までに最終報告ということで、地域自立支援協議会に報告をさせていただいてからということになりますので、来年度につきましては年度途中ということで、４月からの実施は難しいというふうに考えております。","voiceIndex":65,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"意見","question":"もう１点だけ。皆さん積極的にやるという考え方もあるのでしょうけれども、その中で具体的に、負担面、費用負担なども出てくると思うのですよね。当然、研修に出せばその分の負担が出てきますが、その辺は区としてはノータッチと言うか、フォローを考えなくていいのかというのが１点気になっているところです。","respondent":"松山障害者福祉課長","answer":"今すぐに何か具体策というのはまだ考えておりませんけれども、また意見交換の場を、今回ヒアリング調査をして終わりということではなく、またフィードバックしたり、いろいろな場面で意見交換もする中で、皆様方から意見を頂戴しながら考えていこうと考えています。","voiceIndex":67,"id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"まだこれから課題もあるし、地域の中で相談しやすい体制をつくっていく点では、ぜひうまく進めてもらいたいと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-021"},{"speaker":"こんの委員","kind":"質問","question":"ヒアリングをして対面式で聞き取りをしてくださっているということで、大変丁寧に聞き取ってくださっているなと思います。そこで少し参考までにお聞きしますが、在宅介護支援センターは７カ所ということで、全体で何カ所のうち７カ所で、なぜここの７カ所で実施されようと思ったのかということを教えてください。","respondent":"松山障害者福祉課長","answer":"やはり具体的に、どのようにこのことを進めていくかというイメージがなかなか湧かないということと、あとは地域バランスを考えまして、６圏域で１カ所以上はというところで選定したものです。","voiceIndex":71,"id":"exchange-022"},{"speaker":"こんの委員","kind":"質問","question":"それを今回、一緒にできるような体制をとってくださるということだと思うのですけれども、いろいろヒアリングの声も出ていましたけれども、今まではどういうふうにそのご相談者の高齢福祉の部分、障害福祉の部分、どのような形でご相談されていたのか、改めて状況を伺います。","respondent":"松山障害者福祉課長","answer":"高齢障害であったり、あとは若くして障害を負っていた２号被保険者の方への対応ですけれども、比較的多いのは、障害を受けて高齢者になられる方というのは多くあります。","voiceIndex":73,"id":"exchange-023"},{"speaker":"こんの委員","kind":"質問","question":"その方が困っていらっしゃる、サービスが必要なところ、手当てをしなければいけないというところが、他課と連携がとりやすい状況であったかどうかというのが、先ほどのお声で１つあったかと思います。では、在支に置くとこういったところはきちんと手当てされていくのか、その辺のところはどうなのでしょうか。","respondent":"松山障害者福祉課長","answer":"もちろん在支ありきではないということは認識しており、民間支援事業所の誘致というのも、やはり推進していかなければならないと考えています。","voiceIndex":75,"id":"exchange-024"},{"speaker":"こんの委員","kind":"質問","question":"先の方向性のお話をいただいてありがとうあります。今、課長がおっしゃった中のワードとして、家族丸ごとという、そこは非常に大事だと思います。ご家族もろもろ見ていくと、生活そのものはどうなのか。そうなると、そのほかの課との連携というのも考えられると思うのですが、その辺はどのようにお考えですか。","respondent":"松山障害者福祉課長","answer":"障害の方はかなり高齢、６５歳以上の方も多くありますし、２号被保険者の方も多くありますので、まずその分野できちんと連携を実践的に図るような形で、具体的に進め、そのほかの分野につきましても同時並行でこれまでの連携を生かしつつ進めていきたいと考えています。","voiceIndex":77,"id":"exchange-025"},{"speaker":"こんの委員","kind":"提案","question":"その連携とともに、先ほどもありましたけれども、研修をしていくというところで、区のサービスをどれだけご存じで、その場で提案できるかというのが非常に大事であると思うのです。いい体制をつくってくださる、これは期待しておりますので、その辺のところのご相談の受け方と対応力と連携のとり方というところをお願いしたいと思いますが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"確かに委員のご指摘のとおり、相談されたときに、相談員の知識や、例えば区の制度の知識、あるいは近隣区を含めた地域資源ですとか、あとはご本人の状況や家族を含めてアセスメントするということ等々、かなり高度な対応力を要求されることかと思います。","voiceIndex":79,"id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、ヒアリングの結果では、在宅介護支援センター７カ所に聞き取ったのが１０項目にわたって、寄せられた意見が書かれているのですけれども、聞き取りというのは大まかにこの項目でどういうご意見ですかという、そういう感じで対面で聞かれたということなのでしょうか。","respondent":"松山障害者福祉課長","answer":"お答えになった方というのは、在支の場合は管理者の方とケアマネージャーと聞いております。","voiceIndex":82,"id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"この７カ所がゆくゆく指定特定相談支援事業所を併設する可能性のある在支というふうになっているのでしょうかということが１つと、それから、在支のケアマネがそのまま障害者のケアプランを組むというのは、なかなか難しいという意見が多く出ていると先ほどのご報告でもありましたけれども、そういうことで言うと、在支で指定特定相談支援事業所を一緒にやると言っても。","respondent":"松山障害者福祉課長","answer":"指定特定相談支援事業所の基準ですけれども、管理者１人、これは兼務が可能だと考えています。は相談支援専門員は専従ということで１名以上ということになっています。","voiceIndex":84,"id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もともと持っている資格と、実務経験というのがあると思うのですけれども、そのもともと持っている資格というのはどういう資格で、実務経験がどれくらい必要になるのかということを教えていただきたいのと、あとはそれを研修したからといってすぐにそのまま新しいところにぽんと行くというふうにはなかなかならないのではないかと思うのですけれども。","respondent":"松山障害者福祉課長","answer":"区といたしましては、どういった研修が必要なのかということも、拠点相談支援センターに専門員がおりますので、どういったカリキュラムを組んだほうがいいのか、研修プログラム等も含めまして、またご意見を頂戴しながら考えていきたいと思っています。","voiceIndex":86,"id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"東京都の研修を受けて、さらに研修をしながら、それで配置されるというふうなことになってくるということですけれども、考え方としては、在支ありきではないということで、これから自立支援協議会にこのことも報告をしながら、またさらにヒアリングも進めながら、いろいろ検討されて方向が出されていくと思うのですけれども、もしも在支と一緒にやるというふうなことになるとしても。","respondent":"松山障害者福祉課長","answer":"今後課題をもう少し明確に整理して、１つずつ解決策があるのかどうかというのは、ご意見を頂戴しながら考えていくということになろうかと思います。","voiceIndex":88,"id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そして広く障害者の皆さんからご意見を伺うという形にぜひしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"委員ご指摘のとおり、来年度につきましては、障害児者の方に対しましてアンケートを、今後の計画に向けて実施する予定です。","voiceIndex":90,"id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今回在支にもしも併設するというふうになったときに、やはり連携というのはかなりされていく、どちらにしても、本当に障害と高齢は切り離せない部分があるので、連携というのはそうでなくてもされる部分というのがあると思うのですけれども、そういう点で言うと、さまざまなところで申し上げてきたのですけれども、地域包括支援センターで、やはり保健師や社会福祉士や主任ケアマネという。","respondent":"松山障害者福祉課長","answer":"ただ、現実的にはこれからということになりますので、具体的には１つずついろいろな課題をクリアしながら進めていきたいと考えています。","voiceIndex":92,"id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"本当に今、課長が言われたように、障害を持っている方は医療にかかる割合も多いですし、欠かせないところでもあると思いますので、私はこれを機会にぜひ、併設ということになるのであれば、保健師、社会福祉士、主任ケアマネの３職種配置の地域包括支援センターという形でぜひつくっていただきたいということで、要望にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-033"},{"speaker":"若林委員","kind":"確認","question":"確認です。２ページの6)の地域ケア会議でのケース協議ということで、これは在支の方から拠点相談支援センターの方に対する目線で、障害の担当の方が業務的にいっぱいで相談しにくいのが現状と、こういう区の認識はありますか。","respondent":"松山障害者福祉課長","answer":"ケース会議についての認識ですけれども、実際に障害者の拠点相談支援センターの中には、非常に業務が多忙であるということで、ご自分たちもそう思っている部分がありますが、これが全ての意見なのかというと難しい部分もあると思います。","voiceIndex":96,"id":"exchange-034"},{"speaker":"石田（秀）委員長","kind":"提案","question":"ほかによろしいですか。私から１つだけ確認させてください。それがいい、悪いと言っているのではなくて、私の聞き違いかもしれないので確認します。そこの確認だけ教えていただきたい。","respondent":"松山障害者福祉課長","answer":"確かに、総合支援施設は指定管理ということなので、指定管理者が施設をまず活用していただきまして、当然ながら総合支援施設ですので、指定管理者と区が連携をとりながら、一緒に福祉カレッジも含めまして、研修をしてまいりたいと考えています。","voiceIndex":98,"id":"exchange-035"}]},{"id":"topic-05","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"国保の問題でこの質問をお願いしたいということなのですけれども、１点は子どもの均等割無料化を求めますということでの質問に対して、区から、子どもの均等割を無料化するとなると、一般会計の法定外繰入を増やすことになると、そして国から、法定外繰入は削減・解消すべきということを言われているので、それをさらに増やすようなことはできないので、子どもの均等割無料化はできないという。","respondent":"三ツ橋国保医療年金課長","answer":"これまでも区は納付相談や財産調査など丁寧に実施し、必要に応じて執行停止も実施しており、今後も留意事項を踏まえ、判例・法令等を遵守し、適正な滞納処分に努め、国保制度の安定性や公平性を引き続き図ってまいります。","voiceIndex":102,"id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"直接給与や年金を差押さえる場合は、この１０万円であるとか、プラス４万５,０００円というのは残しますということで、以前もそういう答弁があったのですけれども、ただそれが預金口座に入ってしまった場合は差押さえることができるという考え方、それで改めていいのでしょうか。","respondent":"三ツ橋国保医療年金課長","answer":"２番目の質問、差押禁止の部分ですが、副委員長が先ほど言われましたように、預金に入った場合は転化される、私も申し上げましたが、その部分ですので、今までどおりのことを実施してまいります。","voiceIndex":105,"id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"主張だけします。区長が判断すれば、国が削減・解消すべき法定外繰入というものではないところでできるということなので、私はぜひ、ほかの自治体でもされているわけですから、保険料減免額に充てる、国もそういうところでは言えないわけです。","respondent":"三ツ橋国保医療年金課長","answer":"生活が厳しい方につきましては、今までも必要に応じて執行停止、また生活保護や就労支援へのご紹介を実施しております。引き続き、個々に応じた納付相談など、窓口や電話にて丁寧に対応してまいります。","voiceIndex":109,"id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3526#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":56594,"voices":121}},{"id":"h30-20181211-8","meetingId":"h30-cm12","date":"2018年12月11日","dateIso":"2018-12-11","committee":"建設委員会","time":"午前１０時００分～午前１１時４８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)平成３１年１月区営住宅入居者募集","agenda":"はじめに、(1)平成３１年１月区営住宅入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"区営住宅の募集は７月と１月の年２回だと思いますけれども、直近の７月の募集戸数と入居者数の数字があれば伺いたいと思います。この間、倍率が５０倍を超えて推移しているのですけれども、この倍率について、区は倍率が高いと考えているか、低いと考えているか、伺います。","respondent":"森住宅課長","answer":"７月の募集の結果ですが、１１戸募集しておりまして、９戸で入居済み、２件が審査中です。倍率は５０倍を超えていて、基本的には高い倍率だと認識しております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"応募件数がもしわかれば後で教えてください。いわゆる若い世代はどれだけ家族向けについて募集しているのか知りたいので伺います。あわせて、単身・家族向けにかかわらず、応募者の所得の程度というか、所得分布は区としては把握や分析しているのでしょうか、伺います。","respondent":"森住宅課長","answer":"それ以下の方が残りの４０％になります。収入の内訳ですが、１０月現在の状況ですが、一番収入の低い第１分類の方が７９.４％、３４０世帯です。年齢構成については、６５歳以上の方が６０％ということで、高齢の方が多いと考えております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"２０代・３０代・４０代・５０代の方は大体何％になるか伺います。そもそも若者は単身者向けには応募資格がないと。単身の若者が実態として高家賃のため品川区内で暮らすことは大変厳しいハードルがあるという今のこの状況は問題ではないのか、区の認識を伺います。その改善の何らかの施策を講じる必要があると思うのですけれども、いかがでしょうか。","respondent":"森住宅課長","answer":"割合としては全部合わせますと７０程度ですので、確かに入居者の方の高齢化が進んでおりまして、若者の世代が入るところがなかなかないですけれども、基本的には区としては、民間住宅ストックが大分ありますので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"この状況について問題意識と言いますか、少し問題・課題があるのではないかと思うのですけれども、いかがでしょうかと伺いましたので、もう一度お答えください。","respondent":"森住宅課長","answer":"今後、居住支援協議会等も含めまして、そういった住宅確保が難しい方のためにどういう施策がとれるのか検討していきたいと思います。","voiceIndex":11,"id":"exchange-004"}]},{"id":"topic-02","title":"西五反田二丁目地区のまちづくり","agenda":"西五反田二丁目地区のまちづくり","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、駐車場が目黒川の両岸にあったと思うのですけれども、それは両岸の駐車場を撤去することになったのでしょうか。目黒川沿いの歩道の整備時期は大体いつごろを想定しているのか。パーク２４の本社ビルとしてということですけれども、細かいことで申しわけないですが、新日鉄興和が持っているビルにパーク２４が賃貸で入って本社ビルになるのでしょうか、伺います。","respondent":"稲田都市開発課長","answer":"駐車場の撤去の範囲なのですけれども、これは目黒川の、高速道路の脇のパーク２４側の通りと、それから、向かい側の大崎橋から五反田大橋までの路上の時間貸し駐車場ですけれども、それをなくそうかと、今まさに警視庁と協議中でして。","voiceIndex":17,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"２０１７年２月の建設委員会で質疑があったときに、大街区化のプランをつくった段階で、大きな地主やそういう可能性のある企業には回って、このプランのＰＲをしたというご答弁があったのですけれども、この大街区化というプランは、にぎわいゾーンの中あるいは区内でほかに大街区化を進めようと働きかけているところや、アンケートをとっているようなところなどが具体的にあるのでしょうか、伺います。","respondent":"稲田都市開発課長","answer":"広報紙等でこの大街区化というのをこの地区でプランをつくりましたということで、２回ほど話は出しております。それから、西五反田一丁目のほうも大街区化できないかということで調査等は進めております。","voiceIndex":19,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"一丁目のほうの調査というのはどのような調査というか、どのような段階なのか。一丁目のほうからもそういった要望が出ているということなのでしょうか伺います。","respondent":"稲田都市開発課長","answer":"特に地元からやりたいとかそういう要望があるわけではありませんが、この地区は区画整理等はやられているのですが、狭隘な敷地であることから、適した場所があるかどうかということで、建物の老朽度とか道の幅とか、そういう部分を調査している状況です。","voiceIndex":21,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"この敷地の大街区化によって１３階６５メートルということで、高さについてはほぼ１.５倍になって、容積もそれにともなって相当な大きさになったと思います。私はこういった手法を完全否定するつもりはないのですけれども、こういった手法を一般化して機械的に広げることはできないし、やるべきではないと思うのですけれども、区のお考えをお伺いします。","respondent":"稲田都市開発課長","answer":"ただ、むやみやたらに進めるものではなくて、やはり権利者であります地域の皆様方が相談に来たり、どうかというところで、区は地域の皆様方の意見を聞きながらやっている状況です。","voiceIndex":23,"id":"exchange-008"},{"speaker":"筒井委員","kind":"質問","question":"この大街区化促進に向けてのプランを五反田で行おうとしている取り組みなのですけれども、この範囲内のところには、有名な会社や銀行もありながら、そうではない会社のビルなどもあると思うのですけれども、今そのプランについての合意形成はどのぐらい進んでいるのでしょうか。","respondent":"稲田都市開発課長","answer":"そういう中で、地区の方々が自分たちの建物も古くなったし、道も狭いし、どうしたらいいかと、そういう話が出てくれば、この大街区化という考え方もあるということで進めております。","voiceIndex":25,"id":"exchange-009"},{"speaker":"筒井委員","kind":"質問","question":"将来的には都市計画決定とかそういうことになっていくのですか。","respondent":"稲田都市開発課長","answer":"今回のこの大街区化のプランに基づいてということでは、都市計画決定をするとかいうものではありませんで、その他の都市計画の手法を取り入れたほうがいいというまちづくりになれば、都市計画決定するとかいう場面が出てくるかと思いますが。","voiceIndex":27,"id":"exchange-010"},{"speaker":"筒井委員","kind":"提案","question":"そのプランどおりになるのは大体どのくらいを予定しているのですか。それとも提案しただけであって、ガチガチにプラン通り完成することは求めていないのでしょうか。そのあたりの区のお考えをお知らせください。","respondent":"稲田都市開発課長","answer":"委員おっしゃったように、打ち上げただけというのは無責任過ぎるのですが、このまちはこのような状況ですので、地域の皆さんに、こういうまちづくりをやってはどうですかという提案をしているものですので、いつまでに完成とか。","voiceIndex":29,"id":"exchange-011"},{"speaker":"大沢委員","kind":"質問","question":"パーク２４が新社屋になるということで、駐輪場を、機械式のパラソル型みたいなものを、モデルケースとしてここのところにつくるということなのですけれども、今後まちづくりの手法として、一企業を応援云々かんぬんというのは抜きにした場合、地下にある程度の規模の駐輪場をつくる場合に、そのパラソル型の、周りに対する地盤等々の影響は大丈夫なのですか。","respondent":"稲田都市開発課長","answer":"この地下の利用というのはこれからいろいろと有効に考えていかなければいけないです。そういう意味では、地下を掘るということは周辺の地盤への影響は当然考えなければいけません。","voiceIndex":31,"id":"exchange-012"},{"speaker":"大沢委員","kind":"質問","question":"ただ、かたいところばかりではなくて埋め立てた場所もあるでしょうし、地盤がやわらかいところもあるでしょうけれども、そのあたりのところで、これが設置できる場所と設置できない場所はあるのでしょうか。それとも、技術面が発達しているのでどこでもオールマイティにこのような駐車場はつくることができるのでしょうか、どちらですか。","respondent":"稲田都市開発課長","answer":"ただ委員おっしゃったように、予期せぬこともありますので、つくれる場所、つくれない場所、例えば、地下水位が高過ぎて浮力が生じてしまってなかなか難しいとか、そういう現象があるかもしれませんし、必ずしもできるとは今この場では言えませんけれども。","voiceIndex":33,"id":"exchange-013"},{"speaker":"あくつ委員","kind":"質問・要望","question":"教えていただきたいのですけれども、平成２６年のプランの資料と今の資料を見比べていて、確認なのですけれども、このオープンスペースの整備というところを見ると、先ほどご説明にもあったように、時間貸し駐車場をなくして、これは一方通行だったものを両面通行にして交通利便性の向上を図るということなのか、両面通行になるということなのでしょうか。","respondent":"稲田都市開発課長","answer":"そこを今回整備しまして、車の出入り口も北側の方に持っていき、歩道をつけて安全な通行をするという形で考えております。それと、河川管理用の通路もだぶりますが、現在区道として供用しているところですので、基本的には区の道路管理者と協議します。","voiceIndex":37,"id":"exchange-014"},{"speaker":"横山委員","kind":"確認","question":"１点だけ確認なのですけれども、このあたりの地域は、浸水ハザードマップを見ますと、浸水時の水の深さが１～２メートルあたりで、近隣が２メートル以上なのですけれども、地下２階が全て機械式駐車場なのでしょうか。例えば、増水の際にはどのようになるのか確認させてください。","respondent":"稲田都市開発課長","answer":"駐車場は機械式駐車場です。委員ご指摘のとおり、ここは目黒川沿いですので、そういう浸水対策ということで、浸水防止板といったもので対応します。","voiceIndex":39,"id":"exchange-015"}]},{"id":"topic-03","title":"第二戸越幹線整備工事（上流部）ついて","agenda":"第二戸越幹線整備工事（上流部）ついて","exchanges":[{"speaker":"横山委員","kind":"質問","question":"１点お伺いします。こちらの全体事業の完了見込が平成３６年度なのですけれども、こちらは将来的な接続管の部分も含めての予定でしょうか。その場合、１時間５０ミリを超える雨量に対してもということですけれども、５０ミリ、７５ミリとかそれぐらい対応ということで想定されているのでしょうか。現在わかる範囲で教えてください。","respondent":"持田河川下水道課長","answer":"１点目の事業の終了見込の平成３６年度というスケジュールは、今ご質問いただいたとおり、上流部から下流部までのシールドと、あとその接続の部分も含めての予定で今のところ進めております。","voiceIndex":45,"id":"exchange-016"},{"speaker":"安藤委員","kind":"確認","question":"戸越第一幹線にその宮前坂広場のほうからつなげるということなのですけれども、その戸越幹線のさらに下をシールド工法でトンネルが通るということでよろしいのか。そこも確認させてください。それと、シールド工法による住民への影響はあるでしょうか。そのあるなしを含めて、その工事の住民への説明はどのようになされるのかお伺いします。","respondent":"持田河川下水道課長","answer":"２点目の工事の影響ですが、工法はあまり地上等には影響ができるだけ出ないものを選んでいますが、万が一もありますので、施工前にはいわゆる家屋調査をして、施工後何かあれば当然そこで再度調査をしてという対応をとるように進めております。","voiceIndex":48,"id":"exchange-017"}]},{"id":"topic-04","title":"ヒカリの水辺プロジェクト","agenda":"ヒカリの水辺プロジェクト","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"恐らくタイマーだと思うのですけれども、どういう形でやっているのか。これは買い取りという形になっているのか、メンテナンス等の契約みたいなものは結んでいるのか。要するにいろいろなところで同時に点灯するということで、どういうふうにやっているのかいつも疑問に思っていたのですけれども、それについて教えてください。","respondent":"持田河川下水道課長","answer":"メンテナンスにつきましては、設置した後にはそういったメンテナンスの契約が必要と考えておりまして、今年度設置ですので、来年度になりましたらそういった設置されたもののメンテナンスですとかいう形での別途契約をして、メンテナンスをしていく予定です。","voiceIndex":54,"id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問","question":"イベントのときに配色を変えるということなのですけれども、色の変化ですとか動きのあるという。大崎のあたり、目黒川を見ていても、すごくきれいだなと思うのですが、こういったものについては誰が調整をして、事業者にお願いするのか、それとも区の職員が簡単に完璧にできるような仕組みになっているのか教えてください。","respondent":"持田河川下水道課長","answer":"今のところ所管のほうで想定していますのが、メンテナンスの中で色の変化等はそれほど難しい作業ではなくて、コンピュータの切りかえで可能と聞いておりますので、ある期間からある期間までは何色でということを区で決めて、その期間だけ色を変えるですとか。","voiceIndex":56,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"東京２０２０大会のことが書いてあって、常設とあるのですけれども、機械は設置したら無期限で運用していくものなのか伺います。それと、今回の整備計画３つですけれども、この経費は幾らぐらいなのか。先ほどメンテナンスの契約という話もありましたけれども、それも含めてどれぐらいになるのでしょうか。そして、国や都や区の負担割合はそれぞれ何％ぐらいになるのか、わかればお伺いします。","respondent":"持田河川下水道課長","answer":"１点目の期間ですが、今回常設ということで、基本的には設置しましたらずっとと言いますか、大会後も含めまして水辺のにぎわいということを考えていますので、一般的な照明のようなイメージで、基本的には夜になればライトアップしていくというように考えております。","voiceIndex":60,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"結構区が単費で出しているなと思ったのですけれども、８,６００万円とか９億という話がありましたけれども、イニシャルコストとランニングコストという点では、もう少しどういう感じになるのか、設置したときにはこれぐらいかかって、毎年これぐらいかかってしまうというのがあれば、もう少し教えてください。","respondent":"持田河川下水道課長","answer":"ランニングコストについては、先ほど申しましたが、全部ライトが完成した暁には毎年１,０００万～２,０００万ぐらいの維持管理費がかかってくると考えております。","voiceIndex":62,"id":"exchange-021"},{"speaker":"筒井委員","kind":"質問","question":"結構イニシャルコストがかかるものなのだなと思いましたけれども、１度つけたら大体何年ぐらいもつのでしょうか。","respondent":"持田河川下水道課長","answer":"つけてみないとわからないところもありますが、一般的なこういった電気関係のものにつきましては、１０年で全てが壊れるわけではないと思いますが、１０年が１つの目安、耐用年数だと聞いております。","voiceIndex":65,"id":"exchange-022"},{"speaker":"筒井委員","kind":"質問・要望","question":"わかりました。なるべくもちをよくしていっていただきたいと考えています。これは特に京浜運河のところなどに設置する場合、海水の関係でさびとか発生しやすいとか、地域によって耐久の程度は違ってくるものですか。海水の関係とか。教えてください。","respondent":"持田河川下水道課長","answer":"やはり運河のエリアにつきましては、海水の影響は多少はあると考えております。今、設計中ですが、使う製品や電気の接続については、海水がかぶらないようなカバーをするですとか、そういった対応になると考えております。","voiceIndex":67,"id":"exchange-023"},{"speaker":"松永副委員長","kind":"質問","question":"私からは整備概要のライトアップ箇所についてなのですが、新品川橋と品川橋、荏川橋と箇所がばらばらになっているのですけれども、その理由について教えてください。もう一つは、新品川橋に関しては、イメージのほうなのですけれども、これを見ていると上のほうもライトアップしたほうがいいのではないかと思うのですが、いかがでしょうか。","respondent":"持田河川下水道課長","answer":"次に新品川橋の桁につきましては、橋梁の高欄が縦の転落防止の柵はなく、横方向の柵が３本ほどあって、ライトアップの効果が出にくいと所管では考えておりまして、ここについては桁のライトアップのみにしたところです。","voiceIndex":69,"id":"exchange-024"},{"speaker":"松永副委員長","kind":"質問","question":"この３つの橋についてなのですが、この桁側面と高欄は、先ほどの説明でわかったのですが、ライトアップ箇所は下と横の部分ということで、３橋に関して、何でこういうふうに分けたのかお伺いしたので、それについて伺いたいのですが。","respondent":"持田河川下水道課長","answer":"そういったデザインも生かせるようにということで、その２橋については高欄のライトアップをするというコンセプトで考えております。","voiceIndex":71,"id":"exchange-025"},{"speaker":"大沢委員","kind":"質問","question":"旧東海道の品川宿のこのあたり、ライトアップということは、明るくすることが目的なのですか、それとも、周りの暗さを醸し出すのが主眼なのか、どちらに力点を置いてこの事業を進めようとしているのですか。","respondent":"持田河川下水道課長","answer":"ただ、当然周辺の環境等もありますので、明るくし過ぎることについても、これは影響がありますので、所管として考えましたのが、ある程度暗い中で橋梁だけがぽっと浮かび上がるような形のライトということで、今回はこの桁および高欄のライトアップを考えました。","voiceIndex":73,"id":"exchange-026"},{"speaker":"大沢委員","kind":"質問","question":"暗さゆえの文化というのもあるので、そこら辺は、旧東海道周辺は歴史のあるところなので、よろしいかなと思うのですけれども、そこのところはどうお考えですか。","respondent":"持田河川下水道課長","answer":"護岸につきましても、ライトアップはやっていきたいと考えていますが、護岸にツタが垂れ下がっているところがあったり、また護岸も場所によって状況が変わります。護岸も明る過ぎるとまたまぶしいということもありますので、照らし方など慎重に検討していきます。","voiceIndex":75,"id":"exchange-027"},{"speaker":"松永副委員長","kind":"質問・要望","question":"私はここら辺の地域ではないので、この地域の方に怒られてしまうかもしれないですけれども、必ずしも明るさだけが美しいものを醸し出すわけではなくて、ましてやこの地域は歴史のある場所なので、そのあたりのところの強弱を加味しながら、将来的に進めていっていただきたいと、これは要望で、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-028"}]},{"id":"topic-05","title":"本日は防災対策","agenda":"本日は防災対策","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"主催は避難所連絡会議ということなので、区民防災組織ということですから、大分そこのところを意識されたのかなと思って、本当に実践的な訓練が行われたなと私自身は思っています。以前議会でも何度か要望しましたけれども、障害者の方の団体に直接お話を伺うことは予定されているのかどうか、まずそこを確認します。","respondent":"古巻防災課長","answer":"障害者団体のご意見の反映ということですけれども、今現在、障害者福祉課と協議いたしまして、今、１３の障害者団体にアンケートを実施しています。このアンケートの結果を踏まえて、内容について運営マニュアルに反映していくことで考えております。","voiceIndex":82,"id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問・要望","question":"わかりました。１３団体ということで私たちが考えていたよりも幅広くお声を取り入れるのかなと思うのですけれども、やはり直接面と向かってお話を伺わないとわからない部分もあると思いますので、１３団体とは言わないまでも、できれば少しお話を伺っていただきたいと要望しておきます。これは答弁は結構です。多分そういう声はあると思うのですが。","respondent":"古巻防災課長","answer":"とは言っても今現在の基準で言うと、３.３平米に２人と今ご紹介いただきましたけれども、そういう形で面積換算しておりますので、現実的な物理的な制約もある中で、いかに工夫していくか、そこは避難所というか学校も含めた。","voiceIndex":84,"id":"exchange-030"},{"speaker":"あくつ委員","kind":"質問・要望","question":"いっぱいあるのですが、とりあえずそれだけ申し上げておきます。それから、今回の新しい防災ハンドブックのほうで若干伺います。このデザインを見ると、東京防災のような非常に親しみやすいデザインに変わったなと感じているのですけれども。すごく基礎的というか単純なことなのですが、今までわが家の防災ハンドブックだったのが、しながわ防災ハンドブックに変わった理由について伺います。","respondent":"古巻防災課長","answer":"今までわが家の防災ハンドブックということで、「わが家」ということをタイトルとして載せておりましたけれども、もう少しさまざまな観点からということもあって、「品川区の防災ハンドブックです」ということが前面に出るようなタイトルに変えたという考え方です。","voiceIndex":86,"id":"exchange-031"},{"speaker":"あくつ委員","kind":"質問","question":"もう一つだけ伺います。今後のスケジュールで、来年５月中旬から６月中旬にかけての配布ということなのですが、先ほども若干ご説明あったのですけれども、浸水ハザードマップについては、これも議会で何度もご答弁いただいているのですが、かなり古い東京都のデータを使っているということで、更新に間に合う、これには反映されるということでよろしいでしょうか。","respondent":"古巻防災課長","answer":"今現在、東京都の正式な公表の時期がまだ出ていないのですけれども、基本的にはそれに間に合わせて更新をかけるというスケジュールで考えております。","voiceIndex":88,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"ですから、防災対策というのは、予防となる防災対策が何と言っても中心に座っていなくてはならないことを前提にしつつ伺います。災害で戻る家を失って、こういった避難所もそうですが、仮の住まいでの生活を余儀なくされる方というのは出てくると思います。この避難所運営における行政の役割とか責任について、災害救助法との関係でどのように考えておられるか、改めてお伺いします。","respondent":"古巻防災課長","answer":"避難所運営に関しての区の役割・責任ですけれども、基本的には避難所は区が指定するものですから、最終的には区が責任を負うというのが、法的なたてつけではそういったことになると思っていますので、今ご質問いただいた点については。","voiceIndex":90,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"それは大事な視点だと私も思っています。ぜひ、災害救助法ということで、そちらの責任を果たせるような役割をこれからも努力していただきたいと思います。少し伺いたいのは、新たにマニュアルに加える視点ということで、要配慮者、女性、子ども、ペットに関する対応等がありますけれども、具体的にはどういうことを反映していくのでしょうか、そこら辺をもう少し伺いたいと思います。","respondent":"古巻防災課長","answer":"具体的な中身については、今、目次でしかお示ししていませんけれども、例えば、要配慮者に関しましては、基本的なスペースの決定に関しての考え方、段差や上下移動が少ない低層階にしてくださいとか。","voiceIndex":92,"id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"今回私は三木小に参加したのですが、確かに避難行動要支援者の方の部屋が１階に配置されていまして、ここですということでご案内もありました。そして、そこで交流が生まれると。それと、体を動かしやすいという点でも段ボールベッドの配備ですね、それはこのマニュアルの中にどのようにガイドラインとして入っているのか伺います。","respondent":"古巻防災課長","answer":"トイレにつきましても、数はできる限り避難者全体の中で足りるような数を確保するように努めているところですし、また、仮設トイレ等も備蓄している中で、なるべくトイレが足りなくならないような形での確保を今後も進めていきたいと思います。","voiceIndex":94,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"寝食分離のところは、アドバイザーからはそういうアドバイスがあったということなのですが、やはりある程度実際の避難所の運営に反映されていかないと意味がないと思うのですけれども、ぜひ、そういうアドバイスもあったわけですから、具体的にそういった視点を改定の中に入れていただきたいと思うのですけれども、いかがでしょうか。いざというときに１２万人分の確保というのは難しいのでしょうか。","respondent":"古巻防災課長、曽田災害対策担当部長","answer":"さまざまな避難所運営に関することについては、優先度を考えながら進めることも重要だと思いますので、必要なところ、生活に密接にかかわるところについて、まず、食べる、飲む、トイレの問題。実際にどうなるかと言いますと、発災後、全国を見て、被害を受けていない会社で協定先が作成を開始します。それから配布するということですから、時間的にも量的にも全然足りないのです。協定を結んでいるのは品川区だけではありません。","voiceIndex":96,"id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"キューバだってすごくやっていますよね。ですので、段ボールベッドというのはそういう意味では、避難所生活を整える上で最低限必要だと思っていますので、今の協定だけですと不十分だなということがわかりましたので、ぜひ必要数はどれぐらいなのかを定めた上で、それを確保できる方策をこれから整えていただきたいと要望したいと思います。最後の質問ですが、ハンドブックのほうから１点だけ質問します。","respondent":"古巻防災課長","answer":"今ご質問のあった事項ですけれども、６章の「(1)区の取り組み」の中に、各ご家庭への助成ということで制度一覧を掲載しまして、お問い合わせ先も庁内のしかるべき所管をご紹介する形で、わかりやすく掲載する予定ですので、そのように進めております。","voiceIndex":99,"id":"exchange-037"},{"speaker":"横山委員","kind":"提案","question":"何点かお伺いします。避難所運営マニュアルなのですけれども、上下水道の安全点検や確認についてなのですが、こちらはマニュアルのほうにどういった状況によってこうしてくださいという内容は掲載されていくのでしょうか、教えてください。プールの水の利用方法ですとか、ポンプをどうやって使ったらいいかとか、そういったあたりも掲載されているのか確認できたらと思います。はそちらからお願いします。","respondent":"古巻防災課長","answer":"さまざまな広域の取り組みにつきましては、これからどういった形でそういう仕組みを取り入れられるのか、また、どう取り入れることが効率的なのか、そういったところを十分に、いろいろな事例がありますので、研究を進めてまいります。","voiceIndex":101,"id":"exchange-038"},{"speaker":"横山委員","kind":"確認","question":"最後に、こちらのハンドブックについてなのですけれども、災害時などでもすぐ手にとれるようにということで、一家に１冊配付されるのですけれども、ふだん例えば、携帯電話やパソコンなど、１人１人が家族で確認できるようなデータであったり、スマホ版やアプリなどの展開はどのように考えているのか。こちらは日本語版だけなのでしょうか、多言語の対応をどのように考えているのか教えてください。","respondent":"古巻防災課長","answer":"カタログポケットは基本的には多言語対応ということで、翻訳機能を使ったものですけれども、多言語にも対応して、また、音声でも聞けますので、ひとまずその対応をした上で、冊子としての多言語版・音声つきのものも今後、年度は変わってくると思いますけれども。","voiceIndex":103,"id":"exchange-039"},{"speaker":"横山委員","kind":"質問・要望","question":"要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"私も日曜日に行われた防災訓練に参加しましたけれども、そのとき仮設トイレの組み立て訓練を行いました。あのくみ取り式の仮設トイレは何年前のものでしょうか。と言うのは、今、品川区の組織にない名称が横に書かれていたので結構古いのかなと思ったのですけれども。おおよそでいいのでお知らせください。","respondent":"古巻防災課長","answer":"正確に何年前とは、多分学校によって違うと思います。ただ、かなり前から仮設トイレについては、ほかの避難所も配備していると聞いておりますので、具体的な数字が言えないのですけれども、それなりの年数がたったものだと思います。","voiceIndex":106,"id":"exchange-041"},{"speaker":"筒井委員","kind":"意見","question":"」と聞いたら「使ったことない」という声も聞いたので、そろそろ古いので、あの組立式仮設トイレの洋式化をぜひお願いしたいのですけれども、その点の見解をお知らせください。","respondent":"古巻防災課長","answer":"洋式のものも、委員がご覧になったものとまた違うタイプかもしれませんけれども、洋式の便器をセットするような形の洋式の組立トイレも配備を進めていますので、それと組み合わせて、洋式化については、通常の公衆トイレ等も洋式化のご要望が出ていますけれども、そういった中で。","voiceIndex":108,"id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"よろしくお願いします。この東京防災、東京くらし防災、しながわ防災ハンドブックの３冊、区民の手元に行くのですけれども、どれも重要な内容が書いてあると思うのですけれども、まず区民が読むべき優先順位としては、しながわ防災ハンドブックが最優先になるのでしょうか、その点ご見解をお知らせください。","respondent":"古巻防災課長","answer":"最後の６章以外にも、マンション対策などを踏まえた区の取り組みを記述しておりますので、東京防災、東京くらし防災が一般的な内容とすると、しながわ防災ハンドブックについては、品川区に特化したものと考えております。","voiceIndex":110,"id":"exchange-043"},{"speaker":"松永副委員長","kind":"質問・要望","question":"先ほど、このしながわ防災ハンドブックの外国語版に関しては、後ほど順次やっていくというお話だったのですけれども、避難所運営マニュアルのほうで、外国人への対応というのがないのですけれども、あればあるでいいのですけれども、もしなければつけ加えていただきたいと思うのですが、いかがですか。","respondent":"古巻防災課長","answer":"当然、外国人の方への配慮は、掲示物とか、そういった基本的な配慮については記載していく形で考えていますので、今ご提案いただいたような中身はできるように進めてまいります。","voiceIndex":112,"id":"exchange-044"},{"speaker":"松永副委員長","kind":"質問・要望","question":"もし避難所で通訳が必要であれば私たちを使ってくださいという団体もありますので、ぜひそうした団体の方々との連携も含めて進めていただけたらと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4252#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":30502,"voices":121}}]);
